    @staticmethod
    def _normalizar(texto):
        texto = str(texto or "").lower().strip()
        texto = unicodedata.normalize("NFD", texto)
        texto = "".join(c for c in texto if unicodedata.category(c) != "Mn")
        return " ".join(texto.split())

    def carregar(self):
        self.dados = listar_questoes_lixeira(self.concurso[0])
        self.preencher_tabela()

    def preencher_tabela(self):
        termo = self._normalizar(self.buscar.text())
        dados = list(self.dados)
        if termo:
            termos = [x for x in termo.split() if x]
            dados = [q for q in dados if all(x in self._normalizar(f"{q.get('id')} {q.get('disciplina')} {q.get('topico')} {q.get('enunciado')} {q.get('banca')} {q.get('ano')}") for x in termos)]
        self.tabela.blockSignals(True)
        self.tabela.setRowCount(len(dados))
        for linha, q in enumerate(dados):
            marca = QTableWidgetItem("")
            marca.setFlags(Qt.ItemIsEnabled | Qt.ItemIsUserCheckable | Qt.ItemIsSelectable)
            marca.setCheckState(Qt.Unchecked)
            marca.setData(Qt.UserRole, q.get("id"))
            aplicar_destaque_tabela(marca, "inativo", True)
            self.tabela.setItem(linha, 0, marca)
            enunciado = " ".join(str(q.get("enunciado") or "").split())
            if len(enunciado) > 140:
                enunciado = enunciado[:137].rstrip() + "..."
            valores = [str(q.get("id") or "—"), str(q.get("disciplina") or "—"), str(q.get("topico") or "—"), enunciado, str(q.get("banca") or "—"), str(q.get("ano") or "—")]
            for deslocamento, valor in enumerate(valores, start=1):
                celula = QTableWidgetItem(valor)
                if deslocamento == 4:
                    celula.setData(Qt.UserRole, q.get("id"))
                    celula.setToolTip(str(q.get("enunciado") or ""))
                if deslocamento in (1, 6):
                    celula.setTextAlignment(Qt.AlignCenter)
                aplicar_destaque_tabela(celula, "inativo", True)
                self.tabela.setItem(linha, deslocamento, celula)
            self.tabela.setRowHeight(linha, 34)
        self.tabela.blockSignals(False)
        self.marca_todas.blockSignals(True)
        self.marca_todas.setChecked(False)
        self.marca_todas.blockSignals(False)
        qtd = len(dados)
        self.contagem.setText("1 questão" if qtd == 1 else f"{qtd} questões")

    def alternar_todas(self, estado):
        marcado = estado == Qt.Checked
        self.tabela.blockSignals(True)
        for linha in range(self.tabela.rowCount()):
            item = self.tabela.item(linha, 0)
            if item is not None:
                item.setCheckState(Qt.Checked if marcado else Qt.Unchecked)
        self.tabela.blockSignals(False)

    def ids_marcados(self):
        ids = []
        for linha in range(self.tabela.rowCount()):
            item = self.tabela.item(linha, 0)
            if item is not None and item.checkState() == Qt.Checked:
                ids.append(int(item.data(Qt.UserRole)))
        return ids

    def id_selecionado(self):
        ids = self.ids_marcados()
        if len(ids) == 1:
            return ids[0]
        linha = self.tabela.currentRow()
        if linha < 0:
            return None
        item = self.tabela.item(linha, 4)
        return item.data(Qt.UserRole) if item is not None else None

    def visualizar(self):
        qid = self.id_selecionado()
        if qid is not None:
            JanelaVisualizarQuestao(qid, self).exec()

    def restaurar(self):
        ids = self.ids_marcados()
        if not ids:
            qid = self.id_selecionado()
            ids = [qid] if qid is not None else []
        if not ids:
            QMessageBox.information(self, "Lixeira", "Selecione pelo menos uma questão.")
            return
        try:
            fazer_backup("antes_restaurar_questoes_lixeira")
        except Exception as erro:
            QMessageBox.critical(self, "Backup", f"A operação foi cancelada porque o backup falhou.\n\n{erro}")
            return
        for qid in ids:
            restaurar_questao_da_lixeira(qid, reativar=True)
        self.carregar()

    def excluir_permanente(self):
        ids = self.ids_marcados()
        if not ids:
            qid = self.id_selecionado()
            ids = [qid] if qid is not None else []
        if not ids:
            QMessageBox.information(self, "Lixeira", "Selecione pelo menos uma questão.")
            return
        resposta = QMessageBox.question(
            self,
            "Excluir permanentemente",
            (
                f"Excluir permanentemente {len(ids)} questão(ões)?\n\n"
                "Essa ação não pode ser desfeita."
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No
        )
        if resposta != QMessageBox.Yes:
            return
        try:
            fazer_backup("antes_excluir_permanente_lixeira")
        except Exception as erro:
            QMessageBox.critical(self, "Backup", f"A operação foi cancelada porque o backup falhou.\n\n{erro}")
            return
        for qid in ids:
            excluir_questao_permanentemente(qid)
        self.carregar()

    def esvaziar_lixeira(self):
        ids = [int(q.get("id")) for q in listar_questoes_lixeira(self.concurso[0]) if q.get("id") is not None]
        if not ids:
            QMessageBox.information(self, "Lixeira", "A Lixeira já está vazia.")
            return

        resposta = QMessageBox.question(
            self,
            "Esvaziar lixeira",
            (
                f"Excluir permanentemente todas as {len(ids)} questão(ões) da Lixeira?\n\n"
                "Esta ação não pode ser desfeita. O Vighna fará um backup antes de continuar."
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No
        )
        if resposta != QMessageBox.Yes:
            return

        try:
            fazer_backup("antes_esvaziar_lixeira_questoes")
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Backup",
                f"A operação foi cancelada porque o backup falhou.\n\n{erro}"
            )
            return

        removidas = 0
        for qid in ids:
            if excluir_questao_permanentemente(qid):
                removidas += 1

        self.carregar()
        if removidas != len(ids):
            QMessageBox.warning(
                self,
                "Esvaziar lixeira",
                f"{removidas} de {len(ids)} questão(ões) foram excluídas permanentemente."
            )


