class _AudioXenoArquiteturaB26R2:
    """V3: cinco WAV embutidos, baixa latencia e fallback WinMM no Windows.

    Controlador isolado da logica das questoes. Nao usa banco de dados,
    nao cria timers recorrentes e nao bloqueia o teclado ao tocar sons.
    """

    _GANHOS = {"seta_cima": 0.66, "seta_baixo": 0.66,
               "acerto": 0.92, "constelacao": 0.72, "combo5": 0.87, "proxima_questao": 0.76}

    def __init__(self, parent):
        self._parent = parent
        self._arquivos = {}
        self._efeitos = {}
        self._falhas = set()
        self._usando_winmm = False
        self._preparado = False
        self._volume_setas = 24
        self._volume_recompensa = 45
        self._volume_transicao = 32
        self._ultimo_setas = 0.0
        self._ultimo_aviso = False

    def ajustar_volumes(self, setas, recompensa, transicao=32):
        self._volume_setas = max(0, min(100, int(setas)))
        self._volume_recompensa = max(0, min(100, int(recompensa)))
        self._volume_transicao = max(0, min(100, int(transicao)))
        for nome, efeito in self._efeitos.items():
            try:
                efeito.setVolume(self._volume_efetivo(nome))
            except RuntimeError:
                pass

    def _volume_efetivo(self, nome):
        volume = (self._volume_setas if nome.startswith("seta_") else
                  self._volume_transicao if nome == "proxima_questao" else
                  self._volume_recompensa)
        return max(0.0, min(1.0, volume/100.0*self._GANHOS.get(nome, 1.0)))

    @staticmethod
    def _cache():
        local = os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()
        pasta = Path(local) / "VighnaStudy" / "Cache" / "sons_xenoarquitetura_v3"
        pasta.mkdir(parents=True, exist_ok=True)
        return pasta

    def preparar(self):
        if self._preparado:
            return
        self._preparado = True
        try:
            pasta = self._cache()
            for nome, (arquivo, digest, dados) in _B26R2_AUDIO_V3.items():
                caminho = pasta / arquivo
                valido = (caminho.is_file() and
                          hashlib.sha256(caminho.read_bytes()).hexdigest() == digest)
                if not valido:
                    conteudo = zlib.decompress(base64.b64decode(dados))
                    if hashlib.sha256(conteudo).hexdigest() != digest:
                        raise ValueError("hash de audio divergente")
                    temporario = caminho.with_suffix(f".{os.getpid()}.tmp")
                    temporario.write_bytes(conteudo)
                    temporario.replace(caminho)
                self._arquivos[nome] = caminho

            if QSoundEffect is not None:
                for nome, caminho in self._arquivos.items():
                    som = QSoundEffect(self._parent)
                    som.setLoopCount(1)
                    som.setVolume(self._volume_efetivo(nome))
                    som.setSource(QUrl.fromLocalFile(str(caminho)))
                    self._efeitos[nome] = som
            # Se QtMultimedia nao fizer parte do EXE, usa WinMM em Windows.
            self._usando_winmm = not bool(self._efeitos)
        except Exception as erro:
            self._falhas.add("preparar")
            self._preparado = False
            self._arquivos.clear()
            self._efeitos.clear()
            if not self._ultimo_aviso:
                print("Audio Neural V3 indisponivel:", erro, file=sys.stderr)
                self._ultimo_aviso = True

    def _wav_volume_winmm(self, nome):
        """Atenuacao PCM somente no fallback, sem alterar volume do Windows."""
        caminho = self._arquivos[nome]
        volume = self._volume_efetivo(nome)
        if volume >= 0.995:
            return caminho
        alvo = caminho.with_name(f"{caminho.stem}_gain{round(volume*1000):03d}.wav")
        if alvo.exists():
            return alvo
        with wave.open(str(caminho), "rb") as origem:
            parametros = origem.getparams()
            pcm = origem.readframes(origem.getnframes())
        if parametros.sampwidth != 2:
            return caminho
        numeros = array.array("h")
        numeros.frombytes(pcm)
        if sys.byteorder != "little":
            numeros.byteswap()
        for indice, amostra in enumerate(numeros):
            numeros[indice] = round(amostra * volume)
        if sys.byteorder != "little":
            numeros.byteswap()
        temporario = alvo.with_suffix(f".{os.getpid()}.tmp")
        with wave.open(str(temporario), "wb") as destino:
            destino.setparams(parametros)
            destino.writeframes(numeros.tobytes())
        temporario.replace(alvo)
        return alvo

    def _tocar_winmm(self, nome):
        if sys.platform != "win32":
            return
        caminho = self._wav_volume_winmm(nome)
        # SND_FILENAME|SND_ASYNC|SND_NODEFAULT: reproduz sem travar a GUI.
        flags = 0x00020000 | 0x0001 | 0x0002
        try:
            import winsound
            winsound.PlaySound(str(caminho), flags)
        except (ImportError, OSError):
            # Ultimo recurso: chamada direta a biblioteca nativa do Windows.
            ctypes.windll.winmm.PlaySoundW(str(caminho), None, flags)

    def tocar(self, nome):
        if nome not in _B26R2_AUDIO_V3:
            return
        if self._volume_efetivo(nome) <= 0.001:
            return
        if nome.startswith("seta_"):
            instante = time.monotonic()
            if instante - self._ultimo_setas < 0.115:
                return
            self._ultimo_setas = instante
        if not self._preparado:
            self.preparar()
        if nome not in self._arquivos or nome in self._falhas:
            return
        try:
            if not self._usando_winmm:
                som = self._efeitos[nome]
                # Alterar direcao interrompe o clique anterior; evita camadas.
                if nome.startswith("seta_"):
                    contrario = "seta_baixo" if nome == "seta_cima" else "seta_cima"
                    outro = self._efeitos.get(contrario)
                    if outro is not None:
                        outro.stop()
                elif nome in ("acerto", "proxima_questao"):
                    for chave in ("seta_cima", "seta_baixo"):
                        outro = self._efeitos.get(chave)
                        if outro is not None:
                            outro.stop()
                # Status Error indica backend sem audio; WinMM continua funcional.
                if som.status() == QSoundEffect.Status.Error and sys.platform == "win32":
                    self._usando_winmm = True
                    self._tocar_winmm(nome)
                    return
                som.play()
            else:
                self._tocar_winmm(nome)
        except Exception as erro:
            self._falhas.add(nome)
            if not self._ultimo_aviso:
                print("Audio Neural V3 nao reproduzido:", erro, file=sys.stderr)
                self._ultimo_aviso = True

    def parar(self):
        for som in self._efeitos.values():
            try:
                som.stop()
            except RuntimeError:
                pass
        if self._usando_winmm and sys.platform == "win32":
            try:
                import winsound
                winsound.PlaySound(None, 0)
            except (ImportError, OSError):
                try:
                    ctypes.windll.winmm.PlaySoundW(None, None, 0)
                except Exception:
                    pass


class JanelaResolverQuestoes(QDialog):
    def __init__(
        self,
        configuracao,
        parent=None
    ):
        # ``parent`` continua sendo o controlador lógico da origem da sessão,
        # mas não é usado como parent Qt. No Windows, um QDialog pertencente à
        # janela principal vira uma janela "owned": pode desaparecer da barra
        # de tarefas ao minimizar e fica acoplado à navegação do Dashboard.
        # Como top-level real, a bateria pode permanecer aberta enquanto o
        # usuário navega pelo Vighna e depois ser restaurada sem perder estado.
        super().__init__(None)
        self.controlador_origem = parent
        self.setObjectName("questionSolverDialog")

        self.setWindowFlags(
            Qt.Window
            | Qt.WindowTitleHint
            | Qt.WindowSystemMenuHint
            | Qt.WindowMinMaxButtonsHint
            | Qt.WindowCloseButtonHint
        )
        self.setModal(False)
        self.setWindowModality(Qt.NonModal)

        self.configuracao = configuracao
        ciclo_id = configuracao.get("ciclo_questoes_id")
        self.ciclo_questoes_id = (
            int(ciclo_id)
            if ciclo_id not in (None, "")
            else None
        )
        self.estado_ciclo_questoes = None
        self.sem_impacto_inteligencia = bool(
            configuracao.get("sem_impacto_inteligencia", False)
        )
        self.modo_banco_erros = bool(
            configuracao.get("modo_banco_erros", False)
        )
        if self.modo_banco_erros:
            # O próprio contexto impõe isolamento, mesmo que um chamador
            # futuro esqueça de enviar a flag genérica de reforço livre.
            self.sem_impacto_inteligencia = True
        self.fila = list(
            configuracao[
                "fila"
            ]
        )
        self.indice = 0
        self.registros = []
        self.quantidade_planejada_inicial = len(self.fila)
        self.banco_erros_removidas = set()
        # A primeira vez que uma questão é pulada ela retorna ao fim da
        # própria bateria. Se for pulada novamente, passa a equivaler a erro
        # para a inteligência e para a cobertura da revisão.
        self.pulos_por_questao = {}
        self.questao_atual = None
        self.item_sessao_atual_id = None
        self.inicio_questao = None
        self._questao_pausa_iniciada = None
        self._questao_tempo_pausado = 0.0
        self._pausa_relogio = None
        self._pausa_aviso = None
        self._pausa_foco_iniciada = None
        self._pausa_minimizou = False
        self._pausa_config = {"minutos": 10, "minimizar": False, "som": True}
        # B21: histórico em memória durante esta bateria; tempo real via
        # monotonic, imune a ajustes no relógio do Windows.
        self._b21_historico_pausas = []
        self._b21_pausa_ativa = None
        self._pausa_botoes_anteriores = {}
        self._pausa_timer = QTimer(self)
        self._pausa_timer.setInterval(1000)
        self._pausa_timer.timeout.connect(self.verificar_pausa_programada)
        self._pausa_visual_ativa = False
        self._pausa_overlay = None
        self._pausa_overlay_titulo = None
        self._pausa_overlay_tempo = None
        self._pausa_overlay_info = None
        self._pausa_overlay_historico = None
        self._pausa_overlay_estatisticas = None
        self.resposta_confirmada = False
        self._modo_revisao_historico = False
        self._indice_revisao_historico = None
        self._estado_visual_pendente_revisao = None
        self._frames_pendentes_revisao = None
        # Navegação por teclado usa um foco próprio, separado da alternativa
        # efetivamente marcada. Assim, as setas apenas percorrem as opções;
        # selecionar continua sendo uma ação explícita do usuário.
        self._alternativa_foco_teclado = None
        self._filtro_teclado_aplicacao_instalado = False
        self._editando_explicacao = False
        self._editando_alternativas = False
        self.finalizada = False
        self.resultados_integracao = []
        self.resumo_final = None
        self.efetividade_final = None
        self.proxima_acao_final = None
        self._dados_pos_sessao_notificados = False
        self.modo_simulado = bool(
            configuracao.get(
                "modo_simulado",
                False
            )
        )
        self.feedback_imediato = bool(
            configuracao.get(
                "feedback_imediato",
                not self.modo_simulado
            )
        )
        self.integrar_revisoes = bool(
            configuracao.get(
                "integrar_revisoes",
                not self.modo_simulado
            )
        )
        if self.sem_impacto_inteligencia:
            self.integrar_revisoes = False
        self.tempo_limite_minutos = max(
            0,
            int(
                configuracao.get(
                    "tempo_limite_minutos",
                    0
                )
                or 0
            )
        )
        self.inicio_simulado = (
            datetime.now()
            if self.modo_simulado
            else None
        )
        self.timer_simulado = None

        self.setWindowTitle(
            (
                "Banco de Erros — treino sem impacto"
                if self.modo_banco_erros
                else "Reforço imediato — sem impacto no histórico"
                if self.sem_impacto_inteligencia
                else (
                    "Simulado"
                    if self.modo_simulado
                    else "Resolver questões"
                )
            )
        )
        self.resize(
            1040,
            780
        )
        self.setMinimumSize(
            820,
            620
        )

        self.origem_sessao = _origem_sessao_unificada(configuracao)
        self.sessao_id = None

        if not self.sem_impacto_inteligencia:
            self.sessao_id = iniciar_sessao_questoes(
                configuracao["concurso_id"],
                configuracao["modo"],
                len(self.fila),
                origem=self.origem_sessao,
                contexto=_contexto_sessao_unificada(configuracao),
                versao_motor="sessao_unificado_v1",
            )

            try:
                registrar_fila_sessao_questoes(
                    self.sessao_id,
                    self.fila,
                )
            except Exception:
                try:
                    encerrar_sessao_questoes(
                        self.sessao_id,
                        concluida=False,
                    )
                except Exception:
                    pass
                raise

            if self.modo_simulado:
                try:
                    registrar_configuracao_simulado(
                        self.sessao_id,
                        self.configuracao
                    )
                except Exception:
                    pass

            try:
                iniciar_medicao_efetividade_sessao(
                    self.sessao_id,
                    self.configuracao
                )
            except Exception:
                # A telemetria pedagógica nunca deve impedir a sessão.
                pass

        layout = QVBoxLayout(
            self
        )
        # B05: a geometria da sessão pode se compactar em janelas pequenas,
        # sem alterar enunciado, alternativas ou botões de resposta.
        self._b05_layout_raiz = layout
        layout.setContentsMargins(
            18,
            14,
            18,
            16
        )
        layout.setSpacing(7)

        # Barra superior moderna: identidade e ações integradas ao mesmo painel.
        self.cabecalho_sessao = QFrame(self)
        self.cabecalho_sessao.setObjectName("questionSessionModernHeader")
        cabecalho = QHBoxLayout(self.cabecalho_sessao)
        self._b12_layout_cabecalho = cabecalho
        cabecalho.setContentsMargins(4, 3, 4, 6)
        cabecalho.setSpacing(9)

        titulos = QVBoxLayout()
        titulos.setSpacing(
            1
        )

        titulo = QLabel(
            (
                "BANCO DE ERROS"
                if self.modo_banco_erros
                else "Reforço imediato"
                if self.sem_impacto_inteligencia
                else (
                    "Simulado"
                    if self.modo_simulado
                    else "Resolver questões"
                )
            )
        )
        titulo.setText("VighnaStudy")
        titulo.setObjectName("questionSessionBrandTitle")

        self.sessao_contexto = QLabel(
            (
                "BANCO DE ERROS • MODO SEM IMPACTO NA INTELIGÊNCIA"
                if self.modo_banco_erros
                else "Reforço pós-bateria • estas respostas não alteram histórico, revisões, Domínio ou recomendações"
                if self.sem_impacto_inteligencia
                else (
                    f"{configuracao['modo']} • Prioridade Vighna"
                )
            )
        )
        self.sessao_contexto.setObjectName(
            "pageSubtitle"
        )

        linha_marca = QHBoxLayout()
        linha_marca.setSpacing(8)
        # B20: aplicar a nova marca enviada pelo usuário somente no cabeçalho
        # da bateria. O texto "VighnaStudy" já existe ao lado; por isso usamos
        # apenas o símbolo (livro + chama) em transparência, evitando duplicar
        # o nome e preservando o restante da identidade da sessão.
        simbolo = QLabel()
        simbolo.setObjectName("questionSessionLogoImageB13")
        simbolo.setAlignment(Qt.AlignCenter)
        simbolo.setFixedSize(31, 31)
        simbolo.setToolTip("Nova marca VighnaStudy")
        logo_vighna = carregar_logo_vighnastudy_bateria_b20()
        if not logo_vighna.isNull():
            simbolo.setPixmap(logo_vighna.scaled(
                29, 31, Qt.KeepAspectRatio, Qt.SmoothTransformation
            ))
        else:
            # Fallback para a marca global já embutida na aplicação.
            logo_vighna = carregar_logo_vighnastudy()
            if not logo_vighna.isNull():
                simbolo_vighna = logo_vighna.copy(
                    0, 0, logo_vighna.width(),
                    max(1, round(logo_vighna.height() * 0.51))
                )
                simbolo.setPixmap(simbolo_vighna.scaled(
                    29, 31, Qt.KeepAspectRatio, Qt.SmoothTransformation
                ))
            else:
                simbolo.setText("V")
        # B14: guardar pixmap da marca para trocar apenas sua aparência.
        self._b14_logo_label = simbolo
        self._b14_logo_original = QPixmap(simbolo.pixmap())
        # B17: estado opcional da leitura fica em QSettings (nao no banco).
        # Primeira abertura permanece 100% compativel com o B16 R3: tres
        # efeitos desligados e valores visuais originais.
        self._b17_preferencias = QSettings("VighnaStudy", "LeituraNeural")
        self._b17_intensidade_halo = self._b17_ler_numero("halo_intensidade", 100, 25, 150)
        self._b17_tamanho_halo = self._b17_ler_numero("halo_tamanho", 58, 32, 96)
        self._b17_intensidade_linha = self._b17_ler_numero("linha_intensidade", 100, 25, 175)
        # B18: efeito opt-in; preserva B17 ate o usuario habilitar.
        self._b18_cor_alternativas_ativa = False
        self._b18_cor_intensidade = self._b17_ler_numero(
            "alternativas_cor_intensidade", 35, 0, 100)
        # B22: recompensa visual curta e opcional; sem novo registro no banco.
        self._b22_efeito_ativo = True
        self._b22_intensidade = self._b17_ler_numero(
            "acerto_efeito_intensidade", 45, 0, 100)
        self._b22_overlay = None
        self._b22_animacao = None
        # B26-B: efeito localizado ao foco das setas; sem impacto no estado da resposta.
        self._b26_nav_ativa = True
        self._b26_nav_intensidade = self._b17_ler_numero(
            "navegacao_efeito_intensidade", 65, 0, 100)
        self._b26_constelacao_intensidade = self._b17_ler_numero(
            "combo_constelacao_intensidade", 78, 0, 100)
        self._b26_nav_overlay = None
        self._b26_nav_animacao = None
        # B26-E: combo verdadeiro e isolado, derivado dos registros locais.
        # A exibicao pode aguardar o feixe, mas nunca perde um acerto se
        # navegacao, pausa ou ocultacao interromperem a animacao.
        self._b26_constelacao_ativa = True
        self._b26_constelacao = None
        self._b26_combo = 0
        self._b26_combo_pendente = None
        self._b26_layout_constelacao_pendente = False
        # B26 R2: trilha sonora original V3, persistida fora do banco academico.
        self._b26r2_sons_ativos = True
        self._b26r2_som_setas = True
        self._b26r2_som_recompensas = True
        self._b26r5_som_transicao = True
        self._b26r2_volume_setas = self._b17_ler_numero(
            "audio_v3_volume_setas", 24, 0, 100)
        self._b26r2_volume_recompensa = self._b17_ler_numero(
            "audio_v3_volume_recompensa", 45, 0, 100)
        self._b26r5_volume_transicao = self._b17_ler_numero(
            "audio_v3_volume_transicao", 32, 0, 100)
        self._b26r2_audio = _AudioXenoArquiteturaB26R2(self)
        self._b26r2_audio.ajustar_volumes(
            self._b26r2_volume_setas, self._b26r2_volume_recompensa,
            self._b26r5_volume_transicao)
        self._b14_modo_pb = False  # B17 restaura o estado salvo apos montar o Qt
        self._b15_halo_cursor = None
        self._b16_faixa_linha = None
        self._b16_cache_metricas = None
