        def metrica(titulo_texto, papel="neutral"):
            frame = QFrame(self.sessao_indicadores)
            frame.setObjectName("questionSessionMiniStat")
            frame_layout = QHBoxLayout(frame)
            frame_layout.setContentsMargins(5, 2, 5, 2)
