        frame, self.stat_acertos = metrica("Acertos", "success")
        metricas.addWidget(frame)
        frame, self.stat_erros = metrica("Erros", "danger")
        metricas.addWidget(frame)
        frame, self.stat_puladas = metrica("Puladas", "warning")
