        # Vighna e usa os controles nativos do Windows para minimizar/maximizar.
        self.setWindowFlag(
            Qt.WindowMinimizeButtonHint,
            True
        )
        self.setWindowFlag(
            Qt.WindowMaximizeButtonHint,
            True
        )
        self.setWindowModality(Qt.NonModal)
        self.setObjectName("topicDetailsDialog")

