    def carregar_historico(self):
        resumo = obter_resumo_topico(
            self.topico_id
        )

        dominio = obter_indice_dominio_topico(
            self.topico_id,
            resumo[
                "concurso_id"
            ]
        )

        score_dominio = float(
            dominio.get(
                "score",
                0.0
            )
            or 0.0
        )

        self.dominio_valor.setText(
            f"{score_dominio:.0f} / 100"
        )
        self.dominio_barra.setValue(
            int(
                round(
                    score_dominio
                )
            )
        )
        self.dominio_nivel.setText(
            dominio.get(
                "nivel",
                "Sem evidência"
            )
        )

        mapa_nivel_dominio = {
            "Sem evidência": "sem",
            "Crítico": "critico",
            "Frágil": "fragil",
            "Em desenvolvimento": "desenvolvimento",
            "Consolidando": "consolidando",
            "Dominado": "dominado",
            "Domínio forte": "forte",
        }

        self.dominio_nivel.setProperty(
            "domainLevel",
            mapa_nivel_dominio.get(
                dominio.get(
                    "nivel"
                ),
                "sem"
            )
        )
        self.dominio_nivel.style().unpolish(
            self.dominio_nivel
        )
        self.dominio_nivel.style().polish(
            self.dominio_nivel
        )

        self.dominio_desempenho.setText(
            f"{dominio['desempenho']:.0f}"
        )
        self.dominio_variedade.setText(
            f"{dominio['variedade']:.0f}"
        )
        self.dominio_estabilidade.setText(
            f"{dominio['estabilidade']:.0f}"
        )
        self.dominio_recencia.setText(
            f"{dominio['recencia']:.0f}"
        )
        self.dominio_erros.setText(
            f"{dominio['controle_erros']:.0f}"
        )
        self.dominio_evidencia_score.setText(
            f"{dominio['evidencia']:.0f}"
        )

        # Premium view mirrors existing numerical results; no recalculation.
        for campo, barra in self._topic_metric_bars.items():
            try:
                valor_exibido = float(getattr(self, campo).text().replace(",", "."))
            except (TypeError, ValueError):
                valor_exibido = 0.0
            barra.setValue(max(0, min(100, int(round(valor_exibido)))))
        for campo, label in self._topic_evidence_values.items():
            label.setText(str(int(dominio.get(campo, 0) or 0)))

        if dominio[
            "tentativas"
        ] <= 0:
            evidencia_texto = (
                "Evidência: sem respostas internas efetivas. "
                "Revisões manuais ou legadas não substituem questões "
                "para este índice."
            )
        else:
            evidencia_texto = (
                f"Evidência {dominio['qualidade_evidencia']} • "
                f"{dominio['tentativas_historicas']} resposta(s) histórica(s) • "
                f"{dominio['questoes_unicas']} questão(ões) diferente(s) • "
                f"{dominio['dias_ativos_historicos']} dia(s) de prática • "
                f"{dominio['revisoes']} revisão(ões) registrada(s) • "
                f"dúvidas recentes {dominio['taxa_duvida']:.0f}%"
            )

        self.dominio_evidencia.setText(
            evidencia_texto
        )

        pontos_fortes = dominio.get(
            "pontos_fortes",
            []
        )
        self.dominio_pontos_fortes.setText(
            " • ".join(pontos_fortes)
            if pontos_fortes
            else "Ainda sem sinal forte suficiente para destacar."
        )

        motivos_dominio = dominio.get(
            "motivos",
            []
        )
        self.dominio_motivos.setText(
            " • ".join(motivos_dominio)
            if motivos_dominio
            else "Nenhum limitador relevante aberto no momento."
        )

        self.dados_revisoes = (
            listar_revisoes_topico(
                self.topico_id
            )
        )

        self.tabela.setRowCount(
            len(self.dados_revisoes)
        )

        for linha, revisao in enumerate(
            self.dados_revisoes
        ):
            origem = (
                "Questões internas"
                if revisao[8]
                == "questoes_internas"
                else "Manual"
            )

            if (
                revisao[8]
                == "questoes_internas"
            ):
                if revisao[9] == "muito_baixa":
                    origem += " • 1º contato"
                elif revisao[9] == "baixa":
                    origem += " • baixa"

            valores = [
                formatar_data(
                    revisao[1]
                ),
                str(
                    revisao[2]
                ),
                str(
                    revisao[3]
                ),
                formatar_percentual(
                    revisao[4]
                ),
                origem
            ]

            for coluna, valor in enumerate(
                valores
            ):
                item = QTableWidgetItem(
                    valor
                )
                item.setTextAlignment(
                    Qt.AlignCenter
                )

                self.tabela.setItem(
                    linha,
                    coluna,
                    item
                )

            self.tabela.setRowHeight(
                linha,
                30
            )

        # Resumo executivo da página do tópico. Os números usam a mesma
        # telemetria que alimenta o Domínio V2 e o motor de recomendação.
        self.valor_dominio_resumo.setText(
            f"{score_dominio:.0f}%"
        )

        quantidade_questoes = int(
            dominio.get("questoes_ativas", 0) or 0
        )
        self.valor_questoes_topico.setText(
            str(quantidade_questoes)
        )

        erros_em_atencao = sum(
            int(dominio.get(chave, 0) or 0)
            for chave in (
                "criticas",
                "recorrentes",
                "recuperacao",
                "erros_isolados",
            )
        )
        self.valor_erros_topico.setText(
            str(erros_em_atencao)
        )

        ultima_pratica = (
            dominio.get("ultima_resposta")
            or resumo.get("ultima_revisao")
        )
        if ultima_pratica:
            texto_ultima = str(ultima_pratica)
            try:
                momento = datetime.fromisoformat(
                    texto_ultima.replace("Z", "+00:00")
                )
                texto_ultima = momento.strftime("%d/%m/%Y")
            except Exception:
                texto_ultima = formatar_data(
                    texto_ultima[:10]
                )
        else:
            texto_ultima = "—"

        self.valor_ultima_pratica_topico.setText(
            texto_ultima
        )
        self.topic_last_practice.setText("Última prática\n" + texto_ultima)

        self.valor_proxima_topico.setText(
            formatar_data(
                resumo.get("proxima_revisao")
            )
        )

        disciplina_nome = str(
            self.contexto_topico.get(
                "disciplina_nome",
                ""
            )
            or ""
        )
        breadcrumb = []
        if disciplina_nome:
            breadcrumb.append(disciplina_nome)
        breadcrumb.append(f"Perfil {resumo['concurso_nome']}")
        self.topico_breadcrumb.setText("  ›  ".join(breadcrumb))

        revisoes_totais = int(resumo.get("revisoes_totais", 0) or 0)
        revisoes_texto = (
            "1 revisão registrada"
            if revisoes_totais == 1
            else f"{revisoes_totais} revisões registradas"
        )
        self.topico_contexto_label.setText(
            f"Importância {resumo['importancia']}/5 • {revisoes_texto}"
        )

        # Painel de próximo passo: usa a agenda real do tópico e comunica o
        # estado em linguagem direta, sem transformar todos os dados em cards.
        proxima_raw = resumo.get("proxima_revisao")
        proxima_qdate = QDate.fromString(
            str(proxima_raw or "")[:10],
            "yyyy-MM-dd",
        )
        hoje_qdate = QDate.currentDate()
        estado_agenda = "none"
        if proxima_qdate.isValid():
            dias = hoje_qdate.daysTo(proxima_qdate)
            self.proximo_data.setText(proxima_qdate.toString("dd/MM/yyyy"))
            if dias < 0:
                atraso = abs(dias)
                self.proximo_status.setText(
                    "REVISÃO EM ATRASO"
                )
                self.proximo_texto.setText(
                    f"A revisão programada venceu há {atraso} dia(s). Priorize uma revisão curta ou uma bateria dirigida antes de avançar."
                )
                estado_agenda = "overdue"
            elif dias == 0:
                self.proximo_status.setText("REVISÃO HOJE")
                self.proximo_texto.setText(
                    "A revisão deste tópico está prevista para hoje. Uma rodada curta já atualiza a agenda e o domínio."
                )
                estado_agenda = "today"
            elif dias == 1:
                self.proximo_status.setText("REVISÃO AMANHÃ")
                self.proximo_texto.setText(
                    "A próxima revisão está próxima. Você pode antecipá-la agora ou manter a agenda planejada."
                )
                estado_agenda = "soon"
            else:
                self.proximo_status.setText(f"EM {dias} DIAS")
                self.proximo_texto.setText(
                    "A revisão está agendada. Continue estudando normalmente ou antecipe uma sessão se quiser reforçar este conteúdo."
                )
                estado_agenda = "future"
        else:
            self.proximo_status.setText("SEM REVISÃO AGENDADA")
            self.proximo_data.setText("—")
            self.proximo_texto.setText(
                "Ainda não há uma próxima revisão registrada. Estude o tópico ou registre uma revisão para alimentar a agenda."
            )

        self.proximo_status.setProperty("scheduleState", estado_agenda)
        self.proximo_status.style().unpolish(self.proximo_status)
        self.proximo_status.style().polish(self.proximo_status)
        self.proximo_atencao.setText(
            f"{erros_em_atencao} erro(s) em atenção • {quantidade_questoes} questão(ões) ativa(s)"
        )

        iniciais = resumo[
            "revisoes_iniciais"
        ]

        if iniciais > 0:
            self.aviso_legado.setText(
                f"ℹ  {iniciais} revisão(ões) importada(s) do Excel contam no total, "
                "mas não possuem detalhes individuais editáveis."
            )
            self.aviso_legado.setVisible(
                True
            )
        else:
            self.aviso_legado.clear()
            self.aviso_legado.setVisible(
                False
            )

        # Evolução detalhada considera apenas as sessões que
        # possuem data, questões e acertos registrados no programa.
        cronologico = list(
            reversed(
                self.dados_revisoes
            )
        )

        percentuais_grafico = [
            revisao[4]
            for revisao in cronologico
        ]

        rotulos_grafico = [
            f"R{i + 1}"
            for i in range(
                len(cronologico)
            )
        ]

        self.grafico_evolucao.definir_dados(
            percentuais_grafico,
            rotulos_grafico
        )

        sem_evolucao = len(cronologico) == 0
        self.grafico_evolucao.setVisible(not sem_evolucao)
        self.evolucao_vazia.setVisible(sem_evolucao)
        self.resumo_evolucao.setVisible(not sem_evolucao)

        if len(cronologico) == 0:
            self.resumo_evolucao.clear()

        elif len(cronologico) == 1:
            atual = cronologico[0][4]

            self.resumo_evolucao.setText(
                f"1 revisão detalhada • resultado {formatar_percentual(atual)}"
            )

        else:
            primeiro = cronologico[0][4]
            ultimo = cronologico[-1][4]
            melhor = max(
                percentuais_grafico
            )
            pior = min(
                percentuais_grafico
            )
            variacao = (
                ultimo - primeiro
            )

            sinal = (
                "+"
                if variacao > 0
                else ""
            )

            self.resumo_evolucao.setText(
                f"{formatar_percentual(primeiro)} → {formatar_percentual(ultimo)}  •  "
                f"Variação {sinal}{variacao:.1f} p.p.  •  "
                f"Melhor {formatar_percentual(melhor)}  •  "
                f"Pior {formatar_percentual(pior)}"
            )

        self.detalhes.clear()
        self.atualizar_estado_botoes()

    def atualizar_estado_botoes(self):
        tem_selecao = (
            self.tabela.currentRow() >= 0
            and len(self.dados_revisoes) > 0
        )

        automatica = False

        if tem_selecao:
            revisao = self.dados_revisoes[
                self.tabela.currentRow()
            ]
            automatica = (
                len(
                    revisao
                ) > 8
                and revisao[8]
                == "questoes_internas"
            )

        editavel = (
            tem_selecao
            and not automatica
        )

        self.editar_revisao_btn.setEnabled(
            editavel
        )
        self.excluir_revisao_btn.setEnabled(
            editavel
        )

        if automatica:
            texto = (
                "Revisões automáticas são controladas pelas "
                "tentativas das questões internas."
            )
            self.editar_revisao_btn.setToolTip(
                texto
            )
            self.excluir_revisao_btn.setToolTip(
                texto
            )
        else:
            self.editar_revisao_btn.setToolTip(
                "Editar a revisão manual selecionada."
            )
            self.excluir_revisao_btn.setToolTip(
                "Excluir a revisão manual selecionada."
            )

    def exec(self):
        """Mantém a API dos chamadores sem tornar a página do tópico modal."""
        ciclo = QEventLoop()
        encerrada = False

        def encerrar_ciclo(*_args):
            nonlocal encerrada
            encerrada = True
            if ciclo.isRunning():
                ciclo.quit()

        self.finished.connect(encerrar_ciclo)
        self.setWindowModality(Qt.NonModal)
        self.show()
        self.raise_()
        self.activateWindow()

        if not encerrada:
            ciclo.exec()

        try:
            self.finished.disconnect(encerrar_ciclo)
        except (RuntimeError, TypeError):
            pass
        return self.result()

    def estudar_topico(self):
        janela_config = JanelaEstudoTopico(
            self.topico_id,
            self.nome_topico,
            self,
        )
        if janela_config.exec() != QDialog.Accepted:
            return

        configuracao = janela_config.configuracao or {}
        fila = configuracao.get("fila") or []
        if not fila:
            return

        janela = JanelaResolverQuestoes(
            configuracao,
            self,
        )
        janela.exec_nao_modal()
        self.carregar_historico()

    def revisar_topico(self):
        quantidade_revisao = max(
            1,
            obter_configuracao_int(
                "questoes_revisao_min_registro",
                5
            )
        )
        resultado = abrir_resolvedor_topico(
            self.topico_id,
            self.nome_topico,
            self,
            quantidade_padrao=quantidade_revisao,
            modo_nome="Revisão do tópico",
            origem_sessao="topico_revisao",
        )
        if resultado is not None:
            self.carregar_historico()

    def ver_questoes_topico(self):
        # A Central de Questões é a fonte administrativa oficial. Ao sair da
        # página do tópico, fechamos este diálogo modal e abrimos a Central já
        # filtrada no conteúdo atual, onde também ficam Importar e Nova questão.
        alvo = self.parentWidget()
        while alvo is not None:
            metodo = getattr(alvo, "abrir_questoes_topico_contextual", None)
            if callable(metodo):
                topico_id = self.topico_id
                self.accept()
                QTimer.singleShot(0, lambda m=metodo, tid=topico_id: m(tid))
                return
            alvo = alvo.parentWidget()

        app = QApplication.instance()
        if app is not None:
            for janela in app.topLevelWidgets():
                metodo = getattr(janela, "abrir_questoes_topico_contextual", None)
                if callable(metodo):
                    topico_id = self.topico_id
                    self.accept()
                    QTimer.singleShot(0, lambda m=metodo, tid=topico_id: m(tid))
                    return

        QMessageBox.warning(
            self,
            "Ver questões",
            "A Central de Questões não pôde ser localizada."
        )

    def resolver_questoes(self):
        # Compatibilidade com atalhos antigos: "resolver" agora equivale
        # à ação principal Estudar da página do tópico.
        return self.estudar_topico()

    def nova_revisao(self):
        janela = JanelaRevisao(
            self.topico_id,
            self.nome_topico,
            self
        )

        if janela.exec() == QDialog.Accepted:
            _notificar_dados_alterados_raiz(self, "revisoes")
            self.carregar_historico()

    def editar_revisao(self):
        linha = self.tabela.currentRow()

        if linha < 0:
            return

        revisao = self.dados_revisoes[linha]

        janela = JanelaRevisao(
            self.topico_id,
            self.nome_topico,
            self,
            revisao=revisao,
            modo_edicao=True
        )

        if janela.exec() == QDialog.Accepted:
            _notificar_dados_alterados_raiz(self, "revisoes")
            self.carregar_historico()

    def excluir_revisao_selecionada(self):
        linha = self.tabela.currentRow()

        if linha < 0:
            return

        revisao = self.dados_revisoes[linha]

        resposta = QMessageBox.question(
            self,
            "Excluir revisão",
            (
                "Tem certeza que deseja excluir esta revisão?\n\n"
                f"Data: {formatar_data(revisao[1])}\n"
                f"Questões: {revisao[2]}\n"
                f"Acertos: {revisao[3]}\n"
                f"Resultado: {formatar_percentual(revisao[4])}\n\n"
                "Essa ação remove esse registro do histórico."
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No
        )

        if resposta != QMessageBox.Yes:
            return

        excluir_revisao(
            revisao[0]
        )

        _notificar_dados_alterados_raiz(self, "revisoes")
        self.carregar_historico()

    def alterar_proxima_revisao(self):
        resumo = obter_resumo_topico(
            self.topico_id
        )

        atual = resumo[
            "proxima_revisao"
        ]

        dialogo = QDialog(self)
        dialogo.setWindowTitle(
            "Alterar próxima revisão"
        )

        layout = QVBoxLayout(dialogo)

        texto = QLabel(
            "Escolha a nova data da próxima revisão:"
        )
        layout.addWidget(texto)

        data = QDateEdit()
        data.setCalendarPopup(True)
        data.setDisplayFormat("dd/MM/yyyy")

        if atual:
            data_atual = QDate.fromString(
                atual,
                "yyyy-MM-dd"
            )
            if data_atual.isValid():
                data.setDate(data_atual)
            else:
                data.setDate(QDate.currentDate())
        else:
            data.setDate(QDate.currentDate())

        layout.addWidget(data)

        botoes = QDialogButtonBox(
            QDialogButtonBox.Save |
            QDialogButtonBox.Cancel
        )

        botoes.button(
            QDialogButtonBox.Save
        ).setText("Salvar data")
        botoes.button(
            QDialogButtonBox.Cancel
        ).setText("Cancelar")

        botoes.accepted.connect(
            dialogo.accept
        )
        botoes.rejected.connect(
            dialogo.reject
        )

        layout.addWidget(botoes)

        if dialogo.exec() == QDialog.Accepted:
            atualizar_proxima_revisao(
                self.topico_id,
                data.date().toString(
                    "yyyy-MM-dd"
                )
            )
            _notificar_dados_alterados_raiz(self, "revisoes")
            self.carregar_historico()

    def mostrar_detalhes(self):
        linha = self.tabela.currentRow()

        if linha < 0:
            self.detalhes.clear()
            self.atualizar_estado_botoes()
            return

        revisao = self.dados_revisoes[
            linha
        ]

        observacao = revisao[5] or "—"
        texto_erros = revisao[6] or "—"
        continuacao = revisao[7] or "—"

        origem = (
            revisao[8]
            if len(
                revisao
            ) > 8
            else "manual"
        )

        if origem == "questoes_internas":
            confianca = (
                revisao[9]
                if len(
                    revisao
                ) > 9
                else ""
            )

            if confianca == "muito_baixa":
                confianca_texto = (
                    "Muito baixa • primeiro contato"
                )
            elif confianca == "baixa":
                confianca_texto = (
                    "Baixa confiança"
                )
            else:
                confianca_texto = (
                    "Normal"
                )

            tentativas = (
                listar_tentativas_revisao_automatica(
                    revisao[0]
                )
            )

            linhas_questoes = []

            for tentativa in tentativas:
                linhas_questoes.append(
                    (
                        f"#{tentativa['questao_id']} • "
                        f"{tentativa['status']} • "
                        f"marcada {tentativa['marcada'] or '—'} • "
                        f"gabarito {tentativa['gabarito'] or '—'}"
                        + (
                            " • dúvida"
                            if tentativa[
                                "duvida"
                            ]
                            else ""
                        )
                    )
                )

            bloco_questoes = (
                "\n".join(
                    linhas_questoes
                )
                if linhas_questoes
                else "Nenhuma tentativa vinculada."
            )

            self.detalhes.setPlainText(
                "ORIGEM\n"
                "──────\n"
                "Questões internas\n\n"
                "CONFIANÇA\n"
                "─────────\n"
                f"{confianca_texto}\n\n"
                "QUESTÕES QUE FORMARAM A REVISÃO\n"
                "───────────────────────────────\n"
                f"{bloco_questoes}\n\n"
                "OBSERVAÇÃO\n"
                "──────────\n"
                f"{observacao}"
            )
        else:
            self.detalhes.setPlainText(
                "ORIGEM\n"
                "──────\n"
                "Registro manual\n\n"
                "OBSERVAÇÃO\n"
                "──────────\n"
                f"{observacao}\n\n"
                "TEXTO DE ERROS\n"
                "──────────────\n"
                f"{texto_erros}\n\n"
                "CONTINUAÇÃO\n"
                "───────────\n"
                f"{continuacao}"
            )

        self.atualizar_estado_botoes()


