    def abrir_disciplinas_desativadas(self):
        janela = JanelaItensDesativados(
            aba=0,
            parent=self
        )
        janela.exec()
        self.carregar()

    def carregar(self):
        disciplinas = listar_disciplinas(
            somente_incluidas=False
        )

        concursos = listar_concursos()

        self.tabela.setRowCount(
            len(
                disciplinas
            )
        )

        # Para apresentar em quantos perfis cada disciplina aparece,
        # usa a estrutura já existente de associação.
        for linha, (
            disciplina_id,
            nome
        ) in enumerate(
            disciplinas
        ):
            resumo = obter_resumo_disciplina(
                disciplina_id
            )

            quantidade_perfis = 0

            for concurso in concursos:
                conteudos = listar_conteudos_concurso(
                    concurso[0]
                )

                for disciplina in conteudos:
                    if (
                        disciplina[
                            "disciplina_id"
                        ]
                        == disciplina_id
                        and disciplina[
                            "incluida"
                        ]
                    ):
                        quantidade_perfis += 1
                        break

            valores = [
                nome,
                str(
                    resumo[
                        "topicos"
                    ]
                ),
                str(
                    resumo[
                        "revisoes_totais"
                    ]
                ),
                str(
                    resumo[
                        "questoes_programa"
                    ]
                ),
                (
                    f"{quantidade_perfis}/"
                    f"{len(concursos)}"
                )
            ]

            for coluna, valor in enumerate(
                valores
            ):
                item = QTableWidgetItem(
                    valor
                )

                if coluna == 0:
                    item.setData(
                        Qt.UserRole,
                        disciplina_id
                    )

                self.tabela.setItem(
                    linha,
                    coluna,
                    item
                )

    def selecionada(self):
        linha = (
            self.tabela.currentRow()
        )

        if linha < 0:
            return (
                None,
                None
            )

        item = self.tabela.item(
            linha,
            0
        )

        if item is None:
            return (
                None,
                None
            )

        return (
            item.data(
                Qt.UserRole
            ),
            item.text()
        )

    def adicionar(self):
        nome, confirmou = QInputDialog.getText(
            self,
            "Adicionar disciplina",
            (
                "Nome da nova disciplina:\n"
                "Ex.: Legislação Especial"
            )
        )

        if not confirmou:
            return

        nome = nome.strip()

        if not nome:
            return

        disciplina_id = adicionar_disciplina(
            nome
        )

        if disciplina_id is None:
            QMessageBox.information(
                self,
                "Disciplina não adicionada",
                (
                    "Já existe uma disciplina com esse nome "
                    "ou o nome informado é inválido."
                )
            )
            return

        self.carregar()

        QMessageBox.information(
            self,
            "Disciplina adicionada",
            (
                f"'{nome}' foi criada.\n\n"
                "Ela foi incluída automaticamente no perfil Padrão "
                "e no perfil atualmente ativo. Nos demais perfis, "
                "você pode associá-la em Conteúdos do perfil."
            )
        )

    def renomear_selecionada(self, *args):
        disciplina_id, nome = (
            self.selecionada()
        )

        if disciplina_id is None:
            QMessageBox.information(
                self,
                "Selecione uma disciplina",
                (
                    "Selecione primeiro a disciplina "
                    "que deseja renomear."
                )
            )
            return

        novo_nome, confirmou = QInputDialog.getText(
            self,
            "Renomear disciplina",
            "Novo nome:",
            text=nome
        )

        if not confirmou:
            return

        novo_nome = (
            novo_nome.strip()
        )

        if not novo_nome:
            return

        if not renomear_disciplina(
            disciplina_id,
            novo_nome
        ):
            QMessageBox.information(
                self,
                "Não foi possível renomear",
                (
                    "Verifique se o nome está preenchido "
                    "e se não existe outra disciplina igual."
                )
            )
            return

        self.carregar()

    def excluir_selecionada(self):
        disciplina_id, nome = (
            self.selecionada()
        )

        if disciplina_id is None:
            QMessageBox.information(
                self,
                "Selecione uma disciplina",
                (
                    "Selecione primeiro a disciplina "
                    "que deseja excluir."
                )
            )
            return

        resumo = obter_resumo_disciplina(
            disciplina_id
        )

        if resumo is None:
            return

        resposta = QMessageBox.warning(
            self,
            "Excluir disciplina permanentemente",
            (
                f"Excluir GLOBALMENTE a disciplina:\n\n"
                f"{nome}\n\n"
                "Serão apagados permanentemente:\n"
                f"• {resumo['topicos']} tópico(s)\n"
                f"• {resumo['revisoes_totais']} revisão(ões) "
                "contabilizadas\n"
                f"• {resumo['questoes_programa']} questão(ões) "
                "registradas no programa\n"
                "• observações, erros e histórico desses tópicos\n"
                "• associações dessa disciplina com todos os perfis\n\n"
                "Se a intenção for apenas retirar a matéria de um "
                "concurso, NÃO faça esta exclusão; use Conteúdos do perfil.\n\n"
                "Deseja continuar?"
            ),
            QMessageBox.Yes |
            QMessageBox.No,
            QMessageBox.No
        )

        if resposta != QMessageBox.Yes:
            return

        # Proteção adicional para disciplinas que já possuem conteúdo.
        if (
            resumo[
                "topicos"
            ] > 0
            or resumo[
                "revisoes_totais"
            ] > 0
        ):
            confirmacao, confirmou = QInputDialog.getText(
                self,
                "Confirmação final",
                (
                    "Para confirmar a exclusão permanente, "
                    "digite exatamente o nome da disciplina:\n\n"
                    f"{nome}"
                )
            )

            if (
                not confirmou
                or confirmacao.strip()
                != nome
            ):
                QMessageBox.information(
                    self,
                    "Exclusão cancelada",
                    (
                        "O nome informado não corresponde. "
                        "Nenhum dado foi excluído."
                    )
                )
                return

        try:
            backup_criado = fazer_backup(
                "antes_excluir_disciplina"
            )

            if not excluir_disciplina(
                disciplina_id
            ):
                raise RuntimeError(
                    "A disciplina não foi encontrada."
                )

        except Exception as erro:
            QMessageBox.critical(
                self,
                "Falha na exclusão",
                (
                    "A disciplina não foi excluída.\n\n"
                    f"{erro}"
                )
            )
            return

        self.carregar()

        QMessageBox.information(
            self,
            "Disciplina excluída",
            (
                f"'{nome}' foi excluída permanentemente.\n\n"
                "Foi criado um backup do estado anterior em:\n"
                f"{backup_criado}"
            )
        )


