    def preencher_tabela(
        self,
        tabela
    ):
        for coluna in range(
            5
        ):
            revisao = coluna + 1

            for linha, faixa in enumerate(
                FAIXAS_PERCENTUAIS
            ):
                minimo, maximo = tabela[
                    revisao
                ][faixa]

                item = QTableWidgetItem(
                    f"{minimo}–{maximo}"
                )

                item.setTextAlignment(
                    Qt.AlignCenter
                )

                self.tabela.setItem(
                    linha,
                    coluna,
                    item
                )

    def carregar(self):
        config = (
            carregar_configuracao_espacamento()
        )

        self.preencher_tabela(
            config[
                "tabela"
            ]
        )

        self.limite_moderada.setValue(
            config[
                "limite_moderada"
            ]
        )

        self.limite_forte.setValue(
            config[
                "limite_forte"
            ]
        )

        self.penalizacao_moderada.setValue(
            config[
                "penalizacao_moderada"
            ]
        )

        self.penalizacao_forte.setValue(
            config[
                "penalizacao_forte"
            ]
        )

    def restaurar_padroes(self):
        resposta = QMessageBox.question(
            self,
            "Restaurar padrões",
            (
                "Voltar a matriz e os ajustes por queda "
                "aos valores originais?\n\n"
                "A alteração só será gravada quando você "
                "clicar em “Salvar matriz”."
            ),
            QMessageBox.Yes |
            QMessageBox.No,
            QMessageBox.No
        )

        if resposta != QMessageBox.Yes:
            return

        tabela = obter_tabela_padrao()
        queda = (
            obter_configuracao_queda_padrao()
        )

        self.preencher_tabela(
            tabela
        )

        self.limite_moderada.setValue(
            queda[
                "limite_moderada"
            ]
        )
        self.limite_forte.setValue(
            queda[
                "limite_forte"
            ]
        )
        self.penalizacao_moderada.setValue(
            queda[
                "penalizacao_moderada"
            ]
        )
        self.penalizacao_forte.setValue(
            queda[
                "penalizacao_forte"
            ]
        )

    def ler_intervalo(
        self,
        texto,
        faixa,
        revisao
    ):
        texto = str(
            texto
        ).strip()

        texto = texto.replace(
            "—",
            "-"
        ).replace(
            "–",
            "-"
        )

        partes = [
            parte.strip()
            for parte in texto.split(
                "-"
            )
            if parte.strip()
        ]

        if len(partes) != 2:
            raise ValueError(
                f"Use o formato mínimo–máximo na faixa "
                f"{faixa}, {revisao}ª revisão."
            )

        try:
            minimo = int(
                partes[0]
            )
            maximo = int(
                partes[1]
            )
        except ValueError:
            raise ValueError(
                f"Use números inteiros na faixa "
                f"{faixa}, {revisao}ª revisão."
            )

        return (
            minimo,
            maximo
        )

    def obter_tabela_digitada(self):
        tabela = {}

        for coluna in range(
            5
        ):
            revisao = coluna + 1
            tabela[
                revisao
            ] = {}

            for linha, faixa in enumerate(
                FAIXAS_PERCENTUAIS
            ):
                item = self.tabela.item(
                    linha,
                    coluna
                )

                if item is None:
                    raise ValueError(
                        f"Há uma célula vazia em {faixa}, "
                        f"{revisao}ª revisão."
                    )

                tabela[
                    revisao
                ][faixa] = (
                    self.ler_intervalo(
                        item.text(),
                        faixa,
                        revisao
                    )
                )

        validar_tabela_espacamento(
            tabela
        )

        return tabela

    def salvar(self):
        try:
            tabela = (
                self.obter_tabela_digitada()
            )

            salvar_configuracao_espacamento(
                tabela,
                self.limite_moderada.value(),
                self.limite_forte.value(),
                self.penalizacao_moderada.value(),
                self.penalizacao_forte.value()
            )

        except ValueError as erro:
            QMessageBox.warning(
                self,
                "Configuração inválida",
                str(
                    erro
                )
            )
            return

        QMessageBox.information(
            self,
            "Matriz salva",
            (
                "As novas regras já serão usadas nas "
                "próximas sugestões de revisão."
            )
        )

        self.accept()


