    def abrir_historico_atualizacoes(self):
        from caminhos import PASTA_DADOS
        historico = PASTA_DADOS / "backups" / "atualizacoes" / "historico.jsonl"
        janela = QDialog(self)
        janela.setWindowTitle("Histórico de atualizações — VighnaStudy")
        janela.resize(660, 410)
        layout = QVBoxLayout(janela)
        titulo = QLabel("Histórico de instalações e recuperações")
        titulo.setObjectName("pageTitle")
        layout.addWidget(titulo)
        registros = QTextEdit()
        registros.setReadOnly(True)
        if historico.is_file():
            linhas = historico.read_text(encoding="utf-8").splitlines()[-80:]
            resumo = []
            for linha in reversed(linhas):
                try:
                    item = json.loads(linha)
                    resumo.append(
                        f"{item.get('date', '—')}  •  {item.get('status', '—')}  •  "
                        f"{item.get('from', '—')} → {item.get('to', '—')}"
                    )
                    if item.get('package'):
                        resumo.append("  ZIP: " + str(item['package']))
                    if item.get('sha256'):
                        resumo.append("  SHA-256: " + str(item['sha256'])[:20] + "…")
                    if item.get("error"):
                        resumo.append("  Motivo: " + str(item["error"]))
                except (TypeError, ValueError):
                    continue
            registros.setPlainText("\n".join(resumo) or "Sem registros válidos.")
        else:
            registros.setPlainText("Nenhuma atualização foi executada por esta Central.")
        layout.addWidget(registros)
        botao = QPushButton("Fechar")
        botao.clicked.connect(janela.accept)
        layout.addWidget(botao)
        janela.exec()

    def criar_secao_configuracao(
        self,
        titulo,
        descricao=""
    ):
        # M04: cabeçalho de seção em widgets Qt reais. Nenhum controle original
        # é movido, substituído ou clonado; a seção permanece a mesma QFrame.
        secao = QFrame()
        secao.setObjectName("settingsSection")
        secao_layout = QVBoxLayout(secao)
        secao_layout.setContentsMargins(13, 11, 13, 13)
        secao_layout.setSpacing(9)

        cabecalho = QFrame()
        cabecalho.setObjectName("settingsSectionHeaderM04")
        linha_cabecalho = QHBoxLayout(cabecalho)
        linha_cabecalho.setContentsMargins(0, 0, 0, 0)
        linha_cabecalho.setSpacing(10)

        numero = QLabel(f"{len(self.secoes_pesquisa) + 1:02d}")
        numero.setObjectName("settingsSectionIndexM04")
        numero.setAlignment(Qt.AlignCenter)
        numero.setFixedSize(34, 32)
        linha_cabecalho.addWidget(numero, 0, Qt.AlignVCenter)

        textos = QVBoxLayout()
        textos.setContentsMargins(0, 0, 0, 0)
        textos.setSpacing(2)
        rotulo = QLabel(titulo)
        rotulo.setObjectName("settingsSectionTitle")
        rotulo.setWordWrap(True)
        textos.addWidget(rotulo)
        if descricao:
            subtitulo = QLabel(descricao)
            subtitulo.setObjectName("settingsSectionDescription")
            subtitulo.setWordWrap(True)
            textos.addWidget(subtitulo)
        linha_cabecalho.addLayout(textos, 1)

        contador = QLabel("0 OPÇÕES")
        contador.setObjectName("settingsSectionCountM04")
        contador.setAlignment(Qt.AlignCenter)
        contador.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        linha_cabecalho.addWidget(contador, 0, Qt.AlignVCenter)
        self._contadores_secao_config_m04[secao] = contador
        secao_layout.addWidget(cabecalho)

        separador = QFrame()
        separador.setObjectName("settingsSectionSeparatorM04")
        separador.setFixedHeight(1)
        secao_layout.addWidget(separador)
        # V2/M01: a seção e seus controles originais são filhos de uma
        # página individual. A área de rolagem não afeta outras categorias.
        pagina_scroll = QScrollArea()
        pagina_scroll.setObjectName("settingsPageScrollV2")
        pagina_scroll.setWidgetResizable(True)
        pagina_scroll.setFrameShape(QFrame.NoFrame)
        pagina_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        pagina_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        pagina_conteudo = QWidget()
        pagina_conteudo.setObjectName("settingsPageContentV2")
        pagina_layout = QVBoxLayout(pagina_conteudo)
        pagina_layout.setContentsMargins(2, 2, 8, 4)
        pagina_layout.setSpacing(12)
        pagina_layout.addWidget(secao)
        pagina_layout.addStretch(1)
        pagina_scroll.setWidget(pagina_conteudo)
        self._pilha_paginas_config_v2.addWidget(pagina_scroll)
        self._paginas_config_v2[secao] = pagina_scroll

        self.secoes_pesquisa.append({
            "widget": secao,
            "titulo": titulo,
            "opcoes": []
        })

        # Navegação V2: corresponde às seis seções visíveis.
        titulos_curtos = {
            "Fila inteligente": "Fila inteligente",
            "Espaçamento das revisões": "Revisões",
            "Eficiência e automação": "Automação",
            "Backups e recuperação": "Backups",
            "Atualizações e segurança": "Sistema",
        }
        icones_nav = {
            "Aparência": "fa5s.palette",
            "Fila inteligente": "fa5s.brain",
            "Espaçamento das revisões": "fa5s.calendar-alt",
            "Eficiência e automação": "fa5s.bolt",
            "Backups e recuperação": "fa5s.database",
            "Atualizações e segurança": "fa5s.shield-alt",
        }
        nav = QPushButton(titulos_curtos.get(titulo, titulo))
        nav.setToolTip(f"Abrir categoria: {titulo}")
        nav.setAccessibleName(f"Abrir configurações: {titulo}")
        nav.setObjectName("settingsNavigationButtonM01")
        # Ícones QtAwesome nativos (com fallback sem ícone se QtAwesome faltar).
        tema_nav = normalizar_tema(
            obter_configuracao_texto("tema_interface", "futurista")
        )
        nav.setIcon(criar_icone(icones_nav[titulo], tema=tema_nav, papel="destaque"))
        nav.setIconSize(QSize(17, 17))
        nav.setCheckable(True)
        nav.setMinimumHeight(33)
        nav.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        nav.setFocusPolicy(Qt.StrongFocus)
        nav.clicked.connect(lambda _=False, alvo=secao: self._abrir_secao_config(alvo))
        self._grupo_navegacao_config.addButton(nav)
        self._lista_navegacao_config.insertWidget(
            self._lista_navegacao_config.count() - 1, nav
        )
        self._navegacao_config_links.append((nav, secao))

        return (
            secao,
            secao_layout
        )

    def registrar_opcao_pesquisa(
        self,
        secao,
        widget,
        titulo,
        palavras_chave
    ):
        registro = {
            "secao": secao,
            "widget": widget,
            "titulo": titulo,
            "palavras": (
                f"{titulo} {palavras_chave}"
            )
        }

        self.opcoes_pesquisa.append(
            registro
        )

        for registro_secao in self.secoes_pesquisa:
            if (
                registro_secao[
                    "widget"
                ]
                is secao
            ):
                registro_secao[
                    "opcoes"
                ].append(
                    registro
                )
                # Contagem informativa, derivada das opções já registradas.
                contador = self._contadores_secao_config_m04.get(secao)
                if contador is not None:
                    quantidade = len(registro_secao["opcoes"])
                    contador.setText(
                        f"{quantidade} OPÇÃO" if quantidade == 1
                        else f"{quantidade} OPÇÕES"
                    )
                break

    def normalizar_busca(
        self,
        texto
    ):
        texto = str(
            texto or ""
        ).lower().strip()

        texto = unicodedata.normalize(
            "NFD",
            texto
        )

        texto = "".join(
            caractere
            for caractere in texto
            if unicodedata.category(
                caractere
            )
            != "Mn"
        )

        return " ".join(
            texto.split()
        )

    def _destacar_resultado_config_v2(self, registro):
        """Muda somente aparência visual do resultado; nenhum valor é alterado."""
        anterior = getattr(self, "_resultado_ativo_config_v2", None)
        if anterior is registro:
            return
        for item, ativo in ((anterior, False), (registro, True)):
            if item is None:
                continue
            widget = item["widget"]
            widget.setProperty("configSearchActiveV2", ativo)
            estilo = widget.style()
            estilo.unpolish(widget)
            estilo.polish(widget)
            widget.update()
        self._resultado_ativo_config_v2 = registro

    def _posicionar_resultado_config_v2(self, registro):
        """Executado após o layout ser exibido, sem depender de geometria fixa."""
        if registro is not self._resultado_ativo_config_v2:
            return
        if not self.campo_busca_config.text().strip():
            return
        secao = registro["secao"]
        pagina = self._paginas_config_v2.get(secao)
        if pagina is not None and self._pilha_paginas_config_v2.currentWidget() is pagina:
            pagina.ensureWidgetVisible(registro["widget"], 12, 12)

    def _abrir_resultado_config_v2(self, registro):
        """Abre a categoria correspondente e posiciona o item sem editar dados."""
        if registro not in self._resultados_filtrados_config_v2:
            return
        self._mostrar_pagina_config_v2(registro["secao"], reiniciar_rolagem=False)
        self._destacar_resultado_config_v2(registro)
        QTimer.singleShot(0, lambda item=registro: self._posicionar_resultado_config_v2(item))

    def _selecionar_resultado_config_v2(self, indice):
        """A opção zero é um indicador, não um registro de configuração."""
        if indice <= 0 or indice > len(self._resultados_filtrados_config_v2):
            return
        self._abrir_resultado_config_v2(self._resultados_filtrados_config_v2[indice - 1])

    def _abrir_primeiro_resultado_config_v2(self):
        """Enter no campo de pesquisa abre o resultado selecionado ou primeiro."""
        encontrados = self._resultados_filtrados_config_v2
        if not encontrados or not self.campo_busca_config.text().strip():
            return
        indice = self._lista_resultados_config_v2.currentIndex()
        if 1 <= indice <= len(encontrados):
            registro = encontrados[indice - 1]
        else:
            registro = encontrados[0]
        self._abrir_resultado_config_v2(registro)

    def filtrar_configuracoes(self, texto):
        """Busca todas as seis páginas e permite selecionar cada resultado."""
        busca = self.normalizar_busca(texto)
        termos = [termo for termo in busca.split(" ") if termo]
        encontrados = []
        resultados = {}

        for registro in self.opcoes_pesquisa:
            alvo = self.normalizar_busca(registro["palavras"])
            corresponde = not termos or all(termo in alvo for termo in termos)
            resultados[id(registro)] = corresponde
            registro["widget"].setVisible(corresponde)
            if corresponde:
                encontrados.append(registro)

        for registro_secao in self.secoes_pesquisa:
            registro_secao["widget"].setVisible(any(
                resultados.get(id(opcao), False)
                for opcao in registro_secao["opcoes"]
            ))

        quantidade = len(encontrados)
        if termos:
            self.resultado_busca_config.setText(
                "1 opção encontrada" if quantidade == 1
                else f"{quantidade} opções encontradas"
            )
        else:
            self.resultado_busca_config.setText(
                f"{len(self.opcoes_pesquisa)} opções disponíveis"
            )

        self.aviso_sem_resultado.setVisible(quantidade == 0)
        self._pilha_paginas_config_v2.setVisible(quantidade > 0)
        self._resultados_filtrados_config_v2 = encontrados if termos else []
        self._lista_resultados_config_v2.blockSignals(True)
        try:
            self._lista_resultados_config_v2.clear()
            if termos and quantidade:
                self._lista_resultados_config_v2.addItem("Selecionar resultado…")
                for item in encontrados:
                    nome_secao = next(
                        (secao["titulo"] for secao in self.secoes_pesquisa
                         if secao["widget"] is item["secao"]), "Configurações"
                    )
                    self._lista_resultados_config_v2.addItem(
                        f"{nome_secao} · {item['titulo']}"
                    )
            self._lista_resultados_config_v2.setVisible(bool(termos and quantidade > 1))
        finally:
            self._lista_resultados_config_v2.blockSignals(False)

        if not termos:
            self._destacar_resultado_config_v2(None)
            self._sincronizar_navegacao_config()
        elif quantidade:
            # Prefere resultado da página atual, para não interromper o estudo.
            pagina_atual = self._pilha_paginas_config_v2.currentWidget()
            escolhido = next(
                (item for item in encontrados
                 if self._paginas_config_v2.get(item["secao"]) is pagina_atual),
                encontrados[0]
            )
            if quantidade > 1:
                self._lista_resultados_config_v2.blockSignals(True)
                try:
                    self._lista_resultados_config_v2.setCurrentIndex(
                        encontrados.index(escolhido) + 1
                    )
                finally:
                    self._lista_resultados_config_v2.blockSignals(False)
            self._abrir_resultado_config_v2(escolhido)
        else:
            self._destacar_resultado_config_v2(None)
            self.aviso_sem_resultado.setText(
                f"Nenhuma configuração encontrada para “{texto.strip()}”."
            )
        # Ao pesquisar, um resultado isolado deve ocupar a coluna inteira.
        self._ajustar_grades_preferencias_v2_m04()

