    def atualizar_status_checkpoint(self):
        try:
            auditoria = auditar_protecao_checkpoint()
            if not auditoria.get("existe"):
                self.status_ultimo_checkpoint.setText(
                    "Proteção: nenhum checkpoint nativo gerado ainda."
                )
                self.status_ultimo_checkpoint.setToolTip("")
                return

            ultimo = obter_ultimo_checkpoint()
            data = ultimo["data_modificacao"].strftime("%d/%m/%Y às %H:%M")
            tamanho_mb = ultimo["tamanho_bytes"] / (1024 * 1024)

            if auditoria.get("completo"):
                prefixo = "Proteção completa"
            elif auditoria.get("banco_incluido"):
                prefixo = "Proteção desatualizada"
            else:
                prefixo = "Proteção parcial — banco fora do checkpoint"

            self.status_ultimo_checkpoint.setText(
                f"{prefixo}: {data} • {tamanho_mb:.1f} MB • "
                f"{auditoria.get('quantidade_protegida', 0)} arquivos do projeto"
            )

            detalhes = [
                str(auditoria.get("motivo") or ""),
                f"Checkpoint: {auditoria.get('nome', '')}",
                f"Banco incluído: {'sim' if auditoria.get('banco_incluido') else 'não'}",
                f"Arquivos faltantes: {len(auditoria.get('faltantes') or [])}",
                f"Arquivos alterados depois do checkpoint: {len(auditoria.get('alterados') or [])}",
            ]
            self.status_ultimo_checkpoint.setToolTip("\n".join(detalhes))

        except Exception as erro:
            self.status_ultimo_checkpoint.setText(
                "Proteção: não foi possível auditar o checkpoint atual."
            )
            self.status_ultimo_checkpoint.setToolTip(str(erro))

    def verificar_protecao_checkpoint_config(self):
        try:
            auditoria = auditar_protecao_checkpoint()
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Falha na verificação",
                str(erro),
            )
            return

        if not auditoria.get("existe"):
            QMessageBox.warning(
                self,
                "Proteção não configurada",
                "Ainda não existe checkpoint nativo. Gere um checkpoint completo agora.",
            )
            return

        faltantes = auditoria.get("faltantes") or []
        alterados = auditoria.get("alterados") or []
        linhas = [
            "Estado: " + ("PROTEÇÃO COMPLETA" if auditoria.get("completo") else "PROTEÇÃO INCOMPLETA/DESATUALIZADA"),
            f"Versão do checkpoint: {auditoria.get('versao_checkpoint') or '—'}",
            f"Versão atual: {auditoria.get('versao_atual') or '—'}",
            f"Fontes/recursos atuais: {auditoria.get('quantidade_atual', 0)}",
            f"Fontes/recursos protegidos: {auditoria.get('quantidade_protegida', 0)}",
            f"Banco incluído: {'sim' if auditoria.get('banco_incluido') else 'não'}",
            f"Arquivos faltantes: {len(faltantes)}",
            f"Arquivos alterados desde o checkpoint: {len(alterados)}",
        ]
        if faltantes:
            linhas.append("\nFaltantes:\n• " + "\n• ".join(faltantes[:12]))
        if alterados:
            linhas.append("\nAlterados:\n• " + "\n• ".join(alterados[:12]))
        linhas.append("\n" + str(auditoria.get("motivo") or ""))

        func = QMessageBox.information if auditoria.get("completo") else QMessageBox.warning
        func(
            self,
            "Verificação de proteção",
            "\n".join(linhas),
        )

    def gerar_checkpoint_config(self):
        descricao = self.descricao_checkpoint.text().strip()
        incluir_banco = self.incluir_banco_checkpoint.isChecked()

        QApplication.setOverrideCursor(
            Qt.WaitCursor
        )

        try:
            resultado = (
                gerar_checkpoint_completo(descricao=descricao)
                if incluir_banco
                else gerar_checkpoint(
                    descricao=descricao,
                    incluir_banco=False,
                )
            )
            auditoria = auditar_protecao_checkpoint(resultado.get("caminho"))
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Falha ao gerar checkpoint",
                str(
                    erro
                )
            )
            return
        finally:
            QApplication.restoreOverrideCursor()

        self.atualizar_status_checkpoint()

        tamanho_mb = (
            resultado[
                "tamanho_bytes"
            ] / (1024 * 1024)
        )

        banco_texto = (
            "incluído"
            if resultado[
                "banco_incluido"
            ]
            else "não incluído"
        )
        protecao_texto = (
            "COMPLETA" if auditoria.get("completo")
            else "PARCIAL — gere novamente com o banco incluído"
        )

        QMessageBox.information(
            self,
            "Checkpoint concluído",
            (
                "Checkpoint criado com sucesso.\n\n"
                f"Arquivo: {resultado['nome']}\n"
                f"Arquivos preservados: {resultado['quantidade_arquivos']}\n"
                f"Banco de dados: {banco_texto}\n"
                f"Proteção verificada: {protecao_texto}\n"
                f"Tamanho: {tamanho_mb:.1f} MB\n\n"
                f"Pasta: {resultado['caminho'].parent}"
            )
        )

    def restaurar_checkpoint_config(self):
        try:
            checkpoints = listar_checkpoints()
            pasta_inicial = str(checkpoints[0]["caminho"].parent) if checkpoints else str(Path.cwd())
        except Exception:
            pasta_inicial = str(Path.cwd())

        caminho, _ = QFileDialog.getOpenFileName(
            self,
            "Selecionar checkpoint do VighnaStudy",
            pasta_inicial,
            "Checkpoint VighnaStudy (*.zip);;Arquivos ZIP (*.zip)"
        )
        if not caminho:
            return

        try:
            diagnostico = inspecionar_checkpoint(caminho)
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Checkpoint inválido",
                f"O checkpoint não passou pela verificação de integridade.\n\n{erro}",
            )
            return

        manifesto = diagnostico.get("manifesto") or {}
        criado = str(diagnostico.get("criado_em") or "").replace("T", " ")[:19] or "não informado"
        descricao = str(diagnostico.get("descricao") or "").strip() or "Sem descrição"

        caixa = QMessageBox(self)
        caixa.setIcon(QMessageBox.Warning)
        caixa.setWindowTitle("Restaurar checkpoint")
        caixa.setText("Restaurar esta versão do VighnaStudy?")
        caixa.setInformativeText(
            f"Arquivo: {diagnostico['nome']}\n"
            f"Criado em: {criado}\n"
            f"Descrição: {descricao}\n"
            f"Arquivos validados: {diagnostico['quantidade_arquivos']}\n\n"
            "Antes de restaurar, o Vighna criará automaticamente um checkpoint de segurança completo do estado atual, incluindo o banco quando ele existir. "
            "Após a operação, reinicie o programa para carregar os fontes restaurados."
        )
        caixa.setStandardButtons(QMessageBox.Yes | QMessageBox.Cancel)
        caixa.setDefaultButton(QMessageBox.Cancel)

        incluir_banco = QCheckBox(
            "Banco de dados: restauração segura somente com o Vighna fechado"
        )
        incluir_banco.setChecked(False)
        incluir_banco.setEnabled(False)
        if diagnostico.get("banco_incluido"):
            incluir_banco.setToolTip(
                "Feche o VighnaStudy e execute recuperar_banco.bat para restaurar "
                "um banco de checkpoint com tratamento seguro de WAL/SHM."
            )
        else:
            incluir_banco.setText("Este checkpoint não contém estudos.db")
        caixa.setCheckBox(incluir_banco)

        if caixa.exec() != QMessageBox.Yes:
            return

        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            resultado = restaurar_checkpoint(
                caminho,
                restaurar_banco=bool(incluir_banco.isChecked()),
            )
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Falha ao restaurar checkpoint",
                str(erro),
            )
            return
        finally:
            QApplication.restoreOverrideCursor()

        seguranca = resultado.get("checkpoint_seguranca") or {}
        seguranca_nome = seguranca.get("nome", "checkpoint de segurança")
        orientacao = (
            "Os fontes foram restaurados. Como esta execução é o Vighna compilado, execute atualizar_exe.bat antes de abrir novamente pelo EXE."
            if getattr(sys, "frozen", False)
            else "Feche e abra o VighnaStudy novamente para carregar a versão restaurada."
        )
        QMessageBox.information(
            self,
            "Checkpoint restaurado",
            (
                f"Arquivos restaurados: {len(resultado.get('arquivos_restaurados') or [])}\n"
                f"Banco restaurado: {'sim' if resultado.get('banco_restaurado') else 'não'}\n"
                f"Segurança criada: {seguranca_nome}\n\n"
                + orientacao
            ),
        )
        self.atualizar_status_checkpoint()

    def abrir_pasta_checkpoints_config(self):
        try:
            abrir_pasta_checkpoints()
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Não foi possível abrir a pasta",
                str(
                    erro
                )
            )

    def salvar(self):
        # A preferência somente é persistida quando o usuário clica em Salvar.
        if not self._pausa_animacao_home_bloqueada:
            self._preferencias_animacao_home.setValue(
                "acessibilidade/reduzir_movimento",
                self.pausar_animacao_home.isChecked(),
            )
            self._preferencias_animacao_home.sync()

        tema_escolhido = normalizar_tema(
            self.combo_tema.currentData()
        )

        definir_configuracao_texto(
            "tema_interface",
            tema_escolhido
        )

        aplicar_tema(
            QApplication.instance(),
            tema_escolhido
        )

        definir_configuracao_bool(
            "usar_importancia_fila",
            self.usar_importancia.isChecked()
        )

        definir_configuracao_bool(
            "aplicar_penalizacao_queda",
            self.aplicar_penalizacao.isChecked()
        )

        definir_configuracao_bool(
            "mostrar_modo_um_clique",
            self.mostrar_modo_um_clique.isChecked()
        )
        definir_configuracao_bool(
            "calibracao_automatica_foco",
            self.calibracao_automatica_foco.isChecked()
        )
        definir_configuracao_bool(
            "aprender_decisoes_estudar_agora",
            self.aprender_decisoes_estudar_agora.isChecked()
        )

        self.accept()


