        self.contexto.setObjectName("autoPlanContext")
        self.contexto.setWordWrap(True)
        layout.addWidget(self.contexto)

        self.tabela = QTableWidget()
        self.tabela.setObjectName("autoPlanTable")
        self.tabela.setColumnCount(7)
        self.tabela.setHorizontalHeaderLabels([
            "Incluir", "Dia", "Tipo", "Atividade", "Carga", "Por quê", "Foco"
        ])
        self.tabela.setSelectionBehavior(QAbstractItemView.SelectRows)
        self.tabela.setSelectionMode(QAbstractItemView.SingleSelection)
        self.tabela.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.tabela.verticalHeader().setVisible(False)
        self.tabela.setShowGrid(False)
        header = self.tabela.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeToContents)
        header.setSectionResizeMode(1, QHeaderView.ResizeToContents)
        header.setSectionResizeMode(2, QHeaderView.ResizeToContents)
        header.setSectionResizeMode(3, QHeaderView.Stretch)
        header.setSectionResizeMode(4, QHeaderView.ResizeToContents)
        header.setSectionResizeMode(5, QHeaderView.Stretch)
        header.setSectionResizeMode(6, QHeaderView.ResizeToContents)
        layout.addWidget(self.tabela, 1)

        acoes = QHBoxLayout()
        self.botao_regenerar = QPushButton("Regenerar")
        self.botao_regenerar.setObjectName("subtleButton")
        self.botao_regenerar.setToolTip("Gerar outra combinação usando os mesmos critérios e a mesma carga.")
        self.botao_regenerar.clicked.connect(self.regenerar)

        self.botao_substituir = QPushButton("Substituir atividade")
        self.botao_substituir.setObjectName("subtleButton")
        self.botao_substituir.setToolTip("Trocar a linha selecionada por outra prioridade relevante.")
        self.botao_substituir.clicked.connect(self.substituir)

        self.botao_redistribuir = QPushButton("Redistribuir")
        self.botao_redistribuir.setObjectName("subtleButton")
        self.botao_redistribuir.setToolTip("Balancear as ações flexíveis entre os dias sem mover revisões fixas.")
        self.botao_redistribuir.clicked.connect(self.redistribuir)

        self.botao_iniciar_proxima = QPushButton("▶ Iniciar próxima de hoje")
        self.botao_iniciar_proxima.setObjectName("autoPlanAcceptButton")
        self.botao_iniciar_proxima.setToolTip(
            "Preparar no Modo Foco a primeira atividade marcada para hoje. Se não houver, usa a próxima atividade marcada."
        )
