    def ir_para_secao_dashboard(self, chave=None, widget=None):
        """Navega à seção no seu destino real após as transferências."""
        # Atalhos antigos dos três blocos devem abrir Meu Edital, nunca o
        # Dashboard do qual os widgets foram removidos.
        secoes_edital = ("resumo", "notificacoes", "planejamento", "progresso")
        alvo_edital = {
            "resumo": getattr(self, "dashboard_resumo_painel", None),
            "notificacoes": getattr(self, "dashboard_notificacoes_painel", None),
            "planejamento": getattr(self, "dashboard_planejamento_painel", None),
            "progresso": getattr(self, "dashboard_resumo_painel", None),
        }
        if getattr(self, "_portal_edital_dashboard_raiz", None) is not None and (
            chave in secoes_edital or widget in tuple(alvo_edital.values())
        ):
            self.abrir_portal_edital()
            if chave in secoes_edital:
                self.definir_estado_secao_dashboard(chave, True, salvar=False)
            alvo = widget if widget is not None else alvo_edital.get(chave)
            scroll = getattr(self.tela_portal_edital, "portal_edital_scroll", None)
            if scroll is not None and alvo is not None:
                QTimer.singleShot(
                    0, lambda alvo=alvo, scroll=scroll:
                    scroll.ensureWidgetVisible(alvo, 0, 24)
                )
            return
        # O Estudo por questões já não reside no Dashboard. Links antigos,
        # incluindo a Busca Global, devem abrir seu novo destino único.
        if chave == "estudar" or (widget is not None and widget is getattr(self, "dashboard_estudo_questoes_painel", None)):
            self.abrir_portal_treinos()
            portal = self.tela_portal_treinos
            rolador = getattr(portal, "portal_treinos_scroll", None)
            if rolador is not None:
                QTimer.singleShot(0, lambda: rolador.ensureWidgetVisible(
                    self.dashboard_estudo_questoes_painel, 0, 24
                ))
            return
        # O04-R1: rotas antigas de busca/portal continuam alcançando os
        # mesmos cards funcionais, agora abertos pelas esferas do GIF.
        orbs = getattr(self, "_dashboard_orb_panels", None)
        if (orbs is not None and normalizar_tema(self.tema_atual) == "futurista"):
            alvo_orb = None
            if widget is getattr(self, "dashboard_hoje_acao", None) or chave == "hoje":
                alvo_orb = "recomendacao"
            elif (widget is getattr(self, "dashboard_resumo_ia", None)
                  or chave == "planejamento"):
                alvo_orb = "planejamento"
            elif widget is getattr(self, "_dashboard_foco_widget", None):
                alvo_orb = "foco"
            if alvo_orb is not None:
                self.telas.setCurrentWidget(self.tela_inicial)
                self._agendar_atualizacao_dashboard()
                QTimer.singleShot(0, lambda k=alvo_orb: orbs.open(k))
                return
        self.telas.setCurrentWidget(self.tela_inicial)
        self._agendar_atualizacao_dashboard()
        if chave:
            try:
                self.definir_estado_secao_dashboard(chave, True, salvar=False)
            except Exception:
                pass

        alvo = widget
        if alvo is None:
            if chave == "hoje":
                alvo = getattr(self, "dashboard_hoje_painel", None)
            elif chave == "estudar":
                alvo = getattr(self, "dashboard_estudo_questoes_painel", None)
            elif chave == "planejamento":
                alvo = getattr(self, "dashboard_planejamento_painel", None)

        if alvo is not None and hasattr(self, "dashboard_scroll"):
            QTimer.singleShot(
                0,
                lambda alvo=alvo: self.dashboard_scroll.ensureWidgetVisible(alvo, 0, 28),
            )

    def executar_comando_busca_global(self, comando_id):
        comando_id = str(comando_id or "")
        if comando_id == "inicio":
            self.abrir_portal_inicio()
        elif comando_id == "dashboard":
            self.voltar_inicio()
        elif comando_id == "simulados_treinos":
            self.abrir_portal_treinos()
        elif comando_id == "recursos":
            self.abrir_portal_recursos()
        elif comando_id == "foco":
            self.abrir_modo_foco()
        elif comando_id == "sessao_rapida":
            self.ir_para_secao_dashboard("hoje")
        elif comando_id == "algoritmo":
            self.ir_para_secao_dashboard(
                widget=getattr(self, "dashboard_hoje_acao", None)
            )
        elif comando_id == "estudo_questoes":
            self.ir_para_secao_dashboard("estudar")
        elif comando_id == "revisao_inteligente":
            self.abrir_revisao_inteligente_dashboard()
        elif comando_id == "treino_adaptativo":
            self.abrir_treino_adaptativo()
        elif comando_id == "simulado":
            self.abrir_simulado()
        elif comando_id == "banco_erros":
            self.abrir_banco_erros()
        elif comando_id == "central_questoes":
            self.abrir_questoes()
        elif comando_id == "estatisticas":
            self.abrir_estatisticas()
        elif comando_id == "relatorios":
            self.abrir_relatorios()
        elif comando_id == "calendario":
            self.abrir_calendario()
        elif comando_id == "pausa":
            self.abrir_pausa_desafios()
        elif comando_id == "perfis":
            self.abrir_concursos()
        elif comando_id == "configuracoes":
            self.abrir_configuracoes()
        elif comando_id == "backup":
            self.backup_manual()
        elif comando_id == "diagnostico":
            self.abrir_diagnostico_vighna()

    def abrir_busca_global(self):
        from navegacao import JanelaBuscaGlobal
        concurso = obter_concurso_ativo()
        conteudos = listar_conteudos_concurso(concurso[0])
        topicos = []
        for disciplina in conteudos:
            if not disciplina.get("incluida"):
                continue
            for topico in disciplina.get("topicos") or []:
                if not topico.get("incluido"):
                    continue
                topicos.append({
                    "disciplina_id": disciplina.get("disciplina_id"),
                    "disciplina": disciplina.get("disciplina"),
                    "topico_id": topico.get("topico_id"),
                    "topico": topico.get("topico"),
                    "importancia": topico.get("importancia", 3),
                })

        try:
            recentes = json.loads(
                obter_configuracao_texto("busca_global_recentes", "[]") or "[]"
            )
            if not isinstance(recentes, list):
                recentes = []
        except Exception:
            recentes = []

        janela = JanelaBuscaGlobal(
            self.obter_comandos_busca_global(),
            topicos=topicos,
            recentes=recentes,
            parent=self,
        )
        if janela.exec() != QDialog.Accepted or not janela.resultado:
            return

        item = janela.resultado
        if item.get("tipo") == "topico":
            topico = item.get("topico") or {}
            topico_id = topico.get("topico_id")
            topico_nome = topico.get("topico")
            if topico_id is None or not topico_nome:
                return
            JanelaTopico(int(topico_id), str(topico_nome), self).exec()
            self.notificar_dados_alterados("topicos")
            return

        comando_id = str(item.get("id") or "")
        if not comando_id:
            return

        novos_recentes = [comando_id] + [
            str(valor) for valor in recentes if str(valor) != comando_id
        ]
        definir_configuracao_texto(
            "busca_global_recentes",
            json.dumps(novos_recentes[:6], ensure_ascii=False),
        )
        self.executar_comando_busca_global(comando_id)

    def iniciar_estudo_um_clique(self):
        """Abre primeiro a recomendação do dia; o Foco só vem após confirmação."""
        return self.abrir_estudar_agora_v5()

    def criar_cartao(self, titulo):
        caixa = QFrame()
        caixa.setObjectName(
            "cardResumo"
        )
        caixa.setProperty(
            "metricRole",
            (
                "performance"
                if titulo == "Desempenho"
                else "default"
            )
        )

        caixa.setMinimumHeight(
            82
        )
        caixa.setSizePolicy(
            QSizePolicy.Expanding,
            QSizePolicy.Fixed
        )

        layout = QVBoxLayout(
            caixa
        )

        layout.setContentsMargins(
            13,
            9,
            13,
            9
        )

        layout.setSpacing(
            3
        )

        rotulo = QLabel(
            titulo
        )
        rotulo.setObjectName(
            "cardTitulo"
        )
        rotulo.setWordWrap(
            True
        )

        valor = QLabel(
            "0"
        )
        valor.setObjectName(
            "cardValor"
        )

        layout.addWidget(
            rotulo
        )
        layout.addWidget(
            valor
        )
        layout.addStretch()

        return (
            caixa,
            valor
        )

