        if hasattr(self, "jornada_dia_botao"):
            try:
                jornada_atual = carregar_jornada(concurso_id, hoje)
            except Exception:
                jornada_atual = None
            if jornada_atual:
                resumo_jornada = jornada_atual.get("resumo") or {}
                pendentes_jornada = int(resumo_jornada.get("pendentes") or 0)
                status_jornada = str(jornada_atual.get("status") or "ativa").lower()
                if status_jornada == "encerrada":
                    texto_jornada = "Jornada encerrada"
                elif resumo_jornada.get("meta_atingida"):
                    texto_jornada = "Jornada • meta atingida"
                elif pendentes_jornada:
                    texto_jornada = f"Jornada do dia ({pendentes_jornada})"
                else:
                    texto_jornada = "Jornada do dia"
                self.jornada_dia_botao.setText(texto_jornada)
                self.jornada_dia_botao.setProperty("journeyState", status_jornada)
                self.jornada_dia_botao.setToolTip(
                    f"Foco hoje: {int(resumo_jornada.get('foco_hoje_minutos') or 0)} min • "
                    f"restante operacional: {int(resumo_jornada.get('restante_minutos') or 0)} min • "
                    f"{pendentes_jornada} atividade(s) na fila."
                )
            else:
                self.jornada_dia_botao.setText("Jornada do dia")
                self.jornada_dia_botao.setProperty("journeyState", "nova")
                self.jornada_dia_botao.setToolTip(
                    "Montar uma sequência adaptativa para o restante do dia."
                )
            self.jornada_dia_botao.style().unpolish(self.jornada_dia_botao)
            self.jornada_dia_botao.style().polish(self.jornada_dia_botao)

