    def obter_secoes_recolhiveis_dashboard(self):
        return {
            "acessos": {
                "conteudo": getattr(
                    self,
                    "dashboard_acessos_conteudo",
                    None
                ),
                "botao": getattr(
                    self,
                    "dashboard_toggle_acessos",
                    None
                ),
                "subtitulo": None,
                "titulo": "Acessos rápidos",
                "config": "dashboard_secao_acessos_expandida",
            },
            "resumo": {
                "conteudo": getattr(
                    self,
                    "dashboard_resumo_conteudo",
                    None
                ),
                "botao": getattr(
                    self,
                    "dashboard_toggle_resumo",
                    None
                ),
                "subtitulo": None,
                "titulo": "Visão geral",
                "config": "dashboard_secao_resumo_expandida",
            },
            "notificacoes": {
                "conteudo": getattr(
                    self,
                    "dashboard_notificacoes_conteudo",
                    None
                ),
                "botao": getattr(
                    self,
                    "dashboard_toggle_notificacoes",
                    None
                ),
                "subtitulo": None,
                "titulo": "Notificações e alertas",
                "config": "dashboard_secao_notificacoes_expandida",
            },
            "progresso": {
                "conteudo": getattr(
                    self,
                    "dashboard_progresso_conteudo",
                    None
                ),
                "botao": getattr(
                    self,
                    "dashboard_toggle_progresso",
                    None
                ),
                "subtitulo": getattr(
                    self,
                    "dashboard_progresso_subtitulo",
                    None
                ),
                "titulo": "Progresso do edital",
                "config": "dashboard_secao_progresso_expandida",
            },
            "planejamento": {
                "conteudo": getattr(
                    self,
                    "dashboard_planejamento_conteudo",
                    None
                ),
                "botao": getattr(
                    self,
                    "dashboard_toggle_planejamento",
                    None
                ),
                "subtitulo": getattr(
                    self,
                    "dashboard_planejamento_subtitulo",
                    None
                ),
                "titulo": "Planejamento",
                "config": "dashboard_secao_planejamento_expandida",
            },
            "estudar": {
                "conteudo": getattr(
                    self,
                    "dashboard_estudar_conteudo",
                    None
                ),
                "botao": getattr(
                    self,
                    "dashboard_toggle_estudar",
                    None
                ),
                "subtitulo": getattr(
                    self,
                    "estudar_agora_subtitulo",
                    None
                ),
                "titulo": "Estudo por questões",
                "config": "dashboard_secao_estudar_expandida",
            },
        }

    def definir_estado_secao_dashboard(
        self,
        chave,
        expandida,
        salvar=True
    ):
        secoes = (
            self.obter_secoes_recolhiveis_dashboard()
        )

        secao = secoes.get(
            chave
        )

        if not secao:
            return

        expandida = bool(
            expandida
        )

        conteudo = secao[
            "conteudo"
        ]
        botao = secao[
            "botao"
        ]
        subtitulo = secao[
            "subtitulo"
        ]

        if conteudo is not None:
            conteudo.setVisible(
                expandida
            )

        if subtitulo is not None:
            subtitulo.setVisible(
                expandida
            )

        if botao is not None:
            seta = (
                "▾"
                if expandida
                else "▸"
            )

            botao.setText(
                f"{seta}  {secao['titulo']}"
            )
            botao.setToolTip(
                (
                    "Clique para recolher esta seção."
                    if expandida
                    else "Clique para expandir esta seção."
                )
            )
            botao.setProperty(
                "expanded",
                expandida
            )
            botao.style().unpolish(
                botao
            )
            botao.style().polish(
                botao
            )

        if salvar:
            definir_configuracao_bool(
                secao[
                    "config"
                ],
                expandida
            )

    def alternar_secao_dashboard(
        self,
        chave
    ):
        secoes = (
            self.obter_secoes_recolhiveis_dashboard()
        )

        secao = secoes.get(
            chave
        )

        if not secao:
            return

        conteudo = secao[
            "conteudo"
        ]

        if conteudo is None:
            return

        self.definir_estado_secao_dashboard(
            chave,
            not conteudo.isVisible(),
            salvar=True
        )

    def aplicar_estados_secoes_dashboard(self):
        # Referências aos subtítulos, criadas aqui para não duplicar
        # regras de visibilidade ao montar os layouts.
        if hasattr(
            self,
            "_progresso_subtitulo_ref"
        ):
            self.dashboard_progresso_subtitulo = (
                self._progresso_subtitulo_ref
            )

        if hasattr(
            self,
            "_planejamento_subtitulo_ref"
        ):
            self.dashboard_planejamento_subtitulo = (
                self._planejamento_subtitulo_ref
            )

        secoes = (
            self.obter_secoes_recolhiveis_dashboard()
        )

        # Dashboard Executivo V1: aplica uma única vez uma hierarquia mais
        # compacta. Depois disso, cada escolha manual do usuário é preservada.
        preset_executivo_aplicado = obter_configuracao_bool(
            "dashboard_executivo_v1_aplicado",
            False
        )

        if not preset_executivo_aplicado:
            padroes_executivos = {
                "hoje": True,
                "acessos": True,
                "resumo": True,
                "notificacoes": False,
                "progresso": True,
                "planejamento": True,
                "estudar": False,
                "fila": False,
                "disciplinas": False,
            }

            for chave, secao in secoes.items():
                expandida = padroes_executivos.get(
                    chave,
                    False
                )
                self.definir_estado_secao_dashboard(
                    chave,
                    expandida,
                    salvar=True
                )

            definir_configuracao_bool(
                "dashboard_executivo_v1_aplicado",
                True
            )
            return

        padroes = {
            "hoje": True,
            "acessos": True,
            "resumo": True,
            "notificacoes": False,
            "progresso": True,
            "planejamento": True,
            "estudar": False,
            "fila": False,
            "disciplinas": False,
        }

        for chave, secao in secoes.items():
            expandida = obter_configuracao_bool(
                secao[
                    "config"
                ],
                padroes.get(chave, False)
            )

            self.definir_estado_secao_dashboard(
                chave,
                expandida,
                salvar=False
            )

    def _estilo_disciplina_desligada_dashboard(self, tema):
        """Estilo local tokenizado; mantem a representacao anterior do QSS."""
        tema = normalizar_tema(tema)
        return (
            f"background-color:{qss_color(tema, 'dashboard.disciplines_disabled_surface')}; "
            f"color:{qss_color(tema, 'dashboard.disciplines_disabled_text')}; "
            f"border:1px solid {qss_color(tema, 'dashboard.disciplines_disabled_border')}; "
            "text-align:left; padding-left:14px;"
        )

    def atualizar_estilos_disciplinas_desligadas_dashboard(self):
        """Atualiza botoes existentes apos troca de tema, sem refazer o grid."""
        layout = getattr(self, "botoes_disciplinas_layout", None)
        if layout is None:
            return
        estilo = self._estilo_disciplina_desligada_dashboard(self.tema_atual)
        for indice in range(layout.count()):
            item = layout.itemAt(indice)
            botao = item.widget() if item is not None else None
            if botao is None or not botao.property("dashboardDisciplinaDesligada"):
                continue
            if botao.styleSheet() != estilo:
                botao.setStyleSheet(estilo)

    def carregar_botoes_disciplinas(self):
        if not hasattr(
            self,
            "botoes_disciplinas_layout"
        ):
            return

        while (
            self.botoes_disciplinas_layout.count()
            > 0
        ):
            item = (
                self.botoes_disciplinas_layout.takeAt(
                    0
                )
            )

            widget = item.widget()

            if widget is not None:
                widget.deleteLater()

        disciplinas = listar_disciplinas_gerenciamento()

        if not disciplinas:
            aviso = QLabel(
                (
                    "Nenhuma matéria está incluída neste perfil. "
                    "Use “Gerenciar perfis” → “Conteúdos do perfil”."
                )
            )
            aviso.setWordWrap(
                True
            )

            self.botoes_disciplinas_layout.addWidget(
                aviso,
                0,
                0,
                1,
                3
            )
            return

        tema_atual = normalizar_tema(
            obter_configuracao_texto("tema_interface", "claro")
        )

        for indice, (_, nome, pausada) in enumerate(
            disciplinas
        ):
            botao = QPushButton(
                nome
            )
            botao.setMinimumHeight(
                42
            )
            botao.setObjectName(
                "disciplineButton"
            )
            if pausada:
                botao.setProperty("dashboardDisciplinaDesligada", True)
                botao.setStyleSheet(
                    self._estilo_disciplina_desligada_dashboard(tema_atual)
                )
                botao.setText(f"{nome}  • desligada")
                botao.setToolTip(
                    "Disciplina desligada temporariamente. Clique para abrir e gerenciar."
                )

            botao.clicked.connect(
                lambda checked=False,
                disciplina=nome:
                    self.abrir_disciplina(
                        disciplina
                    )
            )

            linha = indice // 3
            coluna = indice % 3

            self.botoes_disciplinas_layout.addWidget(
                botao,
                linha,
                coluna
            )

    def carregar_concursos(self):
        if not hasattr(
            self,
            "combo_concurso"
        ):
            return

        concursos = listar_concursos()
        ativo_id = obter_concurso_ativo()[0]

        self.combo_concurso.blockSignals(
            True
        )

        self.combo_concurso.clear()

        indice_ativo = 0

        for indice, concurso in enumerate(
            concursos
        ):
            concurso_id = concurso[0]
            nome = concurso[1]

            self.combo_concurso.addItem(
                nome,
                concurso_id
            )

            if concurso_id == ativo_id:
                indice_ativo = indice

        if concursos:
            self.combo_concurso.setCurrentIndex(
                indice_ativo
            )

        self.combo_concurso.blockSignals(
            False
        )

    def alterar_concurso_ativo(self, indice):
        if indice < 0:
            return

        concurso_id = (
            self.combo_concurso.itemData(
                indice
            )
        )

        if concurso_id is None:
            return

        if definir_concurso_ativo(
            concurso_id
        ):
            if hasattr(self, "tela_portal_disciplinas"):
                self.tela_portal_disciplinas.atualizar(self.combo_concurso.currentText().strip())
            self.carregar_botoes_disciplinas()
            self.atualizar_dashboard()

            # O perfil mudou: snapshots analíticos do perfil anterior não podem
            # continuar marcados como limpos. Apenas invalidamos; telas ocultas
            # serão atualizadas quando realmente precisarem aparecer.
            self.invalidar_estatisticas("all", atualizar_se_visivel=True)
            self.invalidar_relatorios(atualizar_se_visivel=True)
            self._marcar_central_questoes_suja()

            if (
                hasattr(
                    self,
                    "tela_calendario"
                )
                and self.telas.currentWidget()
                == self.tela_calendario
            ):
                self.atualizar_calendario()

            if (
                hasattr(
                    self,
                    "tela_questoes"
                )
                and self.telas.currentWidget()
                == self.tela_questoes
            ):
                self.carregar_questoes()

            disciplinas_ativas = {
                nome
                for _, nome in listar_disciplinas()
            }

            if (
                self.disciplina_atual
                and self.disciplina_atual
                not in disciplinas_ativas
            ):
                self.disciplina_atual = None

    def abrir_disciplinas(self):
        janela = JanelaDisciplinas(
            self
        )
        janela.exec()

        self.carregar_botoes_disciplinas()
        self.carregar_concursos()
        if hasattr(self, "tela_portal_disciplinas"):
            self.tela_portal_disciplinas.atualizar(self.combo_concurso.currentText().strip())
        self.atualizar_dashboard()

        disciplinas_ativas = {
            nome
            for _, nome in listar_disciplinas()
        }

        if (
            self.disciplina_atual
            and self.disciplina_atual
            not in disciplinas_ativas
        ):
            self.disciplina_atual = None

        if (
            hasattr(
                self,
                "tela_relatorios"
            )
            and self.telas.currentWidget()
            == self.tela_relatorios
        ):
            self.invalidar_relatorios(atualizar_se_visivel=True)

    def abrir_concursos(self):
        janela = JanelaConcursos(
            self
        )
        janela.exec()

        self.carregar_concursos()
        self.carregar_botoes_disciplinas()
        if hasattr(self, "tela_portal_disciplinas"):
            self.tela_portal_disciplinas.atualizar(self.combo_concurso.currentText().strip())

        disciplinas_ativas = {
            nome
            for _, nome in listar_disciplinas()
        }

        if (
            self.disciplina_atual
            and self.disciplina_atual
            in disciplinas_ativas
        ):
            self.carregar_topicos()
        elif self.disciplina_atual:
            self.disciplina_atual = None

        self.atualizar_dashboard()


    def _montar_jornada_atual(self, preservar=None):
        concurso_id = int(obter_concurso_ativo()[0])
        hoje = QDate.currentDate().toString("yyyy-MM-dd")
        # Garante que a fila temporal esteja sincronizada antes de congelar a
        # sequência do dia. O Motor V5 continua sendo a fonte da primeira ação.
        if not hasattr(self, "fila_prioridade"):
            self.atualizar_dashboard()
        try:
            recomendacao = self.montar_recomendacao_estudar_agora_v4()
        except Exception:
            recomendacao = None
        try:
            plano = obter_plano_acao_automatico(concurso_id)
        except Exception:
            plano = None
        jornada = gerar_jornada(
            concurso_id,
            recomendacao=recomendacao,
            fila=list(getattr(self, "fila_prioridade", []) or []),
            plano=plano,
            data_ref=hoje,
            preservar=preservar,
        )
        return jornada

    def abrir_jornada_do_dia(self):
        concurso_id = int(obter_concurso_ativo()[0])
        hoje = QDate.currentDate().toString("yyyy-MM-dd")
        jornada = carregar_jornada(concurso_id, hoje)
        if not jornada or str(jornada.get("status") or "") == "encerrada":
            try:
                jornada = self._montar_jornada_atual()
            except Exception as erro:
                QMessageBox.critical(
                    self,
                    "Jornada do Dia",
                    f"Não foi possível montar a Jornada de hoje.\n\n{erro}",
                )
                return
        janela = JanelaJornadaDia(jornada, self)
        janela.exec()
        self.notificar_dados_alterados("all")

    def recalcular_jornada_do_dia(self):
        concurso_id = int(obter_concurso_ativo()[0])
        hoje = QDate.currentDate().toString("yyyy-MM-dd")
        atual = carregar_jornada(concurso_id, hoje)
        try:
            jornada = self._montar_jornada_atual(preservar=atual)
        except Exception as erro:
            QMessageBox.warning(
                self,
                "Recalcular Jornada",
                f"Não foi possível recalcular o restante da Jornada.\n\n{erro}",
            )
            return atual or {}
        self.notificar_dados_alterados("all")
        return jornada

    def _registrar_decisao_item_jornada(self, item, decisao, minutos=None):
        item = dict(item or {})
        if item.get("origem_item") not in {"recomendacao_v4", "recomendacao_v5"}:
            return
        if not obter_configuracao_bool("aprender_decisoes_estudar_agora", True):
            return
        meta = dict(item.get("recomendacao") or {})
        recomendacao = {
            **meta,
            "disciplina": item.get("disciplina"),
            "topico_id": item.get("topico_id"),
            "topico": item.get("topico"),
            "atividade": item.get("atividade"),
            "minutos": int(item.get("minutos") or 0),
            "questoes_alvo": int(item.get("questoes_alvo") or 0),
            "score_total": float(item.get("prioridade") or meta.get("score_total") or 0.0),
        }
        try:
            registro_id = registrar_recomendacao_estudo(obter_concurso_ativo()[0], recomendacao)
            atualizar_decisao_recomendacao(registro_id, decisao, minutos)
            self.cache_analitico.invalidar("inteligencia:decisoes")
        except Exception:
            pass

    def iniciar_item_jornada(self, item):
        item = dict(item or {})
        concurso_id = int(obter_concurso_ativo()[0])
        hoje = QDate.currentDate().toString("yyyy-MM-dd")
        jornada = carregar_jornada(concurso_id, hoje)
        if jornada and str(jornada.get("status") or "ativa") == "pausada":
            QMessageBox.information(
                self,
                "Jornada pausada",
                "Retome a Jornada antes de iniciar uma nova atividade.",
            )
            return
        item_id = item.get("id")
        if item_id:
            # Preparar o Foco não equivale a iniciar o cronômetro. Mantemos a
            # atividade pendente até existir uma sessão real registrada.
            marcar_item_jornada(
                concurso_id,
                item_id,
                "pendente",
                hoje,
                preparada_em=datetime.now().isoformat(timespec="seconds"),
            )
        self._registrar_decisao_item_jornada(item, "aceita_direta", item.get("minutos"))
        preparacao = preparar_item_jornada(item, hoje, concurso_id)
        self.notificar_dados_alterados("all")
        self.abrir_modo_foco(preparacao)

    def iniciar_proxima_jornada(self):
        concurso_id = int(obter_concurso_ativo()[0])
        hoje = QDate.currentDate().toString("yyyy-MM-dd")
        jornada = carregar_jornada(concurso_id, hoje)
        if not jornada:
            jornada = self._montar_jornada_atual()
        if str(jornada.get("status") or "ativa") == "pausada":
            jornada = definir_status_jornada(concurso_id, "ativa", hoje)
        item = proximo_item_jornada(jornada)
        if not item:
            resumo = (jornada or {}).get("resumo") or {}
            if resumo.get("meta_atingida"):
                QMessageBox.information(
                    self,
                    "Jornada concluída",
                    "O ritmo operacional do dia já foi atingido e não há outra atividade pendente.",
                )
            else:
                jornada = self.recalcular_jornada_do_dia()
                item = proximo_item_jornada(jornada)
        if item:
            self.iniciar_item_jornada(item)

    def pular_item_jornada(self, item):
        item = dict(item or {})
        concurso_id = int(obter_concurso_ativo()[0])
        hoje = QDate.currentDate().toString("yyyy-MM-dd")
        self._registrar_decisao_item_jornada(item, "ignorada")
        jornada = marcar_item_jornada(
            concurso_id,
            item.get("id"),
            "pulada",
            hoje,
            pulada_em=datetime.now().isoformat(timespec="seconds"),
        )
        self.notificar_dados_alterados("all")
        return jornada or {}

    def alternar_pausa_jornada(self):
        concurso_id = int(obter_concurso_ativo()[0])
        hoje = QDate.currentDate().toString("yyyy-MM-dd")
        jornada = carregar_jornada(concurso_id, hoje)
        if not jornada:
            jornada = self._montar_jornada_atual()
        status_atual = str(jornada.get("status") or "ativa")
        novo = "ativa" if status_atual == "pausada" else "pausada"
        jornada = definir_status_jornada(concurso_id, novo, hoje)
        self.notificar_dados_alterados("all")
        return jornada or {}

    def encerrar_jornada_do_dia(self):
        concurso_id = int(obter_concurso_ativo()[0])
        hoje = QDate.currentDate().toString("yyyy-MM-dd")
        jornada = definir_status_jornada(concurso_id, "encerrada", hoje)
        self.notificar_dados_alterados("all")
        return jornada or {}

    def tratar_sessao_finalizada_jornada(self, dados):
        dados = dict(dados or {})
        if str(dados.get("origem") or "") != "Jornada do Dia":
            return
        concurso_id = int(obter_concurso_ativo()[0])
        try:
            marcar_jornada_por_plano_chave(
                concurso_id,
                dados.get("plano_chave"),
                bool(dados.get("concluida")),
                sessao_id=dados.get("sessao_id"),
                duracao_efetiva=dados.get("duracao_efetiva"),
            )
        except Exception:
            return
        self.notificar_dados_alterados("all")

    def abrir_plano_acao_automatico(self):
        concurso_id = obter_concurso_ativo()[0]
        janela = JanelaPlanoAcaoAutomatico(concurso_id, self)
        if janela.exec() == QDialog.Accepted:
            self.atualizar_dashboard()

    def abrir_fechamento_semanal(self):
        concurso = obter_concurso_ativo()
        try:
            dados = obter_fechamento_semanal(
                QDate.currentDate().toString("yyyy-MM-dd"),
                concurso[0],
            )
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Fechamento semanal",
                f"Não foi possível consolidar a semana.\n\n{erro}",
            )
            return
        janela = JanelaFechamentoSemanal(dados, self)
        aceitou = janela.exec() == QDialog.Accepted
        if aceitou and getattr(janela, "continuar", False):
            QTimer.singleShot(0, self.abrir_estudar_agora_v4)

    def abrir_redistribuicao_carga(self):
        concurso_id = (
            obter_concurso_ativo()[0]
        )

        janela = JanelaRedistribuicao(
            concurso_id,
            self
        )

        if janela.exec() == QDialog.Accepted:
            self.atualizar_dashboard()

            if hasattr(
                self,
                "tela_calendario"
            ):
                self.atualizar_calendario()

    def abrir_configuracao_planejamento(self):
        janela = JanelaPlanejamento(
            self
        )

        if janela.exec() == QDialog.Accepted:
            self.atualizar_dashboard()

    def atualizar_metrica_meta_semanal(
        self,
        chave,
        atual,
        meta,
        dias_restantes,
        unidade,
        permitir_ritmo=True
    ):
        widgets = (
            self.metas_semanais_widgets[
                chave
            ]
        )

        atual = int(
            atual
            or 0
        )
        meta = int(
            meta
            or 0
        )

        if meta <= 0:
            widgets["valor"].setText(
                f"{atual} {unidade}"
            )
            widgets["barra"].setValue(
                0
            )
            widgets["dica"].setText(
                "Meta desativada"
            )
            estado = "desativada"

        else:
            percentual = round(
                100.0
                * atual
                / meta
            )

            widgets["valor"].setText(
                f"{atual} / {meta}"
            )

            widgets["barra"].setValue(
                min(
                    100,
                    max(
                        0,
                        int(
                            percentual
                        )
                    )
                )
            )

            restante = max(
                0,
                meta - atual
            )

            if restante == 0:
                widgets["dica"].setText(
                    "Meta concluída"
                )
                estado = "concluida"

            elif permitir_ritmo:
                ritmo = (
                    restante
                    / max(
                        1,
                        dias_restantes
                    )
                )

                if chave == "questoes":
                    ritmo_texto = (
                        f"{ritmo:.0f} por dia"
                    )
                elif chave == "revisoes":
                    ritmo_texto = (
                        f"{ritmo:.1f} por dia"
                    )
                else:
                    ritmo_texto = (
                        f"{restante} dia(s) ainda necessários"
                    )

                widgets["dica"].setText(
                    f"Faltam {restante} • {ritmo_texto}"
                )
                estado = "andamento"

            else:
                widgets["dica"].setText(
                    f"Faltam {restante}"
                )
                estado = "andamento"

        widgets["dica"].setProperty(
            "goalState",
            estado
        )
        widgets["barra"].setProperty(
            "goalState",
            estado
        )

        for widget in (
            widgets["dica"],
            widgets["barra"]
        ):
            widget.style().unpolish(
                widget
            )
            widget.style().polish(
                widget
            )

    def atualizar_meta_semanal_dashboard(
        self,
        concurso_id,
        hoje_qdate
    ):
        inicio_semana = hoje_qdate.addDays(
            -(
                hoje_qdate.dayOfWeek()
                - 1
            )
        )
        fim_semana = inicio_semana.addDays(
            6
        )

        inicio_texto = inicio_semana.toString(
            "yyyy-MM-dd"
        )
        hoje_texto = hoje_qdate.toString(
            "yyyy-MM-dd"
        )

        resumo_semana = obter_metricas_periodo_nucleo(
            inicio_texto,
            hoje_texto,
            concurso_id
        ).get("metrics", {})

        questoes = int(
            resumo_semana.get("answered_attempt_count", {}).get("value", 0)
            or 0
        )
        revisoes = int(
            resumo_semana.get("completed_review_count", {}).get("value", 0)
            or 0
        )
        dias_estudados = int(
            resumo_semana.get("study_day_count", {}).get("value", 0)
            or 0
        )

        meta_questoes = max(
            0,
            obter_configuracao_int(
                "meta_questoes_semanal",
                0
            )
        )
        meta_revisoes = max(
            0,
            obter_configuracao_int(
                "meta_revisoes_semanal",
                0
            )
        )
        meta_dias = max(
            0,
            min(
                7,
                obter_configuracao_int(
                    "meta_dias_estudo_semanal",
                    0
                )
            )
        )

        dias_restantes = max(
            1,
            hoje_qdate.daysTo(
                fim_semana
            )
            + 1
        )

        self.meta_semanal_periodo.setText(
            (
                f"{inicio_semana.toString('dd/MM')} "
                f"— {fim_semana.toString('dd/MM')}"
            )
        )

        self.atualizar_metrica_meta_semanal(
            "questoes",
            questoes,
            meta_questoes,
            dias_restantes,
            "questões",
            True
        )
        self.atualizar_metrica_meta_semanal(
            "revisoes",
            revisoes,
            meta_revisoes,
            dias_restantes,
            "revisões",
            True
        )
        self.atualizar_metrica_meta_semanal(
            "dias",
            dias_estudados,
            meta_dias,
            dias_restantes,
            "dias",
            False
        )

        metas_ativas = [
            (
                questoes,
                meta_questoes
            ),
            (
                revisoes,
                meta_revisoes
            ),
            (
                dias_estudados,
                meta_dias
            ),
        ]

        metas_ativas = [
            (
                atual,
                meta
            )
            for atual, meta in metas_ativas
            if meta > 0
        ]

        if not metas_ativas:
            texto_situacao = (
                "Sem metas definidas"
            )
            estado = "desativada"

        elif all(
            atual >= meta
            for atual, meta in metas_ativas
        ):
            texto_situacao = (
                "Semana concluída"
            )
            estado = "concluida"

        else:
            dias_decorridos = max(
                1,
                inicio_semana.daysTo(
                    hoje_qdate
                )
                + 1
            )

            proporcao_tempo = (
                dias_decorridos
                / 7.0
            )

            proporcoes = [
                min(
                    1.0,
                    atual
                    / meta
                )
                for atual, meta in metas_ativas
            ]

            progresso_medio = (
                sum(
                    proporcoes
                )
                / len(
                    proporcoes
                )
            )

            # Pequena tolerância para não alarmar por variações normais.
            if progresso_medio + 0.08 >= proporcao_tempo:
                texto_situacao = (
                    "No ritmo"
                )
                estado = "andamento"
            else:
                texto_situacao = (
                    "Abaixo do ritmo"
                )
                estado = "atencao"

        # Situação individual de cada meta para o card compacto do topo.
        dias_decorridos_compacto = max(
            1,
            inicio_semana.daysTo(hoje_qdate) + 1
        )
        proporcao_tempo_compacto = dias_decorridos_compacto / 7.0

        def situacao_meta_compacta(atual, meta):
            atual = int(atual or 0)
            meta = int(meta or 0)
            if meta <= 0:
                return {"texto": "Não definida", "estado": "desativada"}
            if atual >= meta:
                return {"texto": "Concluída", "estado": "concluida"}
            progresso = min(1.0, atual / meta)
            if progresso + 0.08 >= proporcao_tempo_compacto:
                return {"texto": "No ritmo", "estado": "andamento"}
            return {"texto": "Atenção", "estado": "atencao"}

        resumo_compacto_semana = {
            "questoes": situacao_meta_compacta(questoes, meta_questoes),
            "revisoes": situacao_meta_compacta(revisoes, meta_revisoes),
            "dias": situacao_meta_compacta(dias_estudados, meta_dias),
        }

        metas_semanais_ativas = bool(
            metas_ativas
        )

        self.meta_semanal_vazio.setVisible(
            not metas_semanais_ativas
        )
        self.meta_semanal_metricas_container.setVisible(
            metas_semanais_ativas
        )

        self.meta_semanal_situacao.setText(
            texto_situacao
        )
        self.meta_semanal_situacao.setProperty(
            "weekState",
            estado
        )
        self.meta_semanal_situacao.style().unpolish(
            self.meta_semanal_situacao
        )
        self.meta_semanal_situacao.style().polish(
            self.meta_semanal_situacao
        )

        return {
            "geral": {"texto": texto_situacao, "estado": estado},
            **resumo_compacto_semana,
        }

    def atualizar_planejamento_dashboard(
        self,
        concurso_id,
        hoje_qdate,
        resumo_revisoes=None
    ):
        hoje_texto = hoje_qdate.toString(
            "yyyy-MM-dd"
        )

        resumo_semana_compacto = self.atualizar_meta_semanal_dashboard(
            concurso_id,
            hoje_qdate
        ) or {}

        if hasattr(self, "dashboard_planejamento_resumo_semana"):
            geral_semana = resumo_semana_compacto.get("geral", {})
            self.dashboard_planejamento_resumo_semana.setText(
                geral_semana.get("texto") or "—"
            )
            self.dashboard_planejamento_resumo_semana.setProperty(
                "weekState", geral_semana.get("estado") or "desativada"
            )
            self.dashboard_planejamento_resumo_semana.style().unpolish(
                self.dashboard_planejamento_resumo_semana
            )
            self.dashboard_planejamento_resumo_semana.style().polish(
                self.dashboard_planejamento_resumo_semana
            )

        if hasattr(self, "dashboard_planejamento_semana_labels"):
            for chave, label in self.dashboard_planejamento_semana_labels.items():
                dados_status = resumo_semana_compacto.get(chave, {})
                label.setText(dados_status.get("texto") or "—")
                label.setProperty(
                    "weekState", dados_status.get("estado") or "desativada"
                )
                label.style().unpolish(label)
                label.style().polish(label)

        resumo_revisoes = resumo_revisoes or {}
        revisoes_hoje = int(resumo_revisoes.get("hoje", 0) or 0)
        revisoes_atrasadas = int(resumo_revisoes.get("atrasadas", 0) or 0)
        revisoes_pendentes = revisoes_hoje + revisoes_atrasadas

        if hasattr(self, "dashboard_planejamento_resumo_pendencias"):
            self.dashboard_planejamento_resumo_pendencias.setText(
                str(revisoes_pendentes)
            )
            if revisoes_pendentes <= 0:
                detalhe_pendencias = "Fila do dia em ordem"
            else:
                partes_pendencias = []
                if revisoes_atrasadas:
                    partes_pendencias.append(
                        f"{revisoes_atrasadas} atrasada"
                        + ("s" if revisoes_atrasadas != 1 else "")
                    )
                if revisoes_hoje:
                    partes_pendencias.append(f"{revisoes_hoje} para hoje")
                detalhe_pendencias = " • ".join(partes_pendencias)
            self.dashboard_planejamento_resumo_pendencias_detalhe.setText(
                detalhe_pendencias
            )

        # ----------------------------------------------------
        # META DIÁRIA DE QUESTÕES
        # ----------------------------------------------------

        meta = max(
            0,
            obter_configuracao_int(
                "meta_questoes_diaria",
                60
            )
        )

        relatorio_hoje = obter_metricas_periodo_nucleo(
            hoje_texto,
            hoje_texto,
            concurso_id
        ).get("metrics", {})

        questoes_hoje = int(
            relatorio_hoje.get("answered_attempt_count", {}).get("value", 0)
            or 0
        )

        # Planejamento compacto no topo do Dashboard (Futurista): usar os
        # mesmos dados ja calculados acima, sem consulta e sem pontuacao nova.
        painel_topo = getattr(self, "dashboard_quick_nav", None)
        if painel_topo is not None and hasattr(painel_topo, "planejamento_faixa"):
            dias = ("Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado", "Domingo")
            painel_topo.planejamento_data.setText(
                f"{dias[hoje_qdate.dayOfWeek() - 1]} • {hoje_qdate.toString('dd/MM')}"
            )
            if meta > 0:
                percentual_topo = round(100.0 * questoes_hoje / meta)
                painel_topo.planejamento_questoes.setText(
                    f"{questoes_hoje} / {meta} questões"
                )
                painel_topo.planejamento_percentual.setText(
                    f"{percentual_topo}% concluído"
                )
                painel_topo.planejamento_barra.setValue(
                    min(100, max(0, int(percentual_topo)))
                )
            else:
                painel_topo.planejamento_questoes.setText(
                    f"{questoes_hoje} questões"
                )
                painel_topo.planejamento_percentual.setText("Meta desativada")
                painel_topo.planejamento_barra.setValue(0)
            painel_topo.planejamento_revisoes.setText(
                f"{revisoes_pendentes} "
                + ("revisão" if revisoes_pendentes == 1 else "revisões")
            )
            painel_topo.planejamento_revisoes.setToolTip(
                f"{revisoes_hoje} para hoje • {revisoes_atrasadas} atrasadas"
            )

        if meta > 0:
            percentual_meta = round(
                100.0
                * questoes_hoje
                / meta
            )

            percentual_barra = min(
                100,
                max(
                    0,
                    int(
                        percentual_meta
                    )
                )
            )

            self.meta_questoes_progresso.setText(
                f"{questoes_hoje} / {meta} questões"
            )

            self.meta_questoes_barra.setValue(
                percentual_barra
            )

            if questoes_hoje >= meta:
                excedente = (
                    questoes_hoje
                    - meta
                )

                if excedente > 0:
                    texto_status = (
                        f"Meta concluída • +{excedente} questões"
                    )
                else:
                    texto_status = (
                        "Meta concluída"
                    )

                estado = "concluida"
            else:
                faltam = (
                    meta
                    - questoes_hoje
                )

                texto_status = (
                    f"{percentual_meta}% da meta • faltam {faltam}"
                )

                estado = "andamento"

            self.meta_questoes_status.setText(
                texto_status
            )
            self.meta_questoes_status.setProperty(
                "goalState",
                estado
            )
            self.meta_questoes_barra.setProperty(
                "goalState",
                estado
            )

        else:
            self.meta_questoes_progresso.setText(
                f"{questoes_hoje} questões hoje"
            )
            self.meta_questoes_barra.setValue(
                0
            )
            self.meta_questoes_status.setText(
                "Meta diária desativada"
            )
            self.meta_questoes_status.setProperty(
                "goalState",
                "desativada"
            )
            self.meta_questoes_barra.setProperty(
                "goalState",
                "desativada"
            )

        if hasattr(self, "dashboard_planejamento_resumo_meta_diaria"):
            if meta > 0:
                self.dashboard_planejamento_resumo_meta_diaria.setText(
                    f"{questoes_hoje} / {meta}"
                )
                if questoes_hoje >= meta:
                    excedente = max(0, questoes_hoje - meta)
                    detalhe_hero = "Meta concluída"
                    if excedente > 0:
                        detalhe_hero += f" • +{excedente} questões"
                else:
                    faltam_hero = max(0, meta - questoes_hoje)
                    detalhe_hero = (
                        f"{percentual_meta}% concluído • faltam {faltam_hero}"
                    )
                self.dashboard_planejamento_resumo_meta_diaria_detalhe.setText(
                    detalhe_hero
                )
                self.dashboard_resumo_meta_barra.setValue(
                    min(100, max(0, int(percentual_meta)))
                )
                if hasattr(self, "dashboard_planejamento_meta_gauge"):
                    self.dashboard_planejamento_meta_gauge.setProgress(
                        questoes_hoje,
                        meta,
                    )
            else:
                self.dashboard_planejamento_resumo_meta_diaria.setText(
                    f"{questoes_hoje} hoje"
                )
                self.dashboard_planejamento_resumo_meta_diaria_detalhe.setText(
                    "Meta diária desativada"
                )
                self.dashboard_resumo_meta_barra.setValue(0)
                if hasattr(self, "dashboard_planejamento_meta_gauge"):
                    self.dashboard_planejamento_meta_gauge.setProgress(
                        questoes_hoje,
                        0,
                    )

        if hasattr(self, "dashboard_planejamento_carga_valor"):
            if meta > 0:
                faltam_questoes = max(0, meta - questoes_hoje)
                self.dashboard_planejamento_carga_valor.setText(
                    f"{faltam_questoes} "
                    + ("questão" if faltam_questoes == 1 else "questões")
                )
            else:
                self.dashboard_planejamento_carga_valor.setText(
                    "Meta desativada"
                )

            if revisoes_pendentes > 0:
                self.dashboard_planejamento_carga_detalhe.setText(
                    f"+ {revisoes_pendentes} "
                    + (
                        "revisão pendente"
                        if revisoes_pendentes == 1
                        else "revisões pendentes"
                    )
                )
            else:
                self.dashboard_planejamento_carga_detalhe.setText(
                    "Sem revisões pendentes"
                )

        if hasattr(self, "dashboard_planejamento_status_dia"):
            if meta > 0 and questoes_hoje >= meta and revisoes_pendentes <= 0:
                status_dia = "CONCLUÍDO"
                estado_dia = "concluida"
            elif revisoes_atrasadas > 0:
                status_dia = "ATENÇÃO"
                estado_dia = "atencao"
            elif meta > 0 and questoes_hoje >= meta:
                status_dia = "META CONCLUÍDA"
                estado_dia = "concluida"
            else:
                status_dia = "EM ANDAMENTO"
                estado_dia = "andamento"

            self.dashboard_planejamento_status_dia.setText(status_dia)
            self.dashboard_planejamento_status_dia.setProperty(
                "weekState", estado_dia
            )
            self.dashboard_planejamento_status_dia.style().unpolish(
                self.dashboard_planejamento_status_dia
            )
            self.dashboard_planejamento_status_dia.style().polish(
                self.dashboard_planejamento_status_dia
            )

        for widget in (
            self.meta_questoes_status,
            self.meta_questoes_barra
        ):
            widget.style().unpolish(
                widget
            )
            widget.style().polish(
                widget
            )

        # ----------------------------------------------------
        # CARGA DOS PRÓXIMOS 7 DIAS
        # ----------------------------------------------------

        fim_qdate = hoje_qdate.addDays(
            6
        )

        agendadas = listar_revisoes_agendadas_periodo(
            hoje_texto,
            fim_qdate.toString(
                "yyyy-MM-dd"
            ),
            concurso_id
        )

        contagem_por_data = {}

        for revisao in agendadas:
            data_revisao = revisao[4]

            contagem_por_data[
                data_revisao
            ] = (
                contagem_por_data.get(
                    data_revisao,
                    0
                )
                + 1
            )

        total_7d = sum(
            contagem_por_data.values()
        )

        if total_7d == 1:
            texto_total = (
                "1 revisão em 7 dias"
            )
        else:
            texto_total = (
                f"{total_7d} revisões em 7 dias"
            )

        self.planejamento_total_7d.setText(
            texto_total
        )

        sugerir_automaticamente = obter_configuracao_bool(
            "redistribuicao_sugerir_automaticamente",
            True
        )

        carga_maxima_redistribuicao = max(
            1,
            obter_configuracao_int(
                "redistribuicao_carga_maxima",
                8
            )
        )

        dias_sobrecarga = 0

        for indice in range(
            1,
            7
        ):
            data_verificada = hoje_qdate.addDays(
                indice
            )

            if (
                contagem_por_data.get(
                    data_verificada.toString(
                        "yyyy-MM-dd"
                    ),
                    0
                )
                > carga_maxima_redistribuicao
            ):
                dias_sobrecarga += 1

        if (
            sugerir_automaticamente
            and dias_sobrecarga > 0
        ):
            self.redistribuir_carga_botao.setText(
                f"Redistribuir carga ({dias_sobrecarga})"
            )
            self.redistribuir_carga_botao.setProperty(
                "hasSuggestion",
                True
            )
        else:
            self.redistribuir_carga_botao.setText(
                "Redistribuir carga"
            )
            self.redistribuir_carga_botao.setProperty(
                "hasSuggestion",
                False
            )

        self.redistribuir_carga_botao.style().unpolish(
            self.redistribuir_carga_botao
        )
        self.redistribuir_carga_botao.style().polish(
            self.redistribuir_carga_botao
        )

        nomes_semana = {
            1: "Seg",
            2: "Ter",
            3: "Qua",
            4: "Qui",
            5: "Sex",
            6: "Sáb",
            7: "Dom",
        }

        for indice, card in enumerate(
            self.carga_semana_cards
        ):
            data = hoje_qdate.addDays(
                indice
            )

            data_texto = data.toString(
                "yyyy-MM-dd"
            )

            quantidade = int(
                contagem_por_data.get(
                    data_texto,
                    0
                )
            )

            if indice == 0:
                nome_dia = "Hoje"
            elif indice == 1:
                nome_dia = "Amanhã"
            else:
                nome_dia = nomes_semana[
                    data.dayOfWeek()
                ]

            card["nome"].setText(
                nome_dia
            )
            card["data"].setText(
                data.toString(
                    "dd/MM"
                )
            )
            card["quantidade"].setText(
                str(
                    quantidade
                )
            )

            limite_leve = max(
                1,
                obter_configuracao_int(
                    "planejamento_limite_leve",
                    2
                )
            )

            limite_moderada = max(
                limite_leve + 1,
                obter_configuracao_int(
                    "planejamento_limite_moderada",
                    5
                )
            )

            if quantidade == 0:
                carga = "vazia"
            elif quantidade <= limite_leve:
                carga = "leve"
            elif quantidade <= limite_moderada:
                carga = "moderada"
            else:
                carga = "alta"

            card["box"].setProperty(
                "loadLevel",
                carga
            )
            card["box"].setProperty(
                "today",
                indice == 0
            )

            card["box"].style().unpolish(
                card["box"]
            )
            card["box"].style().polish(
                card["box"]
            )

    def atualizar_hoje_operacional_dashboard(
        self,
        resumo,
        resumo_foco,
        concurso_id,
        hoje_qdate,
    ):
        """Atualiza a visão operacional diária sem duplicar a lógica de prioridade."""
        if not hasattr(self, "dashboard_hoje_painel"):
            return

        dias_semana = {
            1: "Segunda",
            2: "Terça",
            3: "Quarta",
            4: "Quinta",
            5: "Sexta",
            6: "Sábado",
            7: "Domingo",
        }
        nome_dia = dias_semana.get(hoje_qdate.dayOfWeek(), "Hoje")
        self.dashboard_hoje_data.setText(
            f"{nome_dia} • {hoje_qdate.toString('dd/MM')}"
        )
        if hasattr(self, "dashboard_resumo_data"):
            self.dashboard_resumo_data.setText(
                f"{nome_dia} • {hoje_qdate.toString('dd/MM')}"
            )

        hoje_iso = hoje_qdate.toString("yyyy-MM-dd")
        hoje_foco = int(resumo_foco.get("hoje_segundos", 0) or 0)
        hoje_sessoes = int(resumo_foco.get("hoje_sessoes", 0) or 0)
        hoje_concluidas = int(resumo_foco.get("hoje_concluidas", 0) or 0)

        # Foco: o alvo diário é uma referência derivada das metas semanais,
        # nunca um registro fictício de estudo.
        self.dashboard_hoje_foco_valor.setText(
            formatar_tempo_foco_resumido(hoje_foco)
        )
        if hasattr(self, "dashboard_resumo_hoje"):
            self.dashboard_resumo_hoje.setText(
                formatar_tempo_foco_resumido(hoje_foco)
            )
        if hasattr(self, "dashboard_focus_metric_today"):
            self.dashboard_focus_metric_today.setText(
                formatar_tempo_foco_resumido(hoje_foco)
                + " de foco hoje"
            )
        if hasattr(self, "dashboard_focus_metric_sessions"):
            self.dashboard_focus_metric_sessions.setText(
                f"{hoje_sessoes} "
                + ("sessão" if hoje_sessoes == 1 else "sessões")
                + " hoje"
            )
        meta_foco_horas = max(
            0,
            obter_configuracao_int("meta_foco_semanal_horas", 0),
        )
        meta_dias = max(
            0,
            min(
                7,
                obter_configuracao_int("meta_dias_estudo_semanal", 0),
            ),
        )

        if meta_foco_horas > 0:
            divisor_dias = meta_dias if meta_dias > 0 else 7
            alvo_dia = int(round(meta_foco_horas * 3600 / divisor_dias))
            percentual_dia = (
                int(round(100.0 * hoje_foco / alvo_dia))
                if alvo_dia > 0
                else 0
            )
            restante_dia = max(0, alvo_dia - hoje_foco)
            self.dashboard_hoje_foco_barra.setVisible(True)
            self.dashboard_hoje_foco_barra.setValue(
                min(100, max(0, percentual_dia))
            )
            if hasattr(self, "dashboard_focus_goal_value"):
                self.dashboard_focus_goal_value.setText(
                    formatar_tempo_foco_resumido(hoje_foco)
                    + " / "
                    + formatar_tempo_foco_resumido(alvo_dia)
                )
            if restante_dia <= 0:
                self.dashboard_hoje_foco_detalhe.setText(
                    "Ritmo diário da meta semanal atingido"
                )
                if hasattr(self, "dashboard_focus_metric_goal"):
                    self.dashboard_focus_metric_goal.setText(
                        "Meta semanal • ritmo diário atingido"
                    )
            else:
                restante_texto = formatar_tempo_foco_resumido(restante_dia)
                self.dashboard_hoje_foco_detalhe.setText(
                    "Faltam "
                    + restante_texto
                    + " para o ritmo diário"
                )
                if hasattr(self, "dashboard_focus_metric_goal"):
                    self.dashboard_focus_metric_goal.setText(
                        "Meta semanal • faltam " + restante_texto + " hoje"
                    )
            self.dashboard_hoje_foco_detalhe.setToolTip(
                "Referência diária: "
                + formatar_tempo_foco_resumido(alvo_dia)
                + ". Calculada a partir da meta semanal de foco"
                + (
                    f" distribuída por {meta_dias} dia(s) de estudo."
                    if meta_dias > 0
                    else " distribuída pelos 7 dias da semana."
                )
            )
        else:
            self.dashboard_hoje_foco_barra.setVisible(False)
            if hasattr(self, "dashboard_focus_goal_value"):
                self.dashboard_focus_goal_value.setText("Meta não definida")
            self.dashboard_hoje_foco_detalhe.setText(
                "Defina uma meta semanal para acompanhar seu ritmo diário."
            )
            if hasattr(self, "dashboard_focus_metric_goal"):
                self.dashboard_focus_metric_goal.setText(
                    "Meta semanal desativada"
                )
            self.dashboard_hoje_foco_detalhe.setToolTip(
                "Ative Foco semanal em Definir metas para acompanhar um ritmo diário de referência."
            )

        ultima_sessao = resumo_foco.get("ultima_sessao") or {}
        melhor_semana = resumo_foco.get("melhor_sessao_semana") or {}

        def _contexto_foco(item):
            disciplina = str(item.get("disciplina") or "").strip()
            topico = str(item.get("topico") or "").strip()
            if disciplina and topico:
                return f"{disciplina} • {topico}"
            return disciplina or topico or "Livre / outros"

        if hasattr(self, "dashboard_focus_last_session"):
            if ultima_sessao:
                self.dashboard_focus_last_session.setText(
                    "Última sessão: "
                    + formatar_tempo_foco_resumido(
                        int(ultima_sessao.get("segundos") or 0)
                    )
                    + " • "
                    + _contexto_foco(ultima_sessao)
                )
            else:
                self.dashboard_focus_last_session.setText("Última sessão: —")

        if hasattr(self, "dashboard_focus_best_week"):
            if melhor_semana:
                self.dashboard_focus_best_week.setText(
                    "Melhor sessão da semana: "
                    + formatar_tempo_foco_resumido(
                        int(melhor_semana.get("segundos") or 0)
                    )
                    + " • "
                    + _contexto_foco(melhor_semana)
                )
            else:
                self.dashboard_focus_best_week.setText(
                    "Melhor sessão da semana: —"
                )

        # Revisões exigindo ação agora.
        revisoes_hoje = int(resumo.get("hoje", 0) or 0)
        revisoes_atrasadas = int(resumo.get("atrasadas", 0) or 0)
        revisoes_pendentes = revisoes_hoje + revisoes_atrasadas
        if hasattr(self, "dashboard_resumo_pendencias"):
            self.dashboard_resumo_pendencias.setText(str(revisoes_pendentes))
        if revisoes_pendentes <= 0:
            revisoes_detalhe = "Fila em dia"
            revisao_role = "ok"
        else:
            partes = []
            if revisoes_atrasadas:
                partes.append(
                    f"{revisoes_atrasadas} atrasada"
                    + ("s" if revisoes_atrasadas != 1 else "")
                )
            if revisoes_hoje:
                partes.append(f"{revisoes_hoje} para hoje")
            revisoes_detalhe = " • ".join(partes)
            revisao_role = "late" if revisoes_atrasadas else "today"

        # Sessões reais do Modo Foco no dia.
        if hoje_sessoes <= 0:
            sessoes_detalhe = "Nenhuma sessão com tempo efetivo"
        elif hoje_sessoes == hoje_concluidas:
            sessoes_detalhe = (
                f"{hoje_concluidas} concluída"
                + ("s" if hoje_concluidas != 1 else "")
            )
        else:
            sessoes_detalhe = (
                f"{hoje_concluidas} concluída"
                + ("s" if hoje_concluidas != 1 else "")
                + f" • {hoje_sessoes} registrada"
                + ("s" if hoje_sessoes != 1 else "")
            )

        # Questões: usa o mesmo histórico consolidado das revisões.
        # Isso inclui tanto registros manuais quanto sessões do Banco de
        # Questões consolidadas automaticamente, sem somar a mesma sessão
        # duas vezes.
        try:
            linhas_hoje = obter_relatorio_diario_periodo(
                hoje_iso,
                hoje_iso,
                concurso_id,
            )
        except Exception:
            linhas_hoje = []

        respondidas = sum(
            int(linha[2] or 0)
            for linha in linhas_hoje
        )
        acertos_hoje = sum(
            int(linha[3] or 0)
            for linha in linhas_hoje
        )
        percentual = (
            100.0 * acertos_hoje / respondidas
            if respondidas > 0
            else None
        )
        if respondidas > 0 and percentual is not None:
            questoes_detalhe = (
                f"{float(percentual):.0f}% de acerto • "
                f"{acertos_hoje} certas"
            )
            questao_role = (
                "ok" if float(percentual) >= 70.0 else "today"
            )
        else:
            questoes_detalhe = "Nenhuma registrada hoje"
            questao_role = "neutral"
        self.dashboard_hoje_questoes_card.setProperty(
            "metricRole",
            questao_role,
        )

        meta_questoes = max(
            0,
            obter_configuracao_int("meta_questoes_diaria", 0),
        )

        # Próxima ação. O Modo Foco é apenas um cronômetro auxiliar e não
        # substitui nem bloqueia a recomendação operacional do Dashboard.
        action_role = "neutral"
        botao_texto = "Por que esta recomendação?"
        botao_um_clique_texto = "▶  COMEÇAR AGORA"
        estado_pronto = "PRÓXIMA SESSÃO"
        subtitulo_algoritmo = "O Vighna prepara automaticamente sua próxima sessão."
        recomendacao = None

        sessao_pausada = (
            getattr(self, "sessao_ativa", False)
            and getattr(self, "sessao_pausada", False)
        )

        if sessao_pausada:
            titulo_acao = "Retomar sessão pausada"
            detalhe_acao = "Existe uma sessão anterior esperando continuidade."
            action_role = "active"
            botao_texto = "Por que esta recomendação?"
            botao_um_clique_texto = "▶  CONTINUAR SESSÃO"
            estado_pronto = "SESSÃO PAUSADA"
            subtitulo_algoritmo = "Há uma sessão pausada pronta para continuar."
        else:
            try:
                recomendacao = self.montar_recomendacao_estudar_agora_v4()
            except Exception:
                recomendacao = None

            if recomendacao:
                estado_pronto = "PRÓXIMA SESSÃO PRONTA"
                subtitulo_algoritmo = (
                    "Sua próxima sessão foi definida com base no motor de inteligência do Vighna."
                )
                disciplina = str(recomendacao.get("disciplina") or "").strip()
                topico = str(recomendacao.get("topico") or "").strip()
                origem = str(recomendacao.get("origem") or "").strip().lower()
                motivos = list(recomendacao.get("motivos") or [])
                descricao = str(recomendacao.get("descricao_sessao") or "").strip()

                if disciplina and topico:
                    titulo_acao = f"{disciplina} — {topico}"
                elif disciplina:
                    titulo_acao = disciplina
                elif origem == "livre":
                    titulo_acao = "Sessão livre para manter o ritmo"
                else:
                    titulo_acao = "Preparar próxima sessão"

                detalhe_partes = []
                if motivos:
                    detalhe_partes.append(str(motivos[0]).strip())
                if descricao:
                    detalhe_partes.append(descricao)
                detalhe_acao = " • ".join(
                    parte for parte in detalhe_partes if parte
                ) or "O Vighna encontrou uma próxima ação possível."

                if origem == "revisao":
                    action_role = "late"
                elif origem == "adaptativa":
                    action_role = "strategic"
                else:
                    action_role = "neutral"
            else:
                titulo_acao = "Encontrar próxima sessão"
                detalhe_acao = "O Estudar Agora pode analisar o momento atual."

        self.dashboard_hoje_botao.setText(botao_texto)
        if hasattr(self, "dashboard_algoritmo_pronto"):
            self.dashboard_algoritmo_pronto.setText(estado_pronto)
        if hasattr(self, "dashboard_algoritmo_subtitulo"):
            self.dashboard_algoritmo_subtitulo.setText(subtitulo_algoritmo)
        if hasattr(self, "dashboard_hoje_um_clique"):
            self.dashboard_hoje_um_clique.setText(botao_um_clique_texto)
            self.dashboard_hoje_um_clique.setVisible(
                obter_configuracao_bool("mostrar_modo_um_clique", True)
            )
        self.dashboard_hoje_acao.setProperty("actionRole", action_role)

        # Resumo do dia: informativo, alinhado ao que será aberto em
        # Começar agora, sem competir com a ação principal.
        if sessao_pausada:
            self.dashboard_hoje_resumo_disciplina.setText("SESSÃO PAUSADA")
            self.dashboard_hoje_resumo_topico.setText(titulo_acao)
            self.dashboard_hoje_resumo_contexto.setText(
                "Ao clicar em Começar agora, o Vighna continuará a sessão pausada."
            )
            self.dashboard_hoje_dominio_valor.setText("—")
            self.dashboard_hoje_dominio_detalhe.setText("continuidade")
            self.dashboard_hoje_recente_valor.setText("—")
            self.dashboard_hoje_recente_detalhe.setText("desempenho do tópico")
            self.dashboard_hoje_pratica_valor.setText(str(hoje_concluidas))
            self.dashboard_hoje_pratica_detalhe.setText(sessoes_detalhe)
        elif recomendacao:
            disciplina = str(recomendacao.get("disciplina") or "").strip()
            topico = str(recomendacao.get("topico") or "").strip()
            motivo_resumo = []
            if questoes_detalhe and questoes_detalhe != "Nenhuma registrada hoje":
                motivo_resumo.append(questoes_detalhe)
            minutos = int(recomendacao.get("minutos") or 0)
            if minutos > 0:
                motivo_resumo.append(f"~{minutos} min")
            questoes_alvo = int(recomendacao.get("questoes_alvo") or 0)
            if questoes_alvo > 0:
                motivo_resumo.append(f"{questoes_alvo} questões")
            if not motivo_resumo:
                motivo_resumo.append("Conteúdo recomendado pelo algoritmo")

            self.dashboard_hoje_resumo_disciplina.setText(
                disciplina.upper() if disciplina else "RECOMENDADO"
            )
            self.dashboard_hoje_resumo_topico.setText(
                topico or titulo_acao
            )
            self.dashboard_hoje_resumo_contexto.setText(
                " • ".join(motivo_resumo)
            )

            try:
                topico_id = int(recomendacao.get("topico_id") or 0)
            except Exception:
                topico_id = 0

            indice_topico = {}
            resumo_topico = {}
            if topico_id > 0:
                try:
                    indices_dominio = self.cache_analitico.obter(
                        f"dashboard:dominio:{concurso_id}",
                        lambda: obter_indices_dominio_topicos(concurso_id),
                        ttl=20,
                    )
                except Exception:
                    indices_dominio = {}
                indice_topico = dict(indices_dominio.get(topico_id) or {})
                try:
                    resumo_topico = obter_resumo_topico(topico_id, concurso_id)
                except Exception:
                    resumo_topico = {}

            score_dominio = indice_topico.get("score")
            if score_dominio is not None:
                self.dashboard_hoje_dominio_valor.setText(
                    f"{int(round(float(score_dominio)))}%"
                )
                nivel = str(indice_topico.get("nivel") or "").strip()
                self.dashboard_hoje_dominio_detalhe.setText(
                    nivel.capitalize() if nivel else "Domínio V2"
                )
            else:
                self.dashboard_hoje_dominio_valor.setText("—")
                self.dashboard_hoje_dominio_detalhe.setText("ainda sem índice")

            recente_topico = indice_topico.get("desempenho_recente")
            if recente_topico is not None and float(recente_topico) > 0:
                self.dashboard_hoje_recente_valor.setText(
                    f"{int(round(float(recente_topico)))}%"
                )
                self.dashboard_hoje_recente_detalhe.setText("acerto recente")
            else:
                self.dashboard_hoje_recente_valor.setText("—")
                self.dashboard_hoje_recente_detalhe.setText("sem prática recente")

            pratica_total = int(
                indice_topico.get("tentativas_historicas")
                or indice_topico.get("tentativas")
                or 0
            )
            revisoes_total = int(
                indice_topico.get("revisoes")
                or resumo_topico.get("revisoes_programa")
                or 0
            )
            self.dashboard_hoje_pratica_valor.setText(str(pratica_total))
            if pratica_total > 0:
                self.dashboard_hoje_pratica_detalhe.setText(
                    f"{revisoes_total} revisões registradas"
                )
            else:
                self.dashboard_hoje_pratica_detalhe.setText(
                    "ainda sem histórico interno"
                )
        else:
            self.dashboard_hoje_resumo_disciplina.setText("HOJE")
            self.dashboard_hoje_resumo_topico.setText(
                "Nenhum conteúdo recomendado no momento"
            )
            self.dashboard_hoje_resumo_contexto.setText(
                "Use Começar agora para o Vighna analisar a fila atual."
            )
            self.dashboard_hoje_dominio_valor.setText("—")
            self.dashboard_hoje_dominio_detalhe.setText("sem conteúdo")
            self.dashboard_hoje_recente_valor.setText("—")
            self.dashboard_hoje_recente_detalhe.setText("sem conteúdo")
            self.dashboard_hoje_pratica_valor.setText(str(respondidas))
            self.dashboard_hoje_pratica_detalhe.setText(questoes_detalhe)

        if meta_questoes > 0:
            restante_questoes = max(0, meta_questoes - respondidas)
            self.dashboard_hoje_meta_questoes_valor.setText(
                f"{respondidas}/{meta_questoes}"
            )
            self.dashboard_hoje_meta_questoes_detalhe.setText(
                "Meta atingida"
                if restante_questoes <= 0
                else f"{restante_questoes} restante" + ("s" if restante_questoes != 1 else "")
            )
        else:
            self.dashboard_hoje_meta_questoes_valor.setText(str(respondidas))
            self.dashboard_hoje_meta_questoes_detalhe.setText(
                "meta diária desativada"
            )

        self.dashboard_hoje_meta_foco_valor.setText(
            formatar_tempo_foco_resumido(hoje_foco)
        )
        if meta_foco_horas > 0 and alvo_dia > 0:
            self.dashboard_hoje_meta_foco_detalhe.setText(
                "Meta atingida"
                if restante_dia <= 0
                else "Faltam " + formatar_tempo_foco_resumido(restante_dia)
            )
        else:
            self.dashboard_hoje_meta_foco_detalhe.setText(
                "meta semanal desativada"
            )

        self.dashboard_hoje_meta_revisoes_valor.setText(str(revisoes_pendentes))
        self.dashboard_hoje_meta_revisoes_detalhe.setText(revisoes_detalhe)
        self.dashboard_hoje_meta_revisoes_card.setProperty(
            "metricRole",
            revisao_role,
        )

        # Cabeçalho enxuto: mostra apenas a urgência da fila de revisão.
        if revisoes_atrasadas:
            status_hoje = (
                f"{revisoes_atrasadas} "
                + ("revisão atrasada" if revisoes_atrasadas == 1 else "revisões atrasadas")
            )
        elif revisoes_hoje:
            status_hoje = (
                f"{revisoes_hoje} "
                + ("revisão para hoje" if revisoes_hoje == 1 else "revisões para hoje")
            )
        else:
            status_hoje = "Fila de revisão em dia"
        self.dashboard_hoje_status.setText(status_hoje)

        for card in (
            self.dashboard_hoje_questoes_card,
            self.dashboard_hoje_meta_revisoes_card,
            self.dashboard_hoje_acao,
        ):
            card.style().unpolish(card)
            card.style().polish(card)

    def atualizar_dashboard(self):
        hoje_qdate = QDate.currentDate()

        hoje = hoje_qdate.toString(
            "yyyy-MM-dd"
        )

        concurso_id = (
            obter_concurso_ativo()[0]
        )

        # Questões Primeiro: o Dashboard mantém visível o estado do núcleo
        # de aprendizagem, sem depender da abertura do Banco de Questões.
        metricas_nucleo = {}
        try:
            nucleo = self.cache_analitico.obter(
                f"nucleo:global:{int(concurso_id)}:all",
                lambda: obter_metricas_globais_nucleo(concurso_id),
                ttl=30,
            )
            metricas_nucleo = nucleo.get("metrics", {})

            def valor_nucleo(chave, padrao=None):
                return metricas_nucleo.get(chave, {}).get("value", padrao)

            total_nucleo = int(valor_nucleo("answered_attempt_count", 0) or 0)
            topicos_nucleo = int(
                metricas_nucleo.get("topic_coverage_rate", {})
                .get("parameters", {})
                .get("answered_active_topics", 0)
                or 0
            )
            erros_nucleo = int(valor_nucleo("incorrect_attempt_count", 0) or 0)
            respondidas_nucleo = total_nucleo
            desempenho_nucleo = valor_nucleo("accuracy_rate")

            if hasattr(
                self,
                "dashboard_nucleo_questoes_total"
            ):
                self.dashboard_nucleo_questoes_total.setText(
                    f"{total_nucleo} questões"
                )
                self.dashboard_nucleo_questoes_topicos.setText(
                    f"{topicos_nucleo} tópicos"
                )
                self.dashboard_nucleo_questoes_erros.setText(
                    f"{erros_nucleo} erros registrados"
                )
                self.dashboard_nucleo_questoes_desempenho.setText(
                    (
                        "Desempenho "
                        + f"{float(desempenho_nucleo):.1f}%".replace(
                            ".",
                            ","
                        )
                    )
                    if respondidas_nucleo > 0 and desempenho_nucleo is not None
                    else "Desempenho —"
                )
        except Exception:
            pass

        try:
            pendentes_banco_erros = contar_banco_erros_pendentes(concurso_id)
        except Exception:
            pendentes_banco_erros = 0
        if hasattr(self, "banco_erros_resumo"):
            self.banco_erros_resumo.setText(
                "1 pendente"
                if pendentes_banco_erros == 1
                else f"{pendentes_banco_erros} pendentes"
            )

        resumo = obter_dashboard(
            hoje,
            concurso_id,
            metricas_nucleo
        )

        resumo_foco = obter_resumo_foco(hoje)
        regularidade = self.cache_analitico.obter(
            f"regularidade:{hoje}",
            lambda: obter_snapshot_regularidade(hoje),
            ttl=20,
        )
        self.atualizar_regularidade_dashboard(regularidade)

        # ----------------------------------------------------
        # Ritmo de estudo — tempo real do Modo Foco
        # ----------------------------------------------------
        hoje_foco = int(
            resumo_foco.get("hoje_segundos", 0)
            or 0
        )
        semana_foco = int(
            resumo_foco.get("semana_segundos", 0)
            or 0
        )
        sessoes_semana = int(
            resumo_foco.get("semana_sessoes", 0)
            or 0
        )
        media_semana = int(
            resumo_foco.get("media_sessao_semana", 0)
            or 0
        )
        dias_foco = int(
            resumo_foco.get("dias_com_foco_semana", 0)
            or 0
        )

        self.status_total_dashboard.setText(
            formatar_tempo_foco_resumido(hoje_foco)
        )
        self.status_subtitulo_dashboard.setText(
            "foco efetivo hoje"
        )
        self.ritmo_semana_dashboard.setText(
            formatar_tempo_foco_resumido(semana_foco)
        )
        self.ritmo_sessoes_dashboard.setText(
            str(sessoes_semana)
        )

        meta_foco_horas = max(
            0,
            obter_configuracao_int(
                "meta_foco_semanal_horas",
                0
            )
        )

        if hasattr(self, "dashboard_resumo_meta"):
            if meta_foco_horas > 0:
                meta_foco_segundos_resumo = meta_foco_horas * 3600
                percentual_meta_resumo = int(round(
                    100.0 * semana_foco / meta_foco_segundos_resumo
                )) if meta_foco_segundos_resumo else 0
                self.dashboard_resumo_meta.setText(
                    formatar_tempo_foco_resumido(semana_foco)
                    + f" / {meta_foco_horas}h"
                )
                self.dashboard_resumo_meta_barra.setValue(
                    min(100, max(0, percentual_meta_resumo))
                )
            else:
                self.dashboard_resumo_meta.setText("Não definida")
                self.dashboard_resumo_meta_barra.setValue(0)

        if meta_foco_horas > 0:
            meta_foco_segundos = meta_foco_horas * 3600
            percentual_foco = round(
                100.0 * semana_foco / meta_foco_segundos
            ) if meta_foco_segundos else 0
            self.ritmo_meta_texto.setText(
                "Meta semanal: "
                + formatar_tempo_foco_resumido(semana_foco)
                + f" / {meta_foco_horas}h • {percentual_foco}%"
            )
            self.ritmo_meta_barra.setVisible(True)
            self.ritmo_meta_barra.setValue(
                min(100, max(0, int(percentual_foco)))
            )
            restante_foco = max(
                0,
                meta_foco_segundos - semana_foco
            )
            self.ritmo_meta_texto.setToolTip(
                "Meta calculada apenas com tempo efetivo do Modo Foco. "
                + (
                    "Meta concluída."
                    if restante_foco == 0
                    else "Faltam "
                    + formatar_tempo_foco_resumido(restante_foco)
                    + " nesta semana."
                )
            )
        else:
            self.ritmo_meta_barra.setVisible(False)
            self.ritmo_meta_texto.setText(
                "Média por sessão: "
                + formatar_tempo_foco_resumido(media_semana)
                + f" • {dias_foco} "
                + ("dia com foco" if dias_foco == 1 else "dias com foco")
            )
            self.ritmo_meta_texto.setToolTip(
                "Defina uma meta em Definir metas → Metas semanais → Foco semanal "
                "para acompanhar horas e progresso semanal."
            )

        hoje_revisoes = int(resumo.get("hoje", 0) or 0)
        atrasadas_revisoes = int(resumo.get("atrasadas", 0) or 0)
        total_pendencias_dashboard = hoje_revisoes + atrasadas_revisoes
        self.status_contexto_dashboard.setText(
            "Revisões: "
            + (
                "nenhuma pendência"
                if total_pendencias_dashboard == 0
                else (
                    f"{total_pendencias_dashboard} "
                    + ("pendência" if total_pendencias_dashboard == 1 else "pendências")
                    + f" • {hoje_revisoes} hoje • {atrasadas_revisoes} "
                    + ("atrasada" if atrasadas_revisoes == 1 else "atrasadas")
                )
            )
        )
        self.status_contexto_dashboard.setProperty(
            "statusRole",
            "attention" if atrasadas_revisoes > 0 else "ok"
        )
        self.status_contexto_dashboard.style().unpolish(
            self.status_contexto_dashboard
        )
        self.status_contexto_dashboard.style().polish(
            self.status_contexto_dashboard
        )

        distribuicao = list(
            resumo_foco.get("distribuicao_semana")
            or []
        )
        if distribuicao:
            principais = distribuicao[:2]
            resumo_dist = " • ".join(
                f"{item.get('disciplina', 'Livre / outros')} "
                f"{formatar_tempo_foco_resumido(item.get('segundos', 0))}"
                for item in principais
            )
            self.ritmo_distribuicao_dashboard.setText(
                "Mais tempo: " + resumo_dist
            )
            linhas_tooltip = [
                "Distribuição semanal pelo tempo real do Modo Foco:"
            ]
            for item in distribuicao:
                linhas_tooltip.append(
                    f"{item.get('disciplina', 'Livre / outros')}: "
                    f"{formatar_tempo_foco_resumido(item.get('segundos', 0))} "
                    f"({float(item.get('percentual', 0) or 0):.1f}%)"
                )
            self.ritmo_distribuicao_dashboard.setToolTip(
                "\n".join(linhas_tooltip).replace(".", ",")
            )
        else:
            self.ritmo_distribuicao_dashboard.setText(
                "Mais tempo: ainda sem sessões vinculadas nesta semana"
            )
            self.ritmo_distribuicao_dashboard.setToolTip(
                "Vincule disciplina e tópico ao iniciar o Modo Foco para formar a distribuição semanal."
            )

        self.atualizar_planejamento_dashboard(
            concurso_id,
            hoje_qdate,
            resumo
        )

        progresso_snapshot_dashboard = self.atualizar_progresso_dashboard(
            concurso_id,
            metricas_nucleo
        )
        try:
            self.atualizar_gamificacao_dashboard(
                concurso_id=concurso_id,
                progresso_snapshot=progresso_snapshot_dashboard,
                regularidade_snapshot=regularidade,
            )
        except Exception:
            pass

        self.card_media.setText(
            formatar_percentual(
                resumo["media_atual"]
            )
        )

        # ----------------------------------------------------
        # Tendência oficial de desempenho — performance_trend@1
        # ----------------------------------------------------

        tendencia_metrica = metricas_nucleo.get("performance_trend", {})
        tendencia_valor = tendencia_metrica.get("value")
        tendencia_role = "none"
        if (
            tendencia_metrica.get("state") != "ok"
            or tendencia_valor == "insufficient_data"
        ):
            tendencia_texto = "Dados insuficientes"
            faltas = tendencia_metrica.get("missing_requirements", {})
            detalhes_faltas = []
            for chave, rotulo in (
                ("attempts_needed", "tentativas"),
                ("sessions_needed", "sessões"),
                ("days_needed", "dias"),
            ):
                quantidade = int(faltas.get(chave, 0) or 0)
                if quantidade:
                    detalhes_faltas.append(f"{quantidade} {rotulo}")
            self.dashboard_tendencia_label.setText(
                "performance_trend@1"
                + (
                    " • faltam " + ", ".join(detalhes_faltas)
                    if detalhes_faltas else " • base insuficiente"
                )
            )
        elif tendencia_valor == "improvement":
            tendencia_role = "positive"
            tendencia_texto = "Melhora"
            self.dashboard_tendencia_label.setText(
                "performance_trend@1 • janelas consecutivas de tentativas"
            )
        elif tendencia_valor == "decline":
            tendencia_role = "negative"
            tendencia_texto = "Queda"
            self.dashboard_tendencia_label.setText(
                "performance_trend@1 • janelas consecutivas de tentativas"
            )
        else:
            tendencia_role = "stable"
            tendencia_texto = "Estável"
            self.dashboard_tendencia_label.setText(
                "performance_trend@1 • janelas consecutivas de tentativas"
            )

        self.dashboard_tendencia_valor.setText(tendencia_texto)
        self.dashboard_tendencia_valor.setProperty(
            "trendRole",
            tendencia_role
        )
        self.dashboard_tendencia_valor.style().unpolish(
            self.dashboard_tendencia_valor
        )
        self.dashboard_tendencia_valor.style().polish(
            self.dashboard_tendencia_valor
        )

        pendencias = listar_pendencias(
            hoje,
            concurso_id
        )

        usar_importancia_fila = (
            obter_configuracao_bool(
                "usar_importancia_fila",
                True
            )
        )

        # A fila operacional usa a mesma pontuação canônica da Fila Inteligente
        # V3. Assim Dashboard, Revisão Inteligente, Treino Adaptativo e o Motor
        # de Recomendação deixam de manter critérios de prioridade paralelos.
        try:
            prioridades_dashboard = self.cache_analitico.obter(
                f"adaptativas:{int(concurso_id)}",
                lambda: list(obter_prioridades_sessao_adaptativa(concurso_id) or []),
                ttl=30,
            )
            ranking_fila_v3 = {
                int(item["topico_id"]): item
                for item in prioridades_dashboard
                if item.get("topico_id") not in (None, "")
            }
        except Exception:
            ranking_fila_v3 = {}

        fila = []

        for dado in pendencias:
            topico_id = dado[0]
            disciplina = dado[1]
            topico = dado[2]
            revisoes = dado[3]
            proxima = dado[4]
            percentual = dado[5]
            importancia = dado[6]

            prioridade_v3 = ranking_fila_v3.get(int(topico_id))
            if prioridade_v3:
                score = float(prioridade_v3.get("score_fila") or 0.0)
                nivel = str(prioridade_v3.get("nivel_fila") or "MÉDIA")
                motivo = str(prioridade_v3.get("motivo_fila") or "prioridade consolidada")
                contribuicoes = dict(prioridade_v3.get("contribuicoes_fila") or {})
                principais = sorted(
                    contribuicoes.items(),
                    key=lambda item: float(item[1] or 0.0),
                    reverse=True,
                )[:3]
                rotulos = {
                    "atraso": "atraso",
                    "dominio": "domínio",
                    "erros_recentes": "erros",
                    "queda": "queda",
                    "importancia": "importância",
                    "cobertura": "cobertura",
                    "revisoes": "revisões",
                    "espacamento": "espaçamento",
                }
                if principais:
                    motivo += " • " + " • ".join(
                        f"{rotulos.get(chave, chave)} {float(valor):.1f}"
                        for chave, valor in principais
                        if float(valor or 0.0) > 0
                    )
            else:
                score, nivel, motivo = calcular_prioridade(
                    proxima,
                    percentual,
                    revisoes,
                    importancia,
                    usar_importancia_fila
                )

            fila.append({
                "topico_id": topico_id,
                "disciplina": disciplina,
                "topico": topico,
                "revisoes": revisoes,
                "proxima": proxima,
                "percentual": percentual,
                "importancia": importancia,
                "score": score,
                "nivel": nivel,
                "motivo": motivo,
                "versao_fila": "fila_inteligente_v3" if prioridade_v3 else "legado",
                "score_fila": float(score),
                "componentes_fila": dict(prioridade_v3.get("componentes_fila") or {}) if prioridade_v3 else {},
                "contribuicoes_fila": dict(prioridade_v3.get("contribuicoes_fila") or {}) if prioridade_v3 else {},
                "pesos_fila": dict(prioridade_v3.get("pesos_fila") or {}) if prioridade_v3 else {},
                "detalhes_fila": dict(prioridade_v3.get("detalhes_fila") or {}) if prioridade_v3 else {},
            })

        fila.sort(
            key=lambda item: (
                -item["score"],
                item["proxima"],
                item["disciplina"].lower(),
                item["topico"].lower()
            )
        )

        # Mantém a fila disponível para o modo "Estudar agora".
        self.fila_prioridade = fila

        self.atualizar_hoje_operacional_dashboard(
            resumo,
            resumo_foco,
            concurso_id,
            hoje_qdate,
        )

        sessao_pausada_ativa = (
            getattr(
                self,
                "sessao_ativa",
                False
            )
            and getattr(
                self,
                "sessao_pausada",
                False
            )
        )

        # Este setor é deliberadamente secundário ao Começar agora.
        # Mantemos o cabeçalho estável para não duplicar a recomendação
        # principal do Dashboard dentro dos modos alternativos de questões.
        self.botao_estudar_agora.setEnabled(False)
        self.botao_estudar_agora.setVisible(False)
        if hasattr(self, "estudar_agora_subtitulo"):
            self.estudar_agora_subtitulo.setText(
                "Escolha como deseja praticar: revisar, treinar, simular ou recuperar pendências."
            )

        # Resumo visual de "Estudar agora".
        atrasadas_fila = sum(
            1
            for item in fila
            if str(
                item.get(
                    "proxima",
                    ""
                )
            ) < hoje
        )

        hoje_fila = sum(
            1
            for item in fila
            if str(
                item.get(
                    "proxima",
                    ""
                )
            ) == hoje
        )

        criticos_fila = sum(
            1
            for item in fila
            if str(item.get("nivel") or "").strip().upper() in {
                "ALTA", "CRÍTICA", "CRITICA"
            }
        )
        if hasattr(self, "dashboard_resumo_pendencias"):
            self.dashboard_resumo_pendencias.setText(str(len(fila)))

        if len(fila) == 0:
            self.revisao_inteligente_resumo.setText(
                "Nenhuma revisão prioritária agora"
            )
            self.revisao_inteligente_detalhe.setText(
                (
                    "A fila está em dia. O Treino Adaptativo continua "
                    "disponível para estudo estratégico."
                )
            )
            self.botao_revisao_inteligente.setEnabled(
                False
            )
        else:
            self.revisao_inteligente_resumo.setText(
                f"{len(fila)} revisão(ões) prioritária(s)"
            )

            partes = []

            if atrasadas_fila:
                partes.append(
                    f"{atrasadas_fila} atrasada(s)"
                )

            if hoje_fila:
                partes.append(
                    f"{hoje_fila} vence(m) hoje"
                )

            if not partes:
                partes.append(
                    "fila ordenada por prioridade"
                )

            prioridade_agora = fila[0]
            disciplina_prioridade = str(
                prioridade_agora.get("disciplina") or ""
            ).strip()
            topico_prioridade = str(
                prioridade_agora.get("topico") or ""
            ).strip()
            motivo_prioridade = str(
                prioridade_agora.get("motivo") or ""
            ).strip()
            destino_prioridade = " — ".join(
                parte for parte in (
                    disciplina_prioridade,
                    topico_prioridade,
                )
                if parte
            )
            contexto_fila = " • ".join(partes)
            detalhe_partes = []
            if destino_prioridade:
                detalhe_partes.append(f"Próximo: {destino_prioridade}")
            if contexto_fila:
                detalhe_partes.append(contexto_fila)
            if motivo_prioridade:
                detalhe_partes.append(motivo_prioridade)
            try:
                cobertura_prioridade = obter_estado_cobertura_revisao(
                    int(prioridade_agora.get("topico_id")),
                    concurso_id,
                )
            except Exception:
                cobertura_prioridade = None
            if (
                cobertura_prioridade
                and cobertura_prioridade.get("ativa")
                and int(cobertura_prioridade.get("total") or 0) > 0
            ):
                detalhe_partes.append(
                    "Cobertura da revisão: "
                    f"{cobertura_prioridade['cobertas']}/{cobertura_prioridade['total']} "
                    f"• {cobertura_prioridade['restantes']} restante(s)"
                )
            self.revisao_inteligente_detalhe.setText(
                " • ".join(detalhe_partes)
                or "A Revisão Inteligente começa pelo conteúdo mais prioritário da fila."
            )
            self.botao_revisao_inteligente.setEnabled(
                True
            )

        # Resumo do Simulado no Dashboard.
        try:
            resumo_simulados = obter_resumo_simulados_dashboard(
                concurso_id
            )
        except Exception:
            resumo_simulados = {
                "realizados": 0,
                "ultimo_percentual": None,
                "melhor_percentual": None,
            }

        def formatar_simulado_dashboard(
            valor
        ):
            if valor is None:
                return "—"

            return (
                f"{float(valor):.1f}%"
                .replace(".", ",")
            )

        self.simulado_ultimo_dashboard.setText(
            formatar_simulado_dashboard(
                resumo_simulados.get(
                    "ultimo_percentual"
                )
            )
        )
        self.simulado_melhor_dashboard.setText(
            formatar_simulado_dashboard(
                resumo_simulados.get(
                    "melhor_percentual"
                )
            )
        )
        self.simulado_total_dashboard.setText(
            str(
                int(
                    resumo_simulados.get(
                        "realizados",
                        0
                    )
                    or 0
                )
            )
        )

        self.tabela_pendentes.setRowCount(
            len(fila)
        )

        if len(fila) == 0:
            self.rotulo_fila_contagem.setText(
                "• tudo em dia"
            )
        elif len(fila) == 1:
            self.rotulo_fila_contagem.setText(
                "• 1 pendência"
            )
        else:
            self.rotulo_fila_contagem.setText(
                f"• {len(fila)} pendências"
            )

        for linha, item_fila in enumerate(
            fila
        ):
            valores = [
                item_fila["disciplina"],
                item_fila["topico"],
                str(item_fila["revisoes"]),
                formatar_data(
                    item_fila["proxima"]
                ),
                formatar_percentual(
                    item_fila["percentual"]
                ),
                "",
                "",
                item_fila["motivo"],
                f"{item_fila['score']:.1f}"
                .replace(".", ",")
            ]

            for coluna, valor in enumerate(
                valores
            ):
                # Importância e prioridade são desenhadas abaixo.
                if coluna in (
                    5,
                    6
                ):
                    continue

                item = QTableWidgetItem(
                    valor
                )

                if coluna == 1:
                    item.setData(
                        Qt.UserRole,
                        item_fila["topico_id"]
                    )

                if coluna in (
                    2,
                    3,
                    4,
                    8
                ):
                    item.setTextAlignment(
                        Qt.AlignCenter
                    )

                self.tabela_pendentes.setItem(
                    linha,
                    coluna,
                    item
                )

            estrelas = IndicadorEstrelasFila(
                item_fila[
                    "importancia"
                ]
            )

            self.tabela_pendentes.setCellWidget(
                linha,
                5,
                estrelas
            )

            chamas = IndicadorChamasPrioridade(
                item_fila[
                    "nivel"
                ]
            )

            self.tabela_pendentes.setCellWidget(
                linha,
                6,
                chamas
            )

            self.tabela_pendentes.setRowHeight(
                linha,
                32
            )

        self._dashboard_sujo = False
        self._dashboard_data_referencia = hoje

    def abrir_simulado(self):
        concurso = obter_concurso_ativo()

        disponibilidade = (
            obter_disponibilidade_simulado_disciplinas(
                concurso[0]
            )
        )

        if not disponibilidade:
            QMessageBox.information(
                self,
                "Simulados",
                (
                    "O perfil ativo ainda não possui questões internas "
                    "suficientes para montar um simulado."
                )
            )
            return

        configurador = JanelaConfigurarSimulado(
            self
        )

        if configurador.exec() != QDialog.Accepted:
            return

        if not configurador.configuracao:
            return

        try:
            janela = JanelaResolverQuestoes(
                configurador.configuracao,
                self
            )
            janela.exec_nao_modal()
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Simulados",
                (
                    "Não foi possível iniciar o simulado.\n\n"
                    f"{erro}"
                )
            )
            return

        if hasattr(
            self,
            "carregar_questoes"
        ):
            self.carregar_questoes()

        self.atualizar_dashboard()

        if hasattr(self, "invalidar_estatisticas"):
            self.invalidar_estatisticas("questoes")

    def abrir_central_efetividade(self):
        janela = JanelaCentralEfetividade(
            self
        )
        janela.exec()

    def abrir_treino_adaptativo(self):
        concurso = obter_concurso_ativo()

        disponiveis = listar_questoes_resolucao(
            concurso[0]
        )

        if not disponiveis:
            QMessageBox.information(
                self,
                "Treino adaptativo",
                (
                    "O perfil ativo ainda não possui questões internas "
                    "disponíveis. Cadastre ou importe questões antes de "
                    "iniciar um treino adaptativo."
                )
            )
            return

        configuracao = JanelaConfigurarSessaoAdaptativa(
            self
        )

        if configuracao.exec() != QDialog.Accepted:
            return

        if not configuracao.configuracao:
            return

        try:
            janela = JanelaResolverQuestoes(
                configuracao.configuracao,
                self
            )
            janela.exec_nao_modal()
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Treino adaptativo",
                (
                    "Não foi possível iniciar a sessão adaptativa.\n\n"
                    f"{erro}"
                )
            )
            return

        if hasattr(
            self,
            "carregar_questoes"
        ):
            self.carregar_questoes()

        self.atualizar_dashboard()

        if hasattr(self, "invalidar_estatisticas"):
            self.invalidar_estatisticas("questoes")

    def _contexto_ritmo_estudar_agora_v4(self):
        foco = self.cache_analitico.obter(
            "foco:resumo",
            lambda: obter_resumo_foco(),
            ttl=8,
        )
        recentes = self.cache_analitico.obter(
            "foco:recentes:12",
            lambda: listar_sessoes_foco(12),
            ttl=8,
        )
        distribuicao = {
            str(item.get("disciplina") or ""): item
            for item in (foco.get("distribuicao_semana") or [])
        }
        meta_horas = max(0, obter_configuracao_int("meta_foco_semanal_horas", 0))
        dias_alvo = max(0, obter_configuracao_int("meta_dias_estudo_semanal", 0))
        ritmo_diario = 0
        faltam_hoje = 0
        if meta_horas > 0:
            divisor = dias_alvo if dias_alvo > 0 else 5
            ritmo_diario = int(round(meta_horas * 3600 / max(1, divisor)))
            faltam_hoje = max(0, ritmo_diario - int(foco.get("hoje_segundos") or 0))
        return {
            "foco": foco,
            "distribuicao": distribuicao,
            "recentes": recentes,
            "ritmo_diario": ritmo_diario,
            "faltam_hoje": faltam_hoje,
        }

    def _dados_motor_v5(self, pesos=None, proteger=None):
        concurso = obter_concurso_ativo()
        concurso_id = int(concurso[0])
        fila = list(getattr(self, "fila_prioridade", []) or [])
        contexto = self._contexto_ritmo_estudar_agora_v4()
        adaptativas = self.cache_analitico.obter(
            f"adaptativas:{concurso_id}",
            lambda: list(obter_prioridades_sessao_adaptativa(concurso_id) or []),
            ttl=15,
        )
        usar_calibracao = obter_configuracao_bool("calibracao_automatica_foco", True)
        usar_decisoes = obter_configuracao_bool("aprender_decisoes_estudar_agora", True)
        calibracao = self.cache_analitico.obter(
            "inteligencia:calibracao_foco", lambda: obter_calibracao_foco(120), ttl=45
        ) if usar_calibracao else {}
        perfil_decisoes = self.cache_analitico.obter(
            f"inteligencia:decisoes:{concurso_id}",
            lambda: obter_perfil_decisoes_recomendacao(concurso_id, 90), ttl=45
        ) if usar_decisoes else {}
        config = carregar_configuracao_motor_v5()
        return {
            "concurso_id": concurso_id, "fila": fila, "adaptativas": adaptativas,
            "contexto": contexto, "calibracao": calibracao,
            "perfil_decisoes": perfil_decisoes,
            "pesos": pesos if pesos is not None else config["pesos"],
            "proteger": config["proteger_revisoes_vencidas"] if proteger is None else bool(proteger),
            "usar_calibracao": usar_calibracao, "usar_decisoes": usar_decisoes,
        }

    def montar_recomendacao_estudar_agora_v5(self):
        d = self._dados_motor_v5()
        motor = MotorRecomendacaoV5(
            fila=d["fila"], adaptativas=d["adaptativas"], contexto=d["contexto"],
            calibracao=d["calibracao"], perfil_decisoes=d["perfil_decisoes"],
            hoje=QDate.currentDate().toString("yyyy-MM-dd"), pesos=d["pesos"],
            proteger_revisoes_vencidas=d["proteger"],
            usar_calibracao=d["usar_calibracao"],
            usar_historico_decisoes=d["usar_decisoes"],
        )
        return motor.montar()

    def montar_recomendacao_estudar_agora_v4(self):
        return self.montar_recomendacao_estudar_agora_v5()

    def montar_recomendacao_estudar_agora_v3(self):
        return self.montar_recomendacao_estudar_agora_v5()

    def montar_recomendacao_estudar_agora_v2(self):
        return self.montar_recomendacao_estudar_agora_v5()

    def _enriquecer_recomendacao_com_bateria(self, recomendacao):
        """Garante que uma recomendação com tópico use questões quando houver banco interno.

        O Motor V5 continua escolhendo matéria/tópico. Esta camada apenas confirma
        a disponibilidade real no banco e define a quantidade automática da bateria.
        """
        dados = dict(recomendacao or {})
        topico_id = dados.get("topico_id")
        if topico_id in (None, ""):
            dados["tem_bateria_automatica"] = False
            return dados

        try:
            topico_id = int(topico_id)
        except Exception:
            dados["tem_bateria_automatica"] = False
            return dados

        try:
            concurso_id = obter_concurso_ativo()[0]
            disponiveis = listar_questoes_resolucao(
                concurso_id,
                topico_id=topico_id,
                somente_ineditas=False,
                aleatorio=False,
            )
        except Exception:
            disponiveis = []

        total_disponivel = len(disponiveis)
        dados["questoes_disponiveis_reais"] = total_disponivel
        dados["tem_bateria_automatica"] = total_disponivel > 0

        if total_disponivel <= 0:
            return dados

        try:
            alvo_atual = max(0, int(dados.get("questoes_alvo") or 0))
        except Exception:
            alvo_atual = 0

        if alvo_atual <= 0:
            try:
                score = float(dados.get("score_total") or 0.0)
            except Exception:
                score = 0.0
            try:
                minutos = int(dados.get("minutos") or 25)
            except Exception:
                minutos = 25

            if score >= 78 or minutos >= 40:
                alvo_atual = 20
            elif score >= 58 or minutos >= 30:
                alvo_atual = 15
            else:
                alvo_atual = 10

        alvo = max(1, min(alvo_atual, total_disponivel))
        dados["questoes_alvo"] = alvo
        dados["atividade"] = "Questões"
        dados["descricao_sessao"] = "Bateria inteligente de questões"
        dados["rotulo_sessao"] = "bateria inteligente recomendada"
        return dados

    def abrir_estudar_agora_v5(self):
        if getattr(self, "sessao_ativa", False) and getattr(self, "sessao_pausada", False):
            self.abrir_sessao_estudo()
            return

        # O Foco registra tempo de forma independente. Uma sessão ativa não
        # pode impedir recomendações, questões, revisões ou outras atividades.
        foco_ativo = False
        janela_foco = getattr(self, "_janela_modo_foco", None)
        if janela_foco is not None:
            try:
                foco_ativo = bool(
                    getattr(
                        janela_foco,
                        "sessao_ativa",
                        False
                    )
                )
            except RuntimeError:
                self._janela_modo_foco = None

        self.cache_analitico.invalidar()
        self.atualizar_dashboard()
        try:
            recomendacao = self.montar_recomendacao_estudar_agora_v5()
            recomendacao = self._enriquecer_recomendacao_com_bateria(recomendacao)
        except Exception as erro:
            QMessageBox.critical(self, "Recomendado para hoje", f"Não foi possível montar a recomendação.\n\n{erro}")
            return
        registro_id = None
        if obter_configuracao_bool("aprender_decisoes_estudar_agora", True):
            try:
                registro_id = registrar_recomendacao_estudo(obter_concurso_ativo()[0], recomendacao)
            except Exception:
                registro_id = None
        janela = JanelaEstudarAgoraV5(recomendacao, self)
        if foco_ativo:
            janela.opcao_modo_foco.setChecked(True)
            janela.opcao_modo_foco.setEnabled(False)
            janela.opcao_modo_foco.setText(
                "Modo Foco já está ativo — o cronômetro continuará independente"
            )
            janela.opcao_modo_foco.setToolTip(
                "A atividade será aberta normalmente sem reiniciar ou interromper o Modo Foco atual."
            )

        if janela.exec() != QDialog.Accepted:
            if registro_id is not None:
                try: atualizar_decisao_recomendacao(registro_id, "ignorada")
                except Exception: pass
            return

        minutos_escolhidos = int(recomendacao.get("minutos") or 0) or None
        if janela.preparacao:
            minutos_escolhidos = janela.preparacao.get("minutos") or minutos_escolhidos

        if registro_id is not None:
            try:
                atualizar_decisao_recomendacao(
                    registro_id,
                    "aceita",
                    minutos_escolhidos,
                )
            except Exception:
                pass

        self.cache_analitico.invalidar("inteligencia:decisoes")

        # Observacao significativa: o usuario confirmou a acao. Qualquer
        # falha de telemetria e absorvida pela camada segura e nunca impede a
        # recomendacao V3/V5 nem altera a ordem apresentada.
        registrar_observacao_fila_sombra_segura(
            "study_now_explicit",
            concurso_id=obter_concurso_ativo()[0],
        )

        if (
            janela.usar_modo_foco
            and janela.preparacao
            and not foco_ativo
        ):
            self.abrir_modo_foco(janela.preparacao)
            return

        # Com um Foco já ativo, a recomendação é executada diretamente. O
        # cronômetro segue em sua janela, sem receber ou impor contexto.
        resultado = self.executar_recomendacao_estudar_agora_v5(recomendacao)
        self._processar_fluxo_pos_bateria_algoritmo(resultado)

    def _processar_fluxo_pos_bateria_algoritmo(self, resultado):
        """Mantém o usuário no fluxo guiado após uma bateria do Motor V5."""
        atual = resultado

        while isinstance(atual, dict):
            acao = str(atual.get("proxima_acao") or "").strip().lower()

            if acao == "banco_questoes":
                self.abrir_questoes()
                return

            if acao != "continuar_algoritmo":
                return

            try:
                self.cache_analitico.invalidar()
                self.atualizar_dashboard()
                proxima = self.montar_recomendacao_estudar_agora_v5()
                proxima = self._enriquecer_recomendacao_com_bateria(proxima)
            except Exception as erro:
                QMessageBox.critical(
                    self,
                    "Próxima recomendação",
                    f"Não foi possível recalcular a próxima recomendação.\n\n{erro}",
                )
                return

            if not proxima:
                QMessageBox.information(
                    self,
                    "Próxima recomendação",
                    "Não há uma nova prioridade disponível neste momento.",
                )
                return

            registro_id = None
            if obter_configuracao_bool("aprender_decisoes_estudar_agora", True):
                try:
                    registro_id = registrar_recomendacao_estudo(
                        obter_concurso_ativo()[0],
                        proxima,
                    )
                except Exception:
                    registro_id = None

            confirmacao = JanelaProximaRecomendacaoAlgoritmo(proxima, self)
            if confirmacao.exec() != QDialog.Accepted:
                if registro_id is not None:
                    try:
                        atualizar_decisao_recomendacao(registro_id, "ignorada")
                    except Exception:
                        pass
                return

            if registro_id is not None:
                try:
                    atualizar_decisao_recomendacao(
                        registro_id,
                        "aceita",
                        int(proxima.get("minutos") or 0) or None,
                    )
                except Exception:
                    pass

            registrar_observacao_fila_sombra_segura(
                "study_now_explicit",
                concurso_id=obter_concurso_ativo()[0],
            )

            atual = self.executar_recomendacao_estudar_agora_v5(proxima)

    def executar_recomendacao_estudar_agora_v5(self, recomendacao):
        """Executa exatamente a recomendação já escolhida pelo Motor V5.

        Se o tópico recomendado possuir qualquer questão interna, o botão
        Começar abre automaticamente uma bateria inteligente daquele tópico.
        Revisão manual é usada somente quando não existe questão disponível.
        """
        dados = self._enriquecer_recomendacao_com_bateria(recomendacao)
        origem = str(dados.get("origem") or "").strip().lower()
        topico_id = dados.get("topico_id")
        topico = str(dados.get("topico") or "").strip()

        try:
            questoes_alvo = max(0, int(dados.get("questoes_alvo") or 0))
        except Exception:
            questoes_alvo = 0

        tem_bateria = bool(dados.get("tem_bateria_automatica"))

        if topico_id not in (None, "") and topico and tem_bateria:
            modo = (
                "Revisão inteligente • Motor V5"
                if origem == "revisao"
                else "Treino inteligente • Motor V5"
            )
            resultado = abrir_resolvedor_topico(
                int(topico_id),
                topico,
                self,
                quantidade_padrao=max(1, questoes_alvo),
                quantidade_exata=max(1, questoes_alvo),
                modo_nome=modo,
                origem_sessao="algoritmo_v5",
            )
            if resultado is not None:
                self.cache_analitico.invalidar()
                self.atualizar_dashboard()
            return resultado

        # Sem questões internas: preserva o caminho manual apenas como fallback.
        if origem == "revisao" and topico_id not in (None, "") and topico:
            QMessageBox.information(
                self,
                "Sem questões internas",
                (
                    "O Vighna recomendou este tópico, mas ele ainda não possui "
                    "questões disponíveis no banco interno.\n\n"
                    "A revisão manual será aberta como alternativa."
                ),
            )
            janela_revisao = JanelaRevisao(
                int(topico_id),
                topico,
                self,
            )
            resultado_dialogo = janela_revisao.exec()
            if resultado_dialogo == QDialog.Accepted:
                self.cache_analitico.invalidar()
                self.atualizar_dashboard()
            return resultado_dialogo

        if topico_id not in (None, "") and topico:
            QMessageBox.information(
                self,
                "Sem questões internas",
                (
                    "O tópico recomendado ainda não possui questões internas "
                    "disponíveis para iniciar uma bateria automática."
                ),
            )
            return None

        QMessageBox.information(
            self,
            "Recomendação do Vighna",
            (
                "A recomendação atual é uma sessão livre e não possui um "
                "tópico específico para iniciar automaticamente."
            ),
        )
        return None


    def explicar_recomendacao_dashboard(self):
        """Abre a explicação factual da prioridade atual sem iniciar estudo."""
        if getattr(self, "sessao_ativa", False) and getattr(self, "sessao_pausada", False):
            QMessageBox.information(
                self,
                "Por que esta recomendação?",
                (
                    "Existe uma sessão de estudo pausada.\n\n"
                    "O Vighna prioriza a continuidade dessa sessão porque ela já foi iniciada "
                    "e mantém o contexto da atividade em andamento."
                ),
            )
            return

        try:
            self.cache_analitico.invalidar()
            recomendacao = self.montar_recomendacao_estudar_agora_v5()
            recomendacao = self._enriquecer_recomendacao_com_bateria(recomendacao)
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Por que esta recomendação?",
                f"Não foi possível recalcular a recomendação.\n\n{erro}",
            )
            return

        if not recomendacao:
            QMessageBox.information(
                self,
                "Por que esta recomendação?",
                "Não há prioridade suficiente para explicar neste momento.",
            )
            return

        JanelaExplicacaoRecomendacao(recomendacao, self).exec()

    def abrir_estudar_agora_v4(self):
        return self.abrir_estudar_agora_v5()

    def abrir_estudar_agora_v3(self):
        return self.abrir_estudar_agora_v5()

    def abrir_estudar_agora_v2(self):
        return self.abrir_estudar_agora_v5()

    def abrir_revisao_inteligente_dashboard(self):
        self.atualizar_dashboard()

        fila = getattr(
            self,
            "fila_prioridade",
            []
        )

        if not fila:
            QMessageBox.information(
                self,
                "Revisões em dia",
                (
                    "Não há revisões vencidas ou previstas "
                    "para hoje."
                )
            )
            return

        linha = self.tabela_pendentes.currentRow()

        topico_id = None
        nome_topico = None

        if linha >= 0:
            item = self.tabela_pendentes.item(
                linha,
                1
            )

            if item is not None:
                topico_id = item.data(
                    Qt.UserRole
                )
                nome_topico = item.text()

        if topico_id is None:
            prioridade = fila[0]
            topico_id = prioridade[
                "topico_id"
            ]
            nome_topico = prioridade[
                "topico"
            ]

        resultado = abrir_resolvedor_topico(
            topico_id,
            nome_topico,
            self,
            modo_nome="Revisão inteligente",
        )

        if resultado is not None:
            self.atualizar_dashboard()

    def iniciar_modo_revisao(self):
        """
        Abre a revisão mais prioritária.
        Depois de salvar, oferece imediatamente a próxima da fila.
        """

        self.atualizar_dashboard()

        if not getattr(
            self,
            "fila_prioridade",
            []
        ):
            QMessageBox.information(
                self,
                "Revisões em dia",
                (
                    "Não há revisões vencidas ou previstas "
                    "para hoje."
                )
            )
            return

        while self.fila_prioridade:
            item_fila = self.fila_prioridade[0]

            confirmacao = QMessageBox.question(
                self,
                "Próxima revisão",
                (
                    f"{item_fila['disciplina']}\n\n"
                    f"{item_fila['topico']}\n\n"
                    f"Prioridade: {item_fila['nivel']}\n"
                    f"Importância: {item_fila['importancia']}/5\n"
                    f"Score: {item_fila['score']:.1f}\n"
                    f"Motivo: {item_fila['motivo']}\n\n"
                    "Iniciar esta revisão agora?"
                ),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes
            )

            if confirmacao != QMessageBox.Yes:
                return

            resultado = abrir_resolvedor_topico(
                item_fila[
                    "topico_id"
                ],
                item_fila[
                    "topico"
                ],
                self
            )

            if resultado is None:
                return

            # Após salvar, o tópico tende a sair da fila porque
            # recebeu uma nova data de revisão.
            self.atualizar_dashboard()

            if not self.fila_prioridade:
                QMessageBox.information(
                    self,
                    "Fila concluída",
                    (
                        "Você concluiu todas as revisões "
                        "pendentes para hoje."
                    )
                )
                return

            proxima = self.fila_prioridade[0]

            continuar = QMessageBox.question(
                self,
                "Revisão salva",
                (
                    "Revisão registrada com sucesso.\n\n"
                    "Próxima prioridade:\n"
                    f"{proxima['disciplina']} — "
                    f"{proxima['topico']}\n\n"
                    f"Prioridade: {proxima['nivel']}\n"
                    f"Motivo: {proxima['motivo']}\n\n"
                    "Deseja continuar para a próxima?"
                ),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes
            )

            if continuar != QMessageBox.Yes:
                return

    def abrir_topico_pendente(
        self,
        linha,
        coluna
    ):
        item = self.tabela_pendentes.item(
            linha,
            1
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )

        nome_topico = item.text()

        janela = JanelaTopico(
            topico_id,
            nome_topico,
            self
        )

        janela.exec()

        self.atualizar_dashboard()

