    def normalizar_texto_questoes(
        self,
        texto
    ):
        texto = str(
            texto
            or ""
        ).lower().strip()

        texto = unicodedata.normalize(
            "NFD",
            texto
        )

        texto = "".join(
            caractere
            for caractere in texto
            if unicodedata.category(
                caractere
            ) != "Mn"
        )

        return " ".join(
            texto.split()
        )

    def selecionar_sessao_rapida_dashboard(self, minutos):
        """Seleciona a duração usada pelo atalho de Sessão rápida."""
        try:
            minutos = int(minutos)
        except (TypeError, ValueError):
            minutos = 10

        if minutos not in (5, 10, 15):
            minutos = 10

        self.dashboard_quick_focus_minutes = minutos

        botoes = getattr(
            self,
            "dashboard_quick_focus_buttons",
            {},
        )
        for valor, botao in botoes.items():
            botao.setChecked(int(valor) == minutos)

        hint = getattr(
            self,
            "dashboard_quick_focus_hint",
            None,
        )
        if hint is not None:
            hint.setText(
                f"{minutos} min selecionados • início imediato"
            )

    def iniciar_sessao_rapida_dashboard(self):
        """Inicia uma sessão curta sem alterar o planejamento do usuário."""
        minutos = getattr(
            self,
            "dashboard_quick_focus_minutes",
            10,
        )
        try:
            minutos = int(minutos)
        except (TypeError, ValueError):
            minutos = 10

        if minutos not in (5, 10, 15):
            minutos = 10

        janela_existente = getattr(
            self,
            "_janela_modo_foco",
            None,
        )
        if janela_existente is not None:
            try:
                if bool(getattr(janela_existente, "sessao_ativa", False)):
                    self.abrir_ou_trazer_modo_foco()
                    return
            except RuntimeError:
                self._janela_modo_foco = None

        # Preparar apenas a duração mantém a sessão realmente rápida: sem
        # disciplina/tópico obrigatório e sem interferir no plano do dia.
        self.abrir_modo_foco({"minutos": minutos})

        janela = getattr(
            self,
            "_janela_modo_foco",
            None,
        )
        if janela is None:
            return

        try:
            if not bool(getattr(janela, "sessao_ativa", False)):
                janela.iniciar()
        except RuntimeError:
            self._janela_modo_foco = None

    def registrar_janela_resolvedor_questoes(self, janela):
        """Registra a bateria top-level para restauração pelo Dashboard."""
        if janela is None:
            return
        self._janela_resolvedor_questoes = janela
        try:
            janela.finished.connect(
                lambda _resultado=0, referencia=janela: self._resolvedor_questoes_finalizado(referencia)
            )
        except (RuntimeError, TypeError):
            pass
        self._atualizar_atalho_visual_resolvedor()

    def _resolvedor_questoes_finalizado(self, janela):
        if getattr(self, "_janela_resolvedor_questoes", None) is janela:
            self._janela_resolvedor_questoes = None
        botao = getattr(self, "botao_retomar_questoes_topo", None)
        if botao is not None:
            botao.setVisible(False)
        # ``finished`` pode ser emitido durante o fechamento do QDialog. A
        # varredura no próximo ciclo evita reencontrar a própria janela antes
        # de o Windows/Qt atualizar sua visibilidade.
        QTimer.singleShot(0, self._atualizar_atalho_visual_resolvedor)

    def _atualizar_atalho_visual_resolvedor(self):
        existe_sessao = self.obter_janela_resolvedor_questoes() is not None
        botao = getattr(self, "botao_retomar_questoes_topo", None)
        if botao is not None:
            botao.setVisible(existe_sessao)
        self._atualizar_retomada_no_portal_treinos()

    def obter_janela_resolvedor_questoes(self):
        janela = getattr(self, "_janela_resolvedor_questoes", None)
        if janela is not None:
            try:
                janela.windowState()
                return janela
            except RuntimeError:
                self._janela_resolvedor_questoes = None

        # Recuperação defensiva: se a referência foi perdida, procura uma
        # bateria top-level ainda viva na aplicação.
        app = QApplication.instance()
        if app is not None:
            for candidata in app.topLevelWidgets():
                if isinstance(candidata, JanelaResolverQuestoes):
                    try:
                        if candidata.isVisible() or candidata.isMinimized():
                            self._janela_resolvedor_questoes = candidata
                            return candidata
                    except RuntimeError:
                        continue
        return None

    def abrir_ou_trazer_resolvedor_questoes(self):
        janela = self.obter_janela_resolvedor_questoes()
        if janela is None:
            self._atualizar_atalho_visual_resolvedor()
            return None
        if janela.isMinimized():
            janela.showNormal()
        elif not janela.isVisible():
            janela.show()
        janela.raise_()
        janela.activateWindow()
        self._atualizar_atalho_visual_resolvedor()
        return janela

    def obter_janela_modo_foco(self, apenas_ativa=False):
        janela = getattr(self, "_janela_modo_foco", None)
        if janela is None:
            return None
        try:
            if apenas_ativa and not bool(janela.sessao_ativa):
                return None
            janela.isVisible()
            return janela
        except RuntimeError:
            self._janela_modo_foco = None
            return None

    def abrir_ou_trazer_modo_foco(self, preparacao=None):
        from foco import JanelaModoFoco, trazer_janela_foco_para_frente

        # Esta é a única fábrica da janela. A referência central impede uma
        # segunda instância e o helper cuida de ocultação/minimização/ativação.
        janela = self.obter_janela_modo_foco()
        if janela is not None:
            if preparacao:
                janela.preparar_sessao(**preparacao)
            trazer_janela_foco_para_frente(janela)
            return janela

        # Sem parent Qt: janela top-level independente, inclusive na barra de
        # tarefas do Windows. Os sinais mantêm o vínculo funcional com o app.
        janela = JanelaModoFoco()
        self._janela_modo_foco = janela
        janela.resumo_alterado.connect(lambda: self.notificar_dados_alterados("foco"))
        janela.estado_alterado.connect(self.estado_foco_alterado.emit)
        janela.acao_pos_foco.connect(self.tratar_acao_pos_foco)
        janela.solicitar_questoes.connect(self.iniciar_questoes_contextuais_foco)
        janela.sessao_finalizada.connect(self.tratar_sessao_finalizada_jornada)
        janela.destroyed.connect(self._modo_foco_destruido)
        if preparacao:
            janela.preparar_sessao(**preparacao)
        trazer_janela_foco_para_frente(janela)
        self.estado_foco_alterado.emit()
        return janela

    def abrir_modo_foco(self, preparacao=None):
        """Alias compatível para o ponto canônico de abertura/restauração."""
        return self.abrir_ou_trazer_modo_foco(preparacao)

    def alternar_pausa_modo_foco(self):
        janela = self.obter_janela_modo_foco(apenas_ativa=True)
        if janela is None:
            return False
        janela.alternar_pausa()
        return True

    def iniciar_questoes_contextuais_foco(self, contexto):
        contexto = dict(contexto or {})
        topico_id = contexto.get("topico_id")
        topico = str(contexto.get("topico") or "").strip()
        quantidade = max(1, int(contexto.get("quantidade") or 10))
        atividade = str(contexto.get("atividade") or "Questões").strip()

        if topico_id in (None, "") or not topico:
            return

        # O cronômetro continua na janela do Foco enquanto o resolvedor é usado.
        self.showNormal()
        self.raise_()
        self.activateWindow()

        try:
            resultado = abrir_resolvedor_topico(
                int(topico_id),
                topico,
                parent=self,
                quantidade_padrao=quantidade,
                quantidade_exata=quantidade,
                modo_nome=f"Foco • {atividade}",
                origem_sessao=contexto.get("origem_sessao"),
            )
        except Exception as erro:
            QMessageBox.warning(
                self,
                "Questões do Modo Foco",
                f"Não foi possível abrir a bateria vinculada.\n\n{erro}",
            )
            resultado = None

        janela_foco = getattr(self, "_janela_modo_foco", None)
        if resultado and janela_foco is not None:
            try:
                janela_foco.registrar_resultado_questoes(resultado)
                self.abrir_ou_trazer_modo_foco()
            except RuntimeError:
                self._janela_modo_foco = None

        if hasattr(self, "carregar_questoes"):
            self.carregar_questoes()
        self.notificar_dados_alterados("questoes")

    def _modo_foco_destruido(self, *args):
        self._janela_modo_foco = None
        self.estado_foco_alterado.emit()
        self.notificar_dados_alterados("foco")

    def tratar_acao_pos_foco(self, acao, dados):
        """Encaminha o próximo passo escolhido no resumo Pós-Foco."""
        dados = dict(dados or {})
        acao = str(acao or "").strip().lower()

        # Traz a janela principal para frente; o Modo Foco permanece disponível
        # e pode ser reaberto depois pelo botão correspondente.
        try:
            janela_foco = getattr(self, "_janela_modo_foco", None)
            if janela_foco is not None:
                janela_foco.hide()
        except RuntimeError:
            self._janela_modo_foco = None

        self.showNormal()
        self.raise_()
        self.activateWindow()

        if acao == "jornada_proxima":
            QTimer.singleShot(0, self.iniciar_proxima_jornada)
            return

        if acao == "jornada_recalcular":
            self.recalcular_jornada_do_dia()
            QTimer.singleShot(0, self.abrir_jornada_do_dia)
            return

        if acao == "jornada_pausar":
            jornada = self.alternar_pausa_jornada()
            if jornada:
                QMessageBox.information(
                    self,
                    "Jornada pausada",
                    "A Jornada foi pausada. O que já foi estudado permanece registrado e você pode retomá-la pelo Dashboard.",
                )
            return

        if acao == "jornada_encerrar":
            self.encerrar_jornada_do_dia()
            try:
                janela_foco = getattr(self, "_janela_modo_foco", None)
                if janela_foco is not None:
                    janela_foco.close()
            except RuntimeError:
                self._janela_modo_foco = None
            return

        if acao == "recomendar":
            QTimer.singleShot(0, self.abrir_estudar_agora_v4)
            return

        if acao == "questoes":
            topico_id = dados.get("topico_id")
            topico = str(dados.get("topico") or "").strip()
            if topico_id not in (None, "") and topico:
                try:
                    resultado = abrir_resolvedor_topico(
                        int(topico_id),
                        topico,
                        parent=self,
                        quantidade_padrao=max(10, int(dados.get("meta_questoes") or 10)),
                        modo_nome="Pós-Foco • continuar questões",
                    )
                    if resultado:
                        self.notificar_dados_alterados("questoes")
                    return
                except Exception:
                    pass

            # Fallback para sessões livres ou sem tópico: abre o Banco já filtrado.
            self.abrir_questoes()
            disciplina = str(dados.get("disciplina") or "").strip()
            if disciplina and hasattr(self, "questoes_filtro_disciplina"):
                indice = self.questoes_filtro_disciplina.findText(disciplina, Qt.MatchFixedString)
                if indice >= 0:
                    self.questoes_filtro_disciplina.setCurrentIndex(indice)
            if topico and hasattr(self, "questoes_filtro_topico"):
                indice = self.questoes_filtro_topico.findText(topico, Qt.MatchFixedString)
                if indice >= 0:
                    self.questoes_filtro_topico.setCurrentIndex(indice)
            if hasattr(self, "filtrar_questoes"):
                self.filtrar_questoes()
            return

        if acao == "revisao":
            topico_id = dados.get("topico_id")
            topico = str(dados.get("topico") or "").strip()
            if topico_id in (None, "") or not topico:
                QMessageBox.information(
                    self,
                    "Registrar revisão",
                    "A sessão precisa estar vinculada a um tópico para registrar uma revisão.",
                )
                return

            janela = JanelaRevisao(int(topico_id), topico, self)
            efetiva = max(0, int(dados.get("duracao_efetiva") or 0))
            minutos = max(1, int(round(efetiva / 60.0))) if efetiva else 0
            atividade = str(dados.get("tipo_atividade") or "Estudo").strip()
            try:
                if minutos:
                    janela.observacao.setPlainText(
                        f"Modo Foco: {atividade} • {minutos} min de foco efetivo."
                    )
            except Exception:
                pass

            if janela.exec() == QDialog.Accepted:
                self.notificar_dados_alterados("revisoes")
            return

    def abrir_pausa_desafios(self):
        from jogos import JanelaPausaDesafios
        janela = JanelaPausaDesafios(self)
        # Diagnóstico opcional, apenas leitura: Ctrl+Shift+F11 dentro da janela.
        # Não modifica o módulo de jogos, as geometrias, nem o banco de dados.
        try:
            from ui.pausa_geometry_runtime import attach_pause_geometry_shortcut
            attach_pause_geometry_shortcut(janela)
        except (ImportError, RuntimeError, AttributeError):
            pass  # A tela permanece funcional mesmo se o diagnóstico estiver indisponível.
        janela.exec()

    def abrir_questoes_topico_contextual(self, topico_id):
        """Abre a Central de Questões já filtrada no tópico informado.

        O filtro é aplicado somente depois que a carga lazy da Central termina,
        evitando o comportamento anterior em que o clique parecia não fazer
        nada ou o filtro era perdido durante a reconstrução dos combos.
        """
        try:
            topico_id = int(topico_id)
        except (TypeError, ValueError):
            QMessageBox.warning(
                self,
                "Ver questões",
                "O tópico selecionado não possui uma identificação válida."
            )
            return

        contexto = obter_contexto_topico(topico_id)
        if not contexto:
            QMessageBox.warning(
                self,
                "Ver questões",
                "O tópico selecionado não foi encontrado no banco de dados."
            )
            return

        self._central_questoes_contexto_pendente = {
            "topico_id": topico_id,
            "disciplina": str(contexto.get("disciplina_nome") or "").strip(),
            "topico": str(contexto.get("topico_nome") or "").strip(),
        }

        # Força uma leitura atual do banco para que questões recém-importadas
        # também estejam presentes quando o filtro contextual for aplicado.
        self._central_questoes_suja = True
        self.abrir_questoes()
        QTimer.singleShot(30, self._aplicar_contexto_pendente_central_questoes)

    def _aplicar_contexto_pendente_central_questoes(self):
        contexto = getattr(self, "_central_questoes_contexto_pendente", None)
        if not contexto:
            return

        if (
            not hasattr(self, "telas")
            or not hasattr(self, "tela_questoes")
            or self.telas.currentWidget() is not self.tela_questoes
        ):
            return

        # Se a carga lazy ainda estiver em andamento, aguarda o próximo ciclo.
        if getattr(self, "_central_questoes_refresh_agendado", False):
            QTimer.singleShot(35, self._aplicar_contexto_pendente_central_questoes)
            return

        disciplina = str(contexto.get("disciplina") or "").strip()
        topico = str(contexto.get("topico") or "").strip()

        if not (
            hasattr(self, "questoes_filtro_disciplina")
            and hasattr(self, "questoes_filtro_topico")
        ):
            return

        indice_disciplina = self.questoes_filtro_disciplina.findText(
            disciplina,
            Qt.MatchFixedString,
        )
        if indice_disciplina < 0:
            self._central_questoes_contexto_pendente = None
            QMessageBox.warning(
                self,
                "Ver questões",
                "A disciplina do tópico não pôde ser localizada na Central de Questões."
            )
            return

        self.questoes_filtro_disciplina.setCurrentIndex(indice_disciplina)
        self.atualizar_filtro_topicos_questoes()

        indice_topico = self.questoes_filtro_topico.findText(
            topico,
            Qt.MatchFixedString,
        )
        if indice_topico < 0:
            # Tópicos ainda sem questões não aparecem naturalmente no combo,
            # mas precisam poder ser abertos para receber a primeira questão.
            self.questoes_filtro_topico.addItem(topico)
            indice_topico = self.questoes_filtro_topico.findText(
                topico,
                Qt.MatchFixedString,
            )

        if indice_topico < 0:
            self._central_questoes_contexto_pendente = None
            QMessageBox.warning(
                self,
                "Ver questões",
                "O tópico não pôde ser aplicado como filtro na Central de Questões."
            )
            return

        self.questoes_filtro_topico.setCurrentIndex(indice_topico)

        if hasattr(self, "questoes_filtro_capitulo"):
            indice_todos = self.questoes_filtro_capitulo.findData(None)
            if indice_todos >= 0:
                self.questoes_filtro_capitulo.setCurrentIndex(indice_todos)

        self.filtrar_questoes()
        self._central_questoes_contexto_ativo = dict(contexto)
        self._central_questoes_contexto_pendente = None

    def _obter_topico_id_contexto_central_questoes(self):
        """Retorna o tópico específico atualmente selecionado na Central."""
        if not (
            hasattr(self, "questoes_filtro_disciplina")
            and hasattr(self, "questoes_filtro_topico")
        ):
            return None

        disciplina = str(self.questoes_filtro_disciplina.currentText() or "").strip()
        topico = str(self.questoes_filtro_topico.currentText() or "").strip()
        if (
            not disciplina
            or disciplina == "Todas disciplinas"
            or not topico
            or topico == "Todos tópicos"
        ):
            return None

        for item in getattr(self, "dados_questoes", []):
            if (
                str(item.get("disciplina") or "") == disciplina
                and str(item.get("topico") or "") == topico
                and item.get("topico_id") is not None
            ):
                return int(item.get("topico_id"))

        contexto = getattr(self, "_central_questoes_contexto_ativo", None) or {}
        if (
            str(contexto.get("disciplina") or "") == disciplina
            and str(contexto.get("topico") or "") == topico
            and contexto.get("topico_id") is not None
        ):
            return int(contexto.get("topico_id"))
        return None

    def abrir_questoes(self):
        self._garantir_tela_questoes()
        # Navegação primeiro; consultas e montagem da grade ficam para o
        # próximo ciclo do event loop. Assim o clique responde imediatamente.
        refiltrar = False

        # A Central deve abrir sempre com o banco completo em destaque. O
        # botão "Para análise" continua disponível como filtro opcional, mas
        # não pode manter a grade presa à fila usada em uma visita anterior.
        if hasattr(self, "questoes_para_analise"):
            refiltrar = refiltrar or self.questoes_para_analise.isChecked()
            self.questoes_para_analise.blockSignals(True)
            self.questoes_para_analise.setChecked(False)
            self.questoes_para_analise.blockSignals(False)

        if hasattr(self, "questoes_somente_duplicadas"):
            refiltrar = refiltrar or self.questoes_somente_duplicadas.isChecked()
            self.questoes_somente_duplicadas.blockSignals(True)
            self.questoes_somente_duplicadas.setChecked(False)
            self.questoes_somente_duplicadas.blockSignals(False)

        self.telas.setCurrentWidget(self.tela_questoes)
        self._agendar_carregamento_central_questoes(refiltrar=refiltrar)

    def carregar_questoes(self):
        concurso = obter_concurso_ativo()
        concurso_id = concurso[0]

        self.questoes_perfil.setText(
            f"Perfil: {concurso[1]}"
        )

        incluir_arquivadas = (
            hasattr(
                self,
                "questoes_mostrar_arquivadas"
            )
            and self.questoes_mostrar_arquivadas.isChecked()
        )

        # Uma única leitura do catálogo alimenta tanto a grade quanto os
        # contadores administrativos. Antes eram feitas duas consultas quase
        # idênticas a cada abertura da Central.
        todas_questoes_administrativas = listar_questoes(
            concurso_id,
            incluir_inativas=True,
            incluir_topicos_pausados=True,
            incluir_disciplinas_pausadas=True,
        )
        if incluir_arquivadas:
            self.dados_questoes = list(todas_questoes_administrativas)
        else:
            self.dados_questoes = [
                item for item in todas_questoes_administrativas
                if item.get("ativa", True)
            ]

        self.questoes_grupos_duplicadas = listar_grupos_questoes_duplicadas(
            concurso_id
        )
        self.questoes_ids_duplicadas = {
            int(questao_id)
            for grupo in self.questoes_grupos_duplicadas
            for questao_id in grupo.get("ids", [])
        }
        if hasattr(self, "questoes_somente_duplicadas"):
            quantidade_duplicadas = len(self.questoes_ids_duplicadas)
            quantidade_grupos = len(self.questoes_grupos_duplicadas)
            self.questoes_somente_duplicadas.setText(
                f"Somente duplicadas · {quantidade_duplicadas}"
            )
            self.questoes_somente_duplicadas.setToolTip(
                (
                    f"{quantidade_duplicadas} questão(ões) em {quantidade_grupos} grupo(s) de duplicidade. "
                    "A detecção compara enunciado, alternativas e gabarito."
                )
            )
            self.questoes_somente_duplicadas.setEnabled(quantidade_duplicadas > 0)
            if quantidade_duplicadas <= 0 and self.questoes_somente_duplicadas.isChecked():
                self.questoes_somente_duplicadas.blockSignals(True)
                self.questoes_somente_duplicadas.setChecked(False)
                self.questoes_somente_duplicadas.blockSignals(False)
        total_ativas = sum(
            1 for item in todas_questoes_administrativas
            if item.get("ativa", True)
        )
        total_desativadas = sum(
            1 for item in todas_questoes_administrativas
            if not item.get("ativa", True)
        )
        total_para_analise = sum(
            1
            for item in todas_questoes_administrativas
            if item.get(
                "analise_pendente",
                False
            )
        )
        estatisticas = {
            "total": total_ativas,
            "disciplinas": len({
                item.get("disciplina")
                for item in todas_questoes_administrativas
                if item.get("disciplina")
            }),
            "topicos": len({
                item.get("topico_id")
                for item in todas_questoes_administrativas
                if item.get("topico_id") is not None
            }),
            "com_explicacao": sum(
                1 for item in todas_questoes_administrativas
                if item.get("tem_explicacao")
            ),
        }

        self.questoes_total.setText(
            str(
                estatisticas[
                    "total"
                ]
            )
        )
        if hasattr(self, "questoes_desativadas_total"):
            self.questoes_desativadas_total.setText(str(total_desativadas))
        if hasattr(
            self,
            "questoes_para_analise"
        ):
            self.questoes_para_analise.setText(
                f"Para análise · {total_para_analise}"
            )
            if total_para_analise <= 0:
                self.questoes_para_analise.blockSignals(
                    True
                )
                self.questoes_para_analise.setChecked(
                    False
                )
                self.questoes_para_analise.blockSignals(
                    False
                )
            self.questoes_para_analise.setEnabled(
                total_para_analise > 0
            )
        self.questoes_topicos.setText(
            str(
                estatisticas[
                    "topicos"
                ]
            )
        )
        self.questoes_disciplinas.setText(
            str(
                estatisticas[
                    "disciplinas"
                ]
            )
        )
        self.questoes_explicadas.setText(
            str(
                estatisticas[
                    "com_explicacao"
                ]
            )
        )

        if hasattr(
            self,
            "questoes_historico_resumo"
        ):
            estatisticas_historico = (
                obter_estatisticas_historico_questoes(
                    concurso_id
                )
            )

            if estatisticas_historico[
                "respondidas"
            ] <= 0:
                self.questoes_historico_resumo.setText(
                    "Nenhuma resposta registrada"
                )
            else:
                desempenho = (
                    estatisticas_historico[
                        "desempenho"
                    ]
                )

                partes = [
                    (
                        f"{estatisticas_historico['respondidas']} "
                        "respondida(s)"
                    ),
                    (
                        f"{estatisticas_historico['erros']} erro(s)"
                    ),
                ]

                if desempenho is not None:
                    partes.append(
                        f"{desempenho:.0f}%"
                    )

                if estatisticas_historico[
                    "criticas"
                ] > 0:
                    partes.append(
                        (
                            f"{estatisticas_historico['criticas']} "
                            "crítica(s)"
                        )
                    )

                self.questoes_historico_resumo.setText(
                    " • ".join(
                        partes
                    )
                )

        if hasattr(
            self,
            "questoes_integridade_resumo"
        ):
            integridade_historica = (
                obter_resumo_integridade_historica_questoes(
                    concurso_id
                )
            )

            estado_integridade = integridade_historica[
                "estado"
            ]

            self.questoes_integridade_resumo.setProperty(
                "integrityState",
                estado_integridade
            )

            if estado_integridade == "empty":
                texto_integridade = "Integridade: sem histórico"
            elif estado_integridade == "warning":
                texto_integridade = (
                    "Integridade: atenção"
                )
            elif estado_integridade == "legacy":
                texto_integridade = (
                    "Integridade: protegida*"
                )
            else:
                texto_integridade = (
                    "Integridade: protegida"
                )

            self.questoes_integridade_resumo.setText(
                texto_integridade
            )

            self.questoes_integridade_resumo.setToolTip(
                (
                    f"Tentativas: {integridade_historica['total_tentativas']}\n"
                    f"Snapshots originais: {integridade_historica['snapshots_originais']}\n"
                    f"Snapshots legados migrados: {integridade_historica['snapshots_migrados']}\n"
                    f"Sem snapshot: {integridade_historica['sem_snapshot']}\n"
                    f"Cobertura histórica: {integridade_historica['cobertura_percentual']:.1f}%\n"
                    f"Questões desativadas com histórico: "
                    f"{integridade_historica['questoes_arquivadas_com_historico']}\n\n"
                    "Snapshot original = conteúdo congelado no momento da resposta.\n"
                    "Snapshot legado = conteúdo congelado durante a migração de integridade."
                )
            )

            self.questoes_integridade_resumo.style().unpolish(
                self.questoes_integridade_resumo
            )
            self.questoes_integridade_resumo.style().polish(
                self.questoes_integridade_resumo
            )

        if hasattr(
            self,
            "botao_resolver_questoes"
        ):
            possui_questoes = (
                estatisticas[
                    "total"
                ] > 0
            )

            self.botao_resolver_questoes.setEnabled(
                possui_questoes
            )
            self.botao_resolver_questoes.setToolTip(
                (
                    "Iniciar uma sessão com as questões do perfil ativo."
                    if possui_questoes
                    else (
                        "Cadastre ou importe pelo menos uma questão "
                        "antes de iniciar uma sessão."
                    )
                )
            )

        selecao_disciplina = (
            self.questoes_filtro_disciplina
            .currentText()
        )

        disciplinas = [
            nome
            for _, nome in listar_disciplinas(
                concurso_id
            )
        ]

        self.questoes_filtro_disciplina.blockSignals(
            True
        )
        self.questoes_filtro_disciplina.clear()
        self.questoes_filtro_disciplina.addItem(
            "Todas disciplinas"
        )
        self.questoes_filtro_disciplina.addItems(
            disciplinas
        )

        if selecao_disciplina in (
            ["Todas disciplinas"]
            + disciplinas
        ):
            self.questoes_filtro_disciplina.setCurrentText(
                selecao_disciplina
            )

        self.questoes_filtro_disciplina.blockSignals(
            False
        )

        self.atualizar_filtro_topicos_questoes()
        self.filtrar_questoes()

        self._central_questoes_suja = False
        self._central_questoes_concurso_id = int(concurso_id)

        # Se a navegação veio de um tópico, aplica o contexto somente agora,
        # depois que disciplinas/tópicos e a grade já foram reconstruídos.
        if getattr(self, "_central_questoes_contexto_pendente", None):
            QTimer.singleShot(0, self._aplicar_contexto_pendente_central_questoes)

    def atualizar_filtro_topicos_questoes(self):
        if not hasattr(
            self,
            "questoes_filtro_topico"
        ):
            return

        selecao_anterior = (
            self.questoes_filtro_topico
            .currentText()
        )

        disciplina = (
            self.questoes_filtro_disciplina
            .currentText()
        )

        if (
            not disciplina
            or disciplina
            == "Todas disciplinas"
        ):
            topicos = sorted(
                {
                    item[
                        "topico"
                    ]
                    for item in self.dados_questoes
                },
                key=str.lower
            )
        else:
            topicos = sorted(
                {
                    item[
                        "topico"
                    ]
                    for item in self.dados_questoes
                    if item[
                        "disciplina"
                    ] == disciplina
                },
                key=str.lower
            )

        self.questoes_filtro_topico.blockSignals(
            True
        )
        self.questoes_filtro_topico.clear()
        self.questoes_filtro_topico.addItem(
            "Todos tópicos"
        )
        self.questoes_filtro_topico.addItems(
            topicos
        )

        if selecao_anterior in (
            ["Todos tópicos"]
            + topicos
        ):
            self.questoes_filtro_topico.setCurrentText(
                selecao_anterior
            )

        self.questoes_filtro_topico.blockSignals(
            False
        )

        self.atualizar_filtro_capitulos_questoes()

    def atualizar_filtro_capitulos_questoes(self):
        if not hasattr(
            self,
            "questoes_filtro_capitulo"
        ):
            return

        selecao_anterior = (
            self.questoes_filtro_capitulo
            .currentData()
        )
        disciplina = (
            self.questoes_filtro_disciplina
            .currentText()
        )
        topico = (
            self.questoes_filtro_topico
            .currentText()
        )

        questoes_contexto = [
            item
            for item in self.dados_questoes
            if (
                not disciplina
                or disciplina == "Todas disciplinas"
                or item["disciplina"] == disciplina
            )
            and (
                not topico
                or topico == "Todos tópicos"
                or item["topico"] == topico
            )
        ]

        capitulos = sorted(
            {
                (
                    item["capitulo_id"],
                    item["capitulo"],
                    item["topico"],
                    item["disciplina"],
                )
                for item in questoes_contexto
                if item.get("capitulo_id") is not None
                and item.get("capitulo")
            },
            key=lambda item: (
                item[3].lower(),
                item[2].lower(),
                item[1].lower(),
            )
        )
        possui_sem_capitulo = any(
            item.get("capitulo_id") is None
            for item in questoes_contexto
        )

        self.questoes_filtro_capitulo.blockSignals(
            True
        )
        self.questoes_filtro_capitulo.clear()
        self.questoes_filtro_capitulo.addItem(
            "Todos capítulos",
            None
        )

        if possui_sem_capitulo:
            self.questoes_filtro_capitulo.addItem(
                "Sem capítulo",
                "sem_capitulo"
            )

        topico_especifico = (
            topico
            and topico != "Todos tópicos"
        )
        disciplina_especifica = (
            disciplina
            and disciplina != "Todas disciplinas"
        )

        for (
            capitulo_id,
            nome_capitulo,
            nome_topico,
            nome_disciplina,
        ) in capitulos:
            if topico_especifico:
                rotulo = nome_capitulo
            elif disciplina_especifica:
                rotulo = f"{nome_topico} — {nome_capitulo}"
            else:
                rotulo = (
                    f"{nome_disciplina} — {nome_topico} — "
                    f"{nome_capitulo}"
                )

            self.questoes_filtro_capitulo.addItem(
                rotulo,
                capitulo_id
            )

        indice_anterior = (
            self.questoes_filtro_capitulo
            .findData(selecao_anterior)
        )
        if indice_anterior >= 0:
            self.questoes_filtro_capitulo.setCurrentIndex(
                indice_anterior
            )

        self.questoes_filtro_capitulo.blockSignals(
            False
        )

    def _reposicionar_checkbox_cabecalho_questoes(self):
        """Mantém o checkbox global centralizado na primeira coluna."""
        if not hasattr(self, "questoes_selecionar_todas_header"):
            return
        if not hasattr(self, "tabela_questoes"):
            return

        header = self.tabela_questoes.horizontalHeader()
        checkbox = self.questoes_selecionar_todas_header
        tamanho = checkbox.sizeHint()
        largura = max(18, tamanho.width())
        altura = max(18, tamanho.height())
        x = header.sectionViewportPosition(0) + max(
            0,
            (header.sectionSize(0) - largura) // 2
        )
        y = max(0, (header.height() - altura) // 2)
        checkbox.setGeometry(x, y, largura, altura)
        checkbox.raise_()

    def _sincronizar_selecao_global_questoes(self):
        """Sincroniza os controles 'selecionar tudo' com as caixas da grade."""
        if not hasattr(self, "tabela_questoes"):
            return

        total = self.tabela_questoes.rowCount()
        marcadas = 0
        for linha in range(total):
            item = self.tabela_questoes.item(linha, 0)
            if item is not None and item.checkState() == Qt.Checked:
                marcadas += 1

        estado = Qt.Unchecked
        if total > 0 and marcadas == total:
            estado = Qt.Checked
        elif marcadas > 0:
            estado = Qt.PartiallyChecked

        controle = getattr(self, "questoes_selecionar_todas", None)
        if controle is not None:
            controle.blockSignals(True)
            controle.setChecked(estado == Qt.Checked)
            controle.setText(f"Selecionar todo o resultado · {total}")
            controle.setEnabled(total > 0)
            controle.blockSignals(False)

        cabecalho = getattr(
            self,
            "questoes_selecionar_todas_header",
            None
        )
        if cabecalho is not None:
            cabecalho.blockSignals(True)
            cabecalho.setCheckState(estado)
            cabecalho.setEnabled(total > 0)
            cabecalho.setToolTip(
                f"Selecionar todas as {total} questão(ões) do resultado atual."
                if total > 0
                else "Nenhuma questão no resultado atual."
            )
            cabecalho.blockSignals(False)
            self._reposicionar_checkbox_cabecalho_questoes()

    def filtrar_questoes(self):
        if not hasattr(
            self,
            "tabela_questoes"
        ):
            return

        busca = self.normalizar_texto_questoes(
            self.questoes_busca.text()
        )

        disciplina = (
            self.questoes_filtro_disciplina
            .currentText()
        )
        topico = (
            self.questoes_filtro_topico
            .currentText()
        )
        capitulo = (
            self.questoes_filtro_capitulo
            .currentData()
        )
        dificuldade = (
            self.questoes_filtro_dificuldade
            .currentText()
        )
        formato = (
            self.questoes_filtro_formato.currentData()
            if hasattr(self, "questoes_filtro_formato")
            else None
        )
        somente_para_analise = (
            hasattr(
                self,
                "questoes_para_analise"
            )
            and self.questoes_para_analise.isChecked()
        )
        somente_duplicadas = (
            hasattr(self, "questoes_somente_duplicadas")
            and self.questoes_somente_duplicadas.isChecked()
        )
        ids_duplicadas = getattr(self, "questoes_ids_duplicadas", set())

        filtradas = []

        for item in self.dados_questoes:
            if (
                somente_para_analise
                and not item.get(
                    "analise_pendente",
                    False
                )
            ):
                continue

            if somente_duplicadas and int(item.get("id") or 0) not in ids_duplicadas:
                continue

            if (
                disciplina
                and disciplina
                != "Todas disciplinas"
                and item[
                    "disciplina"
                ] != disciplina
            ):
                continue

            if (
                topico
                and topico
                != "Todos tópicos"
                and item[
                    "topico"
                ] != topico
            ):
                continue

            if (
                capitulo == "sem_capitulo"
                and item.get("capitulo_id") is not None
            ):
                continue

            if (
                capitulo not in (None, "sem_capitulo")
                and item.get("capitulo_id") != capitulo
            ):
                continue

            if (
                dificuldade
                and dificuldade
                != "Todas dificuldades"
                and item[
                    "dificuldade"
                ] != dificuldade
            ):
                continue

            if (
                formato
                and item.get("tipo_questao", "MULTIPLA_ESCOLHA") != formato
            ):
                continue

            if busca:
                alvo = self.normalizar_texto_questoes(
                    (
                        f"{item['id']} "
                        f"{item['disciplina']} "
                        f"{item['topico']} "
                        f"{item.get('capitulo', '')} "
                        f"{item['enunciado']} "
                        f"{item['banca']} "
                        f"{item['fonte']} "
                        f"{item['dificuldade']} "
                        f"{item.get('tipo_questao', 'MULTIPLA_ESCOLHA')}"
                    )
                )

                termos = [
                    termo
                    for termo in busca.split(
                        " "
                    )
                    if termo
                ]

                if not all(
                    termo in alvo
                    for termo in termos
                ):
                    continue

            filtradas.append(
                item
            )

        self._questoes_ids_resultado_atual = [
            int(item["id"])
            for item in filtradas
            if item.get("id") is not None
        ]

        arquivadas_filtradas = sum(
            1
            for item in filtradas
            if not item.get(
                "ativa",
                True
            )
        )

        texto_contagem = (
            "1 questão"
            if len(
                filtradas
            ) == 1
            else f"{len(filtradas)} questões"
        )

        if arquivadas_filtradas > 0:
            texto_contagem += (
                f" • {arquivadas_filtradas} arquivada(s)"
            )

        if somente_para_analise:
            texto_contagem += " • fila de análise"
        if somente_duplicadas:
            texto_contagem += " • duplicadas"

        self.questoes_contagem.setText(
            texto_contagem
        )

        # QTableWidget emite sinais de seleção/item a cada inserção e também
        # repinta a grade repetidamente. Para centenas de questões isso domina
        # o tempo percebido. Suspenda ambos durante a montagem em lote.
        ordenacao_ativa = self.tabela_questoes.isSortingEnabled()
        self.tabela_questoes.setUpdatesEnabled(False)
        self.tabela_questoes.blockSignals(True)
        self.tabela_questoes.setSortingEnabled(False)

        self.tabela_questoes.setRowCount(
            len(
                filtradas
            )
        )

        for linha, item in enumerate(
            filtradas
        ):
            marca = QTableWidgetItem("")
            marca.setFlags(Qt.ItemIsEnabled | Qt.ItemIsUserCheckable | Qt.ItemIsSelectable)
            marca.setCheckState(Qt.Unchecked)
            marca.setData(Qt.UserRole, item["id"])
            self.tabela_questoes.setItem(linha, 0, marca)

            enunciado_resumido = " ".join(
                item[
                    "enunciado"
                ].split()
            )

            if len(
                enunciado_resumido
            ) > 150:
                enunciado_resumido = (
                    enunciado_resumido[
                        :147
                    ]
                    + "..."
                )

            enunciado_exibicao = enunciado_resumido
            estado_texto = "Ativa" if item.get("ativa", True) else "Arquivada"
            eh_duplicada = int(item.get("id") or 0) in ids_duplicadas
            if item.get("analise_pendente", False) and eh_duplicada:
                analise_texto = "Pendente · Dup."
            elif item.get("analise_pendente", False):
                analise_texto = "Pendente"
            elif eh_duplicada:
                analise_texto = "Duplicada"
            else:
                analise_texto = "—"

            valores = [
                str(item["id"]),
                item["disciplina"],
                item["topico"],
                enunciado_exibicao,
                item["banca"] or "—",
                str(item["ano"]) if item["ano"] else "—",
                item["dificuldade"],
                item["gabarito"] or "—",
                analise_texto,
                estado_texto,
            ]

            for indice_valor, valor in enumerate(
                valores,
                start=1
            ):
                celula = QTableWidgetItem(
                    valor
                )

                if indice_valor == 4:
                    celula.setData(
                        Qt.UserRole,
                        item[
                            "id"
                        ]
                    )
                    celula.setToolTip(
                        item[
                            "enunciado"
                        ]
                        + (
                            "\n\nQuestão arquivada — não entra em novas sessões."
                            if not item.get(
                                "ativa",
                                True
                            )
                            else ""
                        )
                        + (
                            "\n\nSeparada para análise posterior."
                            if item.get(
                                "analise_pendente",
                                False
                            )
                            else ""
                        )
                    )

                elif indice_valor == 2:
                    celula.setToolTip(
                        item[
                            "disciplina"
                        ]
                    )

                elif indice_valor == 3:
                    celula.setToolTip(
                        item[
                            "topico"
                        ]
                    )

                elif indice_valor == 5:
                    celula.setToolTip(
                        item[
                            "banca"
                        ]
                        or "Banca não informada"
                    )

                if indice_valor in (
                    1,
                    6,
                    7,
                    8,
                    9,
                    10
                ):
                    celula.setTextAlignment(
                        Qt.AlignCenter
                    )

                if not item.get(
                    "ativa",
                    True
                ):
                    aplicar_destaque_tabela(
                        celula,
                        "inativo",
                        True
                    )
                    aplicar_destaque_tabela(
                        marca,
                        "inativo",
                        True
                    )

                if indice_valor == 9 and (
                    item.get("analise_pendente", False) or eh_duplicada
                ):
                    aplicar_destaque_tabela(
                        celula,
                        "atencao",
                        True
                    )

                self.tabela_questoes.setItem(
                    linha,
                    indice_valor,
                    celula
                )

            self.tabela_questoes.setRowHeight(
                linha,
                34
            )

        self.tabela_questoes.setSortingEnabled(ordenacao_ativa)
        self.tabela_questoes.blockSignals(False)
        self.tabela_questoes.setUpdatesEnabled(True)
        self.tabela_questoes.viewport().update()

        if hasattr(self, "questoes_selecionar_todas"):
            self.questoes_selecionar_todas.blockSignals(True)
            self.questoes_selecionar_todas.setChecked(False)
            self.questoes_selecionar_todas.setText(
                f"Selecionar todo o resultado · {len(filtradas)}"
            )
            self.questoes_selecionar_todas.setEnabled(bool(filtradas))
            self.questoes_selecionar_todas.blockSignals(False)
        if hasattr(self, "questoes_selecionar_todas_header"):
            self.questoes_selecionar_todas_header.blockSignals(True)
            self.questoes_selecionar_todas_header.setCheckState(Qt.Unchecked)
            self.questoes_selecionar_todas_header.setEnabled(bool(filtradas))
            self.questoes_selecionar_todas_header.blockSignals(False)
            self._reposicionar_checkbox_cabecalho_questoes()
        self.atualizar_acoes_questao()

    def obter_ids_questoes_marcadas_central(self):
        ids = []

        for linha in range(self.tabela_questoes.rowCount()):
            item = self.tabela_questoes.item(linha, 0)
            if item is not None and item.checkState() == Qt.Checked:
                questao_id = item.data(Qt.UserRole)
                if questao_id is not None and int(questao_id) not in ids:
                    ids.append(int(questao_id))

        # Além das caixas, Ctrl/Shift também podem formar uma seleção em lote.
        modelo_selecao = self.tabela_questoes.selectionModel()
        if modelo_selecao is not None:
            for indice in modelo_selecao.selectedRows():
                item = self.tabela_questoes.item(indice.row(), 0)
                if item is None:
                    continue
                questao_id = item.data(Qt.UserRole)
                if questao_id is not None and int(questao_id) not in ids:
                    ids.append(int(questao_id))

        return ids

    def alternar_marcacao_questoes_central(self, estado):
        try:
            marcado = int(estado) == int(Qt.Checked)
        except (TypeError, ValueError):
            marcado = estado == Qt.Checked

        self.tabela_questoes.setUpdatesEnabled(False)
        self.tabela_questoes.blockSignals(True)
        for linha in range(self.tabela_questoes.rowCount()):
            item = self.tabela_questoes.item(linha, 0)
            if item is not None:
                item.setCheckState(Qt.Checked if marcado else Qt.Unchecked)
        self.tabela_questoes.blockSignals(False)
        self.tabela_questoes.setUpdatesEnabled(True)
        self.tabela_questoes.viewport().update()
        self._sincronizar_selecao_global_questoes()
        self.atualizar_acoes_questao()

    def abrir_lixeira_questoes_central(self):
        janela = JanelaLixeiraQuestoes(self)
        janela.exec()
        self.carregar_questoes()
        self.atualizar_dashboard()

    def obter_questao_selecionada_id(self):
        ids_marcados = self.obter_ids_questoes_marcadas_central()
        if len(ids_marcados) == 1:
            return ids_marcados[0]

        linha = (
            self.tabela_questoes.currentRow()
        )

        if linha < 0:
            QMessageBox.information(
                self,
                "Questões",
                "Selecione uma questão na tabela."
            )
            return None

        item = self.tabela_questoes.item(
            linha,
            4
        )

        if item is None:
            return None

        return item.data(
            Qt.UserRole
        )

    def obter_questao_selecionada_dados(
        self
    ):
        questao_id = (
            self.obter_questao_selecionada_id()
        )

        if questao_id is None:
            return None

        return next(
            (
                item
                for item in self.dados_questoes
                if item[
                    "id"
                ] == questao_id
            ),
            obter_questao(
                questao_id
            )
        )

    def atualizar_acoes_questao(self):
        if not hasattr(self, "questoes_estado"):
            return

        self._sincronizar_selecao_global_questoes()

        ids = self.obter_ids_questoes_marcadas_central()
        if not ids:
            linha = self.tabela_questoes.currentRow()
            if linha >= 0:
                item = self.tabela_questoes.item(linha, 4)
                if item is not None and item.data(Qt.UserRole) is not None:
                    ids = [int(item.data(Qt.UserRole))]

        if not ids:
            self.questoes_estado.setText("Arquivar")
            self.questoes_estado.setEnabled(False)
            self.questoes_remover.setEnabled(False)
            self.questoes_concluir_analise.setEnabled(False)
            self.questoes_visualizar.setEnabled(False)
            self.questoes_editar.setEnabled(False)
            self.questoes_mover.setEnabled(False)
            self.questoes_editar_lote.setEnabled(False)
            return

        estados_por_id = {
            int(item["id"]): bool(item.get("ativa", True))
            for item in self.dados_questoes
            if item.get("id") is not None
        }
        estados = []
        for questao_id in ids:
            if int(questao_id) in estados_por_id:
                estados.append(estados_por_id[int(questao_id)])
                continue
            integridade = obter_integridade_questao(questao_id)
            if integridade is not None:
                estados.append(bool(integridade.get("ativa")))

        if not estados:
            self.questoes_estado.setEnabled(False)
            self.questoes_remover.setEnabled(False)
            self.questoes_concluir_analise.setEnabled(False)
            self.questoes_visualizar.setEnabled(False)
            self.questoes_editar.setEnabled(False)
            self.questoes_mover.setEnabled(False)
            self.questoes_editar_lote.setEnabled(False)
            return

        self.questoes_estado.setEnabled(True)
        self.questoes_remover.setEnabled(True)
        self.questoes_mover.setEnabled(True)
        self.questoes_editar_lote.setEnabled(True)
        selecao_unica = len(
            ids
        ) == 1
        self.questoes_visualizar.setEnabled(
            selecao_unica
        )
        self.questoes_editar.setEnabled(
            selecao_unica
        )

        ids_para_analise = {
            int(
                item[
                    "id"
                ]
            )
            for item in self.dados_questoes
            if item.get(
                "analise_pendente",
                False
            )
        }
        quantidade_para_analise = sum(
            1
            for questao_id in ids
            if questao_id in ids_para_analise
        )
        self.questoes_concluir_analise.setEnabled(
            quantidade_para_analise > 0
        )
        self.questoes_concluir_analise.setText(
            (
                "Concluir análise"
                if quantidade_para_analise <= 1
                else f"Concluir {quantidade_para_analise} análises"
            )
        )

        if all(estados):
            self.questoes_estado.setText(
                "Arquivar" if len(ids) == 1 else f"Arquivar {len(ids)}"
            )
        elif not any(estados):
            self.questoes_estado.setText(
                "Reativar" if len(ids) == 1 else f"Reativar {len(ids)}"
            )
        else:
            self.questoes_estado.setText("Alternar estado")

        self.questoes_remover.setText(
            "Excluir" if len(ids) == 1 else f"Excluir {len(ids)}"
        )

    def concluir_analise_questoes_central(self):
        ids = self.obter_ids_questoes_marcadas_central()

        if not ids:
            questao_id = self.obter_questao_selecionada_id()
            ids = [
                questao_id
            ] if questao_id is not None else []

        ids_para_analise = {
            int(
                item[
                    "id"
                ]
            )
            for item in self.dados_questoes
            if item.get(
                "analise_pendente",
                False
            )
        }
        ids = [
            questao_id
            for questao_id in ids
            if questao_id in ids_para_analise
        ]

        if not ids:
            return

        resposta = QMessageBox.question(
            self,
            "Concluir análise",
            (
                f"Retirar {len(ids)} questão(ões) da fila de análise?\n\n"
                "O conteúdo e o histórico das questões serão preservados."
            ),
            QMessageBox.Yes
            | QMessageBox.No,
            QMessageBox.Yes
        )

        if resposta != QMessageBox.Yes:
            return

        concluidas = sum(
            1
            for questao_id in ids
            if definir_questao_analise_pendente(
                questao_id,
                False
            )
        )

        self.carregar_questoes()
        self.notificar_dados_alterados(
            "questoes"
        )

        if concluidas != len(
            ids
        ):
            QMessageBox.warning(
                self,
                "Concluir análise",
                (
                    f"{concluidas} de {len(ids)} questão(ões) "
                    "foram retiradas da fila."
                )
            )

    def alternar_estado_questoes_central(self):
        ids = self.obter_ids_questoes_marcadas_central()
        if not ids:
            questao_id = self.obter_questao_selecionada_id()
            ids = [questao_id] if questao_id is not None else []
        if not ids:
            return

        estados_por_id = {
            int(item["id"]): bool(item.get("ativa", True))
            for item in self.dados_questoes
            if item.get("id") is not None
        }
        estados = []
        for questao_id in ids:
            if int(questao_id) in estados_por_id:
                estados.append((questao_id, estados_por_id[int(questao_id)]))
                continue
            integridade = obter_integridade_questao(questao_id)
            if integridade is not None:
                estados.append((questao_id, bool(integridade.get("ativa"))))

        if not estados:
            return

        if all(ativa for _, ativa in estados):
            acao = "desativar"
            texto = (
                f"Arquivar {len(estados)} questão(ões)?\n\n"
                "Elas sairão das novas sessões, mas continuarão armazenadas e poderão ser reativadas depois."
            )
        elif not any(ativa for _, ativa in estados):
            acao = "reativar"
            texto = (
                f"Reativar {len(estados)} questão(ões)?\n\n"
                "Elas voltarão a participar normalmente das sessões do Vighna."
            )
        else:
            acao = "alternar"
            texto = (
                f"Alternar o estado de {len(estados)} questão(ões)?\n\n"
                "As ativas serão arquivadas e as arquivadas serão reativadas."
            )

        resposta = QMessageBox.question(
            self,
            "Alterar estado das questões",
            texto,
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if resposta != QMessageBox.Yes:
            return

        try:
            fazer_backup("antes_alterar_estado_questoes")
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Backup",
                f"A operação foi cancelada porque o backup falhou.\n\n{erro}",
            )
            return

        for questao_id, ativa in estados:
            if acao == "desativar":
                arquivar_questao(questao_id)
            elif acao == "reativar":
                reativar_questao(questao_id)
            else:
                arquivar_questao(questao_id) if ativa else reativar_questao(questao_id)

        self.carregar_questoes()
        self.notificar_dados_alterados("questoes")

    def reativar_questao_selecionada(
        self
    ):
        questao_id = (
            self.obter_questao_selecionada_id()
        )

        if questao_id is None:
            return

        integridade = obter_integridade_questao(
            questao_id
        )

        if (
            integridade is None
            or integridade[
                "ativa"
            ]
        ):
            return

        resposta = QMessageBox.question(
            self,
            "Reativar questão",
            (
                f"Reativar a questão #{questao_id}?\\n\\n"
                "Ela voltará a participar das sessões inteligentes "
                "e poderá receber novas tentativas."
            ),
            QMessageBox.Yes
            | QMessageBox.No,
            QMessageBox.Yes
        )

        if resposta != QMessageBox.Yes:
            return

        if reativar_questao(
            questao_id
        ):
            self.carregar_questoes()
        else:
            QMessageBox.warning(
                self,
                "Reativar questão",
                "A questão não pôde ser reativada."
            )

    def abrir_historico_questoes(self):
        janela = JanelaHistoricoQuestoes(
            self
        )
        janela.exec()

        self.carregar_questoes()
        self.atualizar_dashboard()

    def abrir_banco_erros(self):
        JanelaBancoErros(self).exec()
        self.atualizar_dashboard()

    def resolver_questoes(self):
        concurso_id = (
            obter_concurso_ativo()[0]
        )

        disponiveis = listar_questoes_resolucao(
            concurso_id
        )

        if not disponiveis:
            QMessageBox.information(
                self,
                "Resolver questões",
                (
                    "O perfil ativo ainda não possui questões disponíveis.\n\n"
                    "Cadastre ou importe questões antes de iniciar uma sessão."
                )
            )
            return

        configuracao = JanelaConfigurarResolucaoQuestoes(
            self
        )

        if configuracao.exec() != QDialog.Accepted:
            return

        if not configuracao.configuracao:
            return

        try:
            janela = JanelaResolverQuestoes(
                configuracao.configuracao,
                self
            )
            janela.exec_nao_modal()
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Resolver questões",
                (
                    "Não foi possível iniciar a sessão de questões.\n\n"
                    f"{erro}"
                )
            )
            return

        self.carregar_questoes()
        self.atualizar_dashboard()

    def mostrar_ajuda_banco_questoes(self):
        QMessageBox.information(
            self,
            "Central de Questões — gestão do banco",
            (
                "A Central de Questões é a área administrativa do banco do VighnaStudy.\n\n"
                "Aqui você organiza o conteúdo que será usado pelas revisões, pelo Motor V5, pelos treinos e pelas baterias inteligentes.\n\n"
                "• Nova questão: cadastra uma questão manualmente.\n"
                "• Central de importação: reúne PDF, TXT, texto colado e CSV com validação antes da gravação.\n"
                "• Arquivar: retira temporariamente a questão das novas sessões sem apagá-la.\n"
                "• Para análise: reúne questões sinalizadas durante uma bateria para visualização e edição.\n"
                "• Lixeira: recebe questões removidas e permite restaurar ou excluir permanentemente.\n"
                "• Seleção múltipla: use as caixas ou Ctrl/Shift para mover e editar questões em lote.\n"
                "• Selecionar resultado: marque a caixa no cabeçalho ou na barra de ações para selecionar todas as questões retornadas pelos filtros atuais.\n"
                "• Duplicadas: identifica questões com enunciado, alternativas e gabarito iguais.\n\n"
                "A prática de questões, os simulados, a efetividade e o histórico de estudo ficam fora desta Central para manter esta tela focada exclusivamente na organização do banco."
            ),
        )

    def abrir_itens_desativados(self, aba=0):
        janela = JanelaItensDesativados(aba=aba, parent=self)
        janela.exec()
        self.carregar_botoes_disciplinas()
        if hasattr(self, "tabela_questoes"):
            self.carregar_questoes()
        if self.disciplina_atual:
            self.atualizar_estado_disciplina_atual()
            self.carregar_topicos()
        self.notificar_dados_alterados("all")

    def abrir_gerenciador_questoes_topicos(self):
        janela = JanelaGerenciarQuestoesTopico(
            self
        )
        janela.exec()
        self.carregar_questoes()
        self.atualizar_dashboard()

    def nova_questao(self):
        janela = JanelaQuestaoEditor(
            parent=self
        )

        # Quando a Central está filtrada em um tópico específico (inclusive
        # quando veio do botão Ver questões), o cadastro manual já nasce nesse
        # contexto, sem exigir que o usuário refaça a classificação.
        topico_id_contexto = self._obter_topico_id_contexto_central_questoes()
        if topico_id_contexto is not None:
            contexto = obter_contexto_topico(topico_id_contexto) or {}
            disciplina = str(contexto.get("disciplina_nome") or "")
            indice_disc = janela.questao_disciplina.findText(
                disciplina,
                Qt.MatchFixedString,
            )
            if indice_disc >= 0:
                janela.questao_disciplina.setCurrentIndex(indice_disc)
                janela.carregar_topicos()
            indice_top = janela.questao_topico.findData(topico_id_contexto)
            if indice_top >= 0:
                janela.questao_topico.setCurrentIndex(indice_top)
                janela.carregar_capitulos()

        if janela.exec() == QDialog.Accepted:
            self.carregar_questoes()

    def visualizar_questao_linha(
        self,
        linha,
        coluna
    ):
        item = self.tabela_questoes.item(
            linha,
            4
        )

        if item is None:
            return

        questao_id = item.data(
            Qt.UserRole
        )

        if questao_id is None:
            return

        JanelaVisualizarQuestao(
            questao_id,
            self
        ).exec()

    def visualizar_questao_selecionada(self):
        questao_id = (
            self.obter_questao_selecionada_id()
        )

        if questao_id is None:
            return

        JanelaVisualizarQuestao(
            questao_id,
            self
        ).exec()

    def editar_questao_selecionada(self):
        questao_id = (
            self.obter_questao_selecionada_id()
        )

        if questao_id is None:
            return

        janela = JanelaQuestaoEditor(
            questao_id,
            self
        )

        if janela.exec() == QDialog.Accepted:
            self.carregar_questoes()

    def obter_ids_questoes_para_acao_lote(self):
        ids = self.obter_ids_questoes_marcadas_central()
        if ids:
            return ids

        questao_id = self.obter_questao_selecionada_id()
        return [questao_id] if questao_id is not None else []

    def mover_questoes_selecionadas(self):
        ids = self.obter_ids_questoes_para_acao_lote()
        if not ids:
            return

        janela = JanelaEdicaoLoteQuestoes(
            len(ids),
            modo="mover",
            parent=self,
        )
        if janela.exec() != QDialog.Accepted or not janela.campos:
            return

        resposta = QMessageBox.question(
            self,
            "Mover questões",
            (
                f"Mover {len(ids)} questão(ões) para a classificação selecionada?\n\n"
                "O histórico de respostas será preservado."
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if resposta != QMessageBox.Yes:
            return

        try:
            fazer_backup("antes_mover_questoes_lote")
            atualizadas = atualizar_questoes_lote(ids, janela.campos)
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Mover questões",
                f"Não foi possível mover as questões.\n\n{erro}",
            )
            return

        self.carregar_questoes()
        self.notificar_dados_alterados("questoes")
        if atualizadas != len(ids):
            QMessageBox.warning(
                self,
                "Mover questões",
                f"{atualizadas} de {len(ids)} questão(ões) foram atualizadas.",
            )

    def editar_questoes_selecionadas_lote(self):
        ids = self.obter_ids_questoes_para_acao_lote()
        if not ids:
            return

        janela = JanelaEdicaoLoteQuestoes(
            len(ids),
            modo="editar",
            parent=self,
        )
        if janela.exec() != QDialog.Accepted or not janela.campos:
            return

        resposta = QMessageBox.question(
            self,
            "Editar em lote",
            (
                f"Aplicar as alterações em {len(ids)} questão(ões)?\n\n"
                "Somente os campos marcados serão modificados."
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if resposta != QMessageBox.Yes:
            return

        try:
            fazer_backup("antes_editar_questoes_lote")
            atualizadas = atualizar_questoes_lote(ids, janela.campos)
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Editar em lote",
                f"Não foi possível aplicar as alterações.\n\n{erro}",
            )
            return

        self.carregar_questoes()
        self.notificar_dados_alterados("questoes")
        if atualizadas != len(ids):
            QMessageBox.warning(
                self,
                "Editar em lote",
                f"{atualizadas} de {len(ids)} questão(ões) foram atualizadas.",
            )

    def excluir_questao_selecionada(self):
        ids = self.obter_ids_questoes_marcadas_central()
        if not ids:
            questao_id = self.obter_questao_selecionada_id()
            ids = [questao_id] if questao_id is not None else []
        if not ids:
            return

        resposta = QMessageBox.question(
            self,
            "Excluir questões",
            (
                f"Mover {len(ids)} questão(ões) para a Lixeira?\n\n"
                "Elas deixarão o banco ativo, mas ainda poderão ser restauradas pela Lixeira. "
                "A exclusão permanente fica disponível somente dentro da Lixeira."
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if resposta != QMessageBox.Yes:
            return

        try:
            fazer_backup("antes_enviar_questoes_lixeira")
        except Exception as erro:
            QMessageBox.critical(
                self,
                "Backup",
                f"A operação foi cancelada porque o backup falhou.\n\n{erro}",
            )
            return

        movidas = 0
        for questao_id in ids:
            if mover_questao_para_lixeira(questao_id):
                movidas += 1

        self.carregar_questoes()
        self.notificar_dados_alterados("questoes")

        if movidas != len(ids):
            QMessageBox.warning(
                self,
                "Lixeira",
                f"{movidas} de {len(ids)} questão(ões) foram enviadas à lixeira.",
            )

    def abrir_prompts_ia(self):
        janela = JanelaPromptsIA(
            self
        )
        janela.exec()

    def abrir_central_importacao_questoes(self, topico_id_padrao=None):
        # clicked(bool) de QPushButton/QToolButton pode fornecer False como
        # argumento. Isso não é um ID de tópico e deve ser tratado como ausência
        # de contexto explícito.
        if isinstance(topico_id_padrao, bool):
            topico_id_padrao = None
        if topico_id_padrao is None:
            topico_id_padrao = self._obter_topico_id_contexto_central_questoes()

        janela = JanelaCentralImportacaoQuestoes(
            self,
            topico_id_padrao=topico_id_padrao,
        )

        if janela.exec() != QDialog.Accepted:
            return

        origem = janela.origem_escolhida

        if origem == "pdf":
            if topico_id_padrao is None:
                self.importar_questoes_pdf()
            else:
                self.importar_questoes_pdf(topico_id_padrao=topico_id_padrao)
        elif origem == "txt":
            if topico_id_padrao is None:
                self.importar_questoes_txt()
            else:
                self.importar_questoes_txt(topico_id_padrao=topico_id_padrao)
        elif origem == "texto":
            if topico_id_padrao is None:
                self.importar_questoes_texto()
            else:
                self.importar_questoes_texto(topico_id_padrao=topico_id_padrao)
        elif origem == "csv":
            if topico_id_padrao is None:
                self.importar_questoes_csv()
            else:
                self.importar_questoes_csv(topico_id_padrao=topico_id_padrao)

    def importar_questoes_texto(self, topico_id_padrao=None):
        janela = JanelaImportarTextoQuestoes(
            self,
            topico_id_padrao=topico_id_padrao,
        )

        if janela.exec() == QDialog.Accepted:
            if janela.importadas > 0:
                self.carregar_questoes()
                self.notificar_dados_alterados("questoes")

    def importar_questoes_txt(self, topico_id_padrao=None):
        caminho, _ = QFileDialog.getOpenFileName(
            self,
            "Selecionar arquivo TXT de questões",
            "",
            "Arquivo de texto (*.txt)"
        )

        if not caminho:
            return

        QApplication.setOverrideCursor(Qt.WaitCursor)

        try:
            dados_txt = ler_arquivo_txt_questoes(caminho)
            analise = analisar_texto_questoes_pdf(
                dados_txt["texto"],
                []
            )
        except Exception as erro:
            QApplication.restoreOverrideCursor()
            QMessageBox.critical(
                self,
                "Importação por TXT",
                f"Não foi possível ler o arquivo TXT.\n\n{erro}"
            )
            return

        QApplication.restoreOverrideCursor()

        if dados_txt.get("caracteres", 0) < 30:
            QMessageBox.information(
                self,
                "Importação por TXT",
                "O arquivo TXT possui pouco conteúdo para uma importação de questões."
            )
            return

        if analise.get("quantidade", 0) <= 0:
            resposta = QMessageBox.question(
                self,
                "Nenhuma questão detectada",
                (
                    "O VighnaStudy conseguiu ler o arquivo TXT, mas não reconheceu "
                    "questões completas com alternativas.\n\n"
                    "Deseja visualizar o conteúdo do arquivo para conferir a formatação?"
                ),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes
            )

            if resposta == QMessageBox.Yes:
                JanelaTextoExtraidoPDF(
                    dados_txt["texto"],
                    self,
                    origem_tipo="txt"
                ).exec()
            return

        janela = JanelaImportarPDFQuestoes(
            caminho,
            dados_txt,
            analise,
            self,
            origem_tipo="txt",
            nome_origem=Path(caminho).name,
            topico_id_padrao=topico_id_padrao,
        )

        if janela.exec() == QDialog.Accepted and janela.importadas > 0:
            self.carregar_questoes()
            self.notificar_dados_alterados("questoes")

    def importar_questoes_pdf(self, topico_id_padrao=None):
        if not dependencia_pdf_disponivel():
            QMessageBox.warning(
                self,
                "Importação por PDF",
                (
                    "A biblioteca necessária para ler PDFs ainda não "
                    "está instalada neste ambiente.\n\n"
                    "Feche o VighnaStudy e execute:\n\n"
                    "python -m pip install pypdf\n\n"
                    "O pacote desta atualização também contém o arquivo "
                    "instalar_dependencia_pdf.bat."
                )
            )
            return

        caminho, _ = QFileDialog.getOpenFileName(
            self,
            "Selecionar PDF de questões",
            "",
            "Arquivo PDF (*.pdf)"
        )

        if not caminho:
            return

        QApplication.setOverrideCursor(
            Qt.WaitCursor
        )

        try:
            dados_pdf = extrair_texto_pdf_questoes(
                caminho
            )
            analise = analisar_texto_questoes_pdf(
                dados_pdf[
                    "texto"
                ],
                dados_pdf[
                    "faixas_paginas"
                ]
            )
        except Exception as erro:
            QApplication.restoreOverrideCursor()

            QMessageBox.critical(
                self,
                "Importação por PDF",
                (
                    "Não foi possível ler o PDF.\n\n"
                    f"{erro}"
                )
            )
            return

        QApplication.restoreOverrideCursor()

        if dados_pdf[
            "caracteres"
        ] < 80:
            QMessageBox.information(
                self,
                "Importação por PDF",
                (
                    "O PDF praticamente não possui texto extraível.\n\n"
                    "Ele provavelmente é um PDF escaneado ou formado "
                    "por imagens. A Importação PDF V1 trabalha com PDFs "
                    "que possuam texto selecionável.\n\n"
                    "OCR para PDFs digitalizados poderá ser acrescentado "
                    "em uma etapa posterior."
                )
            )
            return

        if analise[
            "quantidade"
        ] <= 0:
            resposta = QMessageBox.question(
                self,
                "Nenhuma questão detectada",
                (
                    "O VighnaStudy conseguiu ler o texto do PDF, mas "
                    "não reconheceu uma estrutura de questões com "
                    "alternativas A–E.\n\n"
                    "Deseja visualizar o texto extraído para conferir "
                    "a formatação do arquivo?"
                ),
                QMessageBox.Yes
                | QMessageBox.No,
                QMessageBox.Yes
            )

            if resposta == QMessageBox.Yes:
                JanelaTextoExtraidoPDF(
                    dados_pdf[
                        "texto"
                    ],
                    self
                ).exec()

            return

        janela = JanelaImportarPDFQuestoes(
            caminho,
            dados_pdf,
            analise,
            self,
            topico_id_padrao=topico_id_padrao,
        )

        if janela.exec() == QDialog.Accepted:
            if janela.importadas > 0:
                self.carregar_questoes()
                self.notificar_dados_alterados(
                    "questoes"
                )

    def salvar_modelo_csv_questoes(self):
        caminho, _ = QFileDialog.getSaveFileName(
            self,
            "Salvar modelo de importação",
            "modelo_importacao_questoes.csv",
            "Arquivo CSV (*.csv)"
        )

        if not caminho:
            return

        if not caminho.lower().endswith(
            ".csv"
        ):
            caminho += ".csv"

        cabecalho = [
            "disciplina",
            "topico",
            "enunciado",
            "alternativa_a",
            "alternativa_b",
            "alternativa_c",
            "alternativa_d",
            "alternativa_e",
            "gabarito",
            "explicacao",
            "banca",
            "ano",
            "fonte",
            "dificuldade",
        ]

        try:
            with open(
                caminho,
                "w",
                newline="",
                encoding="utf-8-sig"
            ) as arquivo:
                escritor = csv.writer(
                    arquivo,
                    delimiter=";"
                )
                escritor.writerow(
                    cabecalho
                )

            QMessageBox.information(
                self,
                "Modelo CSV",
                (
                    "Modelo salvo com sucesso.\n\n"
                    "O separador utilizado é ponto e vírgula (;), "
                    "compatível com o uso comum do Excel em português."
                )
            )

        except Exception as erro:
            QMessageBox.critical(
                self,
                "Modelo CSV",
                (
                    "Não foi possível salvar o modelo.\n\n"
                    f"{erro}"
                )
            )

    def normalizar_cabecalho_csv_questao(
        self,
        texto
    ):
        texto = self.normalizar_texto_questoes(
            texto
        )

        return (
            texto
            .replace(
                " ",
                "_"
            )
            .replace(
                "-",
                "_"
            )
        )

    def importar_questoes_csv(self, topico_id_padrao=None):
        caminho, _ = QFileDialog.getOpenFileName(
            self,
            "Importar questões",
            "",
            "Arquivo CSV (*.csv);;Todos os arquivos (*.*)"
        )

        if not caminho:
            return

        concurso_id = (
            obter_concurso_ativo()[0]
        )
        contexto_padrao = (
            obter_contexto_topico(topico_id_padrao)
            if topico_id_padrao is not None
            else None
        )
        disciplina_padrao = (
            str(contexto_padrao.get("disciplina_nome") or "")
            if contexto_padrao
            else ""
        )
        topico_padrao = (
            str(contexto_padrao.get("topico_nome") or "")
            if contexto_padrao
            else ""
        )

        mapa_topicos = {}

        for _, disciplina in listar_disciplinas(
            concurso_id
        ):
            for topico in listar_topicos(
                disciplina,
                concurso_id
            ):
                chave = (
                    self.normalizar_texto_questoes(
                        disciplina
                    ),
                    self.normalizar_texto_questoes(
                        topico[1]
                    ),
                )

                mapa_topicos[
                    chave
                ] = topico[0]

        if not mapa_topicos:
            QMessageBox.warning(
                self,
                "Importar questões",
                (
                    "O perfil ativo não possui tópicos disponíveis. "
                    "Cadastre e inclua os tópicos antes de importar questões."
                )
            )
            return

        try:
            try:
                texto = Path(
                    caminho
                ).read_text(
                    encoding="utf-8-sig"
                )
            except UnicodeDecodeError:
                texto = Path(
                    caminho
                ).read_text(
                    encoding="latin-1"
                )

            amostra = texto[
                :4096
            ]

            try:
                dialeto = csv.Sniffer().sniff(
                    amostra,
                    delimiters=";,\t"
                )
                delimitador = dialeto.delimiter
            except Exception:
                delimitador = ";"

            linhas = texto.splitlines()

            leitor = csv.DictReader(
                linhas,
                delimiter=delimitador
            )

            if not leitor.fieldnames:
                raise ValueError(
                    "O arquivo não possui cabeçalho."
                )

            registros = []
            linhas_validas = []
            erros = []
            duplicadas = 0
            duplicadas_linhas = []
            chaves_importacao = set()

            aliases = {
                "disciplina": "disciplina",
                "materia": "disciplina",
                "topico": "topico",
                "assunto": "topico",
                "enunciado": "enunciado",
                "questao": "enunciado",
                "alternativa_a": "alternativa_a",
                "a": "alternativa_a",
                "alternativa_b": "alternativa_b",
                "b": "alternativa_b",
                "alternativa_c": "alternativa_c",
                "c": "alternativa_c",
                "alternativa_d": "alternativa_d",
                "d": "alternativa_d",
                "alternativa_e": "alternativa_e",
                "e": "alternativa_e",
                "gabarito": "gabarito",
                "resposta": "gabarito",
                "correta": "gabarito",
                "explicacao": "explicacao",
                "comentario": "explicacao",
                "banca": "banca",
                "ano": "ano",
                "fonte": "fonte",
                "origem": "fonte",
                "dificuldade": "dificuldade",
                "nivel": "dificuldade",
            }

            for numero_linha, linha_bruta in enumerate(
                leitor,
                start=2
            ):
                linha = {}

                for cabecalho, valor in linha_bruta.items():
                    if cabecalho is None:
                        continue

                    chave_cabecalho = (
                        self.normalizar_cabecalho_csv_questao(
                            cabecalho
                        )
                    )

                    canonico = aliases.get(
                        chave_cabecalho
                    )

                    if canonico:
                        linha[
                            canonico
                        ] = str(
                            valor
                            or ""
                        ).strip()

                disciplina = (
                    linha.get("disciplina", "").strip()
                    or disciplina_padrao
                )
                topico = (
                    linha.get("topico", "").strip()
                    or topico_padrao
                )
                enunciado = linha.get(
                    "enunciado",
                    ""
                )
                gabarito = linha.get(
                    "gabarito",
                    ""
                ).strip().upper()

                if not any(
                    str(
                        valor
                        or ""
                    ).strip()
                    for valor in linha.values()
                ):
                    continue

                if (
                    not disciplina
                    or not topico
                    or not enunciado
                ):
                    erros.append(
                        (
                            numero_linha,
                            "disciplina, tópico e enunciado são obrigatórios"
                        )
                    )
                    continue

                chave_topico = (
                    self.normalizar_texto_questoes(
                        disciplina
                    ),
                    self.normalizar_texto_questoes(
                        topico
                    ),
                )

                topico_id = mapa_topicos.get(
                    chave_topico
                )

                if topico_id is None:
                    erros.append(
                        (
                            numero_linha,
                            (
                                "disciplina/tópico não encontrado "
                                "no perfil ativo"
                            )
                        )
                    )
                    continue

                alternativas = []

                for letra in "ABCDE":
                    texto_alternativa = linha.get(
                        f"alternativa_{letra.lower()}",
                        ""
                    ).strip()

                    if texto_alternativa:
                        alternativas.append({
                            "letra": letra,
                            "texto": texto_alternativa,
                            "correta": (
                                letra == gabarito
                            ),
                        })

                if len(
                    alternativas
                ) < 2:
                    erros.append(
                        (
                            numero_linha,
                            "é necessário informar pelo menos duas alternativas"
                        )
                    )
                    continue

                letras_preenchidas = {
                    item[
                        "letra"
                    ]
                    for item in alternativas
                }

                if (
                    gabarito not in "ABCDE"
                    or gabarito not in letras_preenchidas
                ):
                    erros.append(
                        (
                            numero_linha,
                            (
                                "gabarito inválido ou alternativa "
                                "correta sem texto"
                            )
                        )
                    )
                    continue

                ano_texto = linha.get(
                    "ano",
                    ""
                ).strip()

                if ano_texto:
                    try:
                        ano = int(
                            float(
                                ano_texto
                                .replace(
                                    ",",
                                    "."
                                )
                            )
                        )
                    except Exception:
                        erros.append(
                            (
                                numero_linha,
                                "ano inválido"
                            )
                        )
                        continue
                else:
                    ano = None

                dificuldade_bruta = (
                    linha.get(
                        "dificuldade",
                        ""
                    ).strip()
                )

                dificuldade_normalizada = (
                    self.normalizar_texto_questoes(
                        dificuldade_bruta
                    )
                )

                mapa_dificuldade = {
                    "facil": "Fácil",
                    "media": "Média",
                    "medio": "Média",
                    "dificil": "Difícil",
                    "nao informada": "Não informada",
                    "nao informado": "Não informada",
                    "": "Não informada",
                }

                dificuldade = mapa_dificuldade.get(
                    dificuldade_normalizada,
                    dificuldade_bruta
                    or "Não informada"
                )

                chave_duplicidade = (
                    topico_id,
                    self.normalizar_texto_questoes(
                        enunciado
                    ),
                )

                if (
                    chave_duplicidade
                    in chaves_importacao
                    or questao_existe(
                        topico_id,
                        enunciado,
                        alternativas=alternativas,
                        gabarito=gabarito
                    )
                ):
                    duplicadas += 1
                    duplicadas_linhas.append((numero_linha, enunciado))
                    continue

                chaves_importacao.add(
                    chave_duplicidade
                )

                registros.append({
                    "topico_id": topico_id,
                    "enunciado": enunciado,
                    "alternativas": alternativas,
                    "explicacao": linha.get(
                        "explicacao",
                        ""
                    ),
                    "banca": linha.get(
                        "banca",
                        ""
                    ),
                    "ano": ano,
                    "fonte": linha.get(
                        "fonte",
                        ""
                    ),
                    "dificuldade": dificuldade,
                })

                linhas_validas.append({
                    "linha": numero_linha,
                    "enunciado": enunciado,
                    "gabarito": gabarito,
                    "classificacao": f"{disciplina} › {topico}",
                })

            if not registros:
                detalhes = ""

                if erros:
                    detalhes = "\n\nPrimeiros problemas:\n" + "\n".join(
                        (
                            f"Linha {numero}: {motivo}"
                        )
                        for numero, motivo
                        in erros[
                            :10
                        ]
                    )

                QMessageBox.information(
                    self,
                    "Importar questões",
                    (
                        "Nenhuma questão válida foi encontrada para importar."
                        f"\nDuplicadas ignoradas: {duplicadas}"
                        f"\nLinhas com erro: {len(erros)}"
                        f"{detalhes}"
                    )
                )
                return

            revisao_csv = JanelaValidacaoCSVQuestoes(
                Path(caminho).name,
                linhas_validas,
                erros,
                duplicadas_linhas,
                self,
            )

            if revisao_csv.exec() != QDialog.Accepted:
                return

            try:
                fazer_backup(
                    "antes_importar_questoes"
                )
            except Exception as erro:
                QMessageBox.critical(
                    self,
                    "Importar questões",
                    (
                        "A importação foi cancelada porque o backup "
                        "de segurança não pôde ser criado.\n\n"
                        f"{erro}"
                    )
                )
                return

            criar_questoes_lote(
                registros
            )

            self.carregar_questoes()

            detalhes = ""

            if erros:
                detalhes = "\n\nPrimeiros problemas ignorados:\n" + "\n".join(
                    (
                        f"Linha {numero}: {motivo}"
                    )
                    for numero, motivo
                    in erros[
                        :10
                    ]
                )

            QMessageBox.information(
                self,
                "Importação concluída",
                (
                    f"Importadas: {len(registros)}\n"
                    f"Duplicadas ignoradas: {duplicadas}\n"
                    f"Linhas com erro: {len(erros)}"
                    f"{detalhes}"
                )
            )

        except Exception as erro:
            QMessageBox.critical(
                self,
                "Importar questões",
                (
                    "Não foi possível importar o arquivo.\n\n"
                    f"{erro}"
                )
            )

