    def _atualizar_aba_relatorios(self, aba, contexto):
        inicio_medicao = time.perf_counter()
        concurso_id = contexto["concurso"][0]
        inicio = contexto["inicio"]
        fim = contexto["fim"]

        if aba == "Estratégico":
            dados = obter_relatorio_estrategico(inicio, fim, concurso_id)
            self.dados_relatorio_estrategico = dados
            self.atualizar_relatorio_estrategico(dados)
        elif aba == "Por disciplina":
            dados = obter_relatorio_disciplinas_periodo(inicio, fim, concurso_id)
            self.dados_relatorio_disciplinas = dados
            self._preencher_relatorio_disciplinas(dados)
        elif aba == "Por tópico":
            dados = obter_relatorio_topicos_periodo(inicio, fim, concurso_id)
            self.dados_relatorio_topicos = dados
            self._preencher_relatorio_topicos(dados)
        elif aba == "Por dia":
            dados = obter_relatorio_diario_periodo(inicio, fim, concurso_id)
            self.dados_relatorio_diario = dados
            self._preencher_relatorio_diario(dados)
        else:
            return

        self._estado_relatorios.marcar_limpa(aba)
        self._estado_relatorios.registrar_duracao(
            aba, (time.perf_counter() - inicio_medicao) * 1000.0
        )

    def atualizar_relatorios(self, forcar=False):
        """Atualiza o resumo e somente a aba de Relatórios atualmente visível."""
        if self._relatorios_refresh_em_andamento:
            return

        contexto = self._obter_contexto_relatorios()
        if contexto is None:
            QMessageBox.warning(
                self,
                "Período inválido",
                "A data inicial não pode ser posterior à data final.",
            )
            return

        self._relatorios_refresh_em_andamento = True
        try:
            concurso = contexto["concurso"]
            trocou_contexto = self._estado_relatorios.trocar_contexto(
                concurso[0], contexto["inicio"], contexto["fim"]
            )
            if trocou_contexto:
                self._limpar_cache_dados_relatorios()

            if forcar:
                self._estado_relatorios.marcar_sujas()
                self._limpar_cache_dados_relatorios()

            if self._estado_relatorios.resumo_sujo:
                self._atualizar_resumo_relatorios(contexto)

            indice = self.abas_relatorios.currentIndex()
            aba = self.abas_relatorios.tabText(indice) if indice >= 0 else "Estratégico"
            if forcar or self._estado_relatorios.precisa_atualizar(aba):
                self._atualizar_aba_relatorios(aba, contexto)
        finally:
            self._relatorios_refresh_em_andamento = False

    def _garantir_dados_relatorio_exportacao(self):
        """Carrega dados faltantes para CSV sem montar abas invisíveis."""
        contexto = self._obter_contexto_relatorios()
        if contexto is None:
            raise ValueError("Período inválido para exportação.")

        concurso = contexto["concurso"]
        trocou_contexto = self._estado_relatorios.trocar_contexto(
            concurso[0], contexto["inicio"], contexto["fim"]
        )
        if trocou_contexto:
            self._limpar_cache_dados_relatorios()

        if self.dados_relatorio_resumo is None or self.dados_relatorio_comparacao is None:
            self._atualizar_resumo_relatorios(contexto)
        if self.dados_relatorio_estrategico is None:
            self.dados_relatorio_estrategico = obter_relatorio_estrategico(
                contexto["inicio"], contexto["fim"], concurso[0]
            )
        if self.dados_relatorio_disciplinas is None:
            self.dados_relatorio_disciplinas = obter_relatorio_disciplinas_periodo(
                contexto["inicio"], contexto["fim"], concurso[0]
            )
        if self.dados_relatorio_topicos is None:
            self.dados_relatorio_topicos = obter_relatorio_topicos_periodo(
                contexto["inicio"], contexto["fim"], concurso[0]
            )
        if self.dados_relatorio_diario is None:
            self.dados_relatorio_diario = obter_relatorio_diario_periodo(
                contexto["inicio"], contexto["fim"], concurso[0]
            )


    def atualizar_relatorio_estrategico(
        self,
        dados
    ):
        dados = dados or {}
        situacao = dados.get(
            "situacao",
            {}
        )
        evolucao = dados.get(
            "evolucao",
            {}
        )
        periodo = dados.get(
            "periodo",
            {}
        )

        def percentual(valor):
            if valor is None:
                return "—"
            return (
                f"{float(valor):.1f}%"
                .replace(".", ",")
            )

        def pontos(valor):
            if valor is None:
                return "—"
            valor = float(valor)
            if abs(valor) < 0.05:
                return "Estável"
            seta = "▲" if valor > 0 else "▼"
            sinal = "+" if valor > 0 else ""
            return (
                f"{seta} {sinal}{valor:.1f} p.p."
                .replace(".", ",")
            )

        preparacao = situacao.get(
            "preparacao",
            "Evidência insuficiente"
        )
        self.rel_estrategico_preparacao.setText(
            preparacao
        )
        estado_preparacao = {
            "Atenção": "attention",
            "Em construção": "building",
            "Boa": "good",
            "Forte": "strong",
            "Evidência insuficiente": "insufficient",
        }.get(preparacao, "insufficient")
        self.rel_estrategico_preparacao.setProperty(
            "prepState",
            estado_preparacao
        )
        self.rel_estrategico_preparacao.style().unpolish(
            self.rel_estrategico_preparacao
        )
        self.rel_estrategico_preparacao.style().polish(
            self.rel_estrategico_preparacao
        )

        criticas = int(
            situacao.get("criticas_abertas") or 0
        )
        recorrentes = int(
            situacao.get("recorrentes_abertas") or 0
        )
        self.rel_estrategico_preparacao_detalhe.setText(
            (
                f"{criticas} críticas • {recorrentes} recorrentes abertas"
                if (criticas or recorrentes)
                else "classificação baseada em evidências atuais"
            )
        )

        dominio = situacao.get(
            "dominio_medio"
        )
        self.rel_estrategico_dominio.setText(
            "—"
            if dominio is None
            else f"{float(dominio):.0f} / 100"
        )
        self.rel_estrategico_dominio_detalhe.setText(
            (
                f"{situacao.get('topicos_com_evidencia', 0)} tópicos com evidência"
            )
        )

        desempenho = situacao.get(
            "desempenho"
        )
        self.rel_estrategico_desempenho.setText(
            percentual(desempenho)
        )
        self.rel_estrategico_desempenho_detalhe.setText(
            (
                f"{int(situacao.get('questoes') or 0)} questões • "
                f"{int(situacao.get('dias_ativos') or 0)} dias ativos"
            )
        )

        cobertura = float(
            situacao.get("cobertura_evidencia") or 0.0
        )
        self.rel_estrategico_cobertura.setText(
            percentual(cobertura)
        )
        self.rel_estrategico_cobertura_detalhe.setText(
            (
                f"{int(situacao.get('topicos_com_evidencia') or 0)} de "
                f"{int(situacao.get('total_topicos') or 0)} tópicos"
            )
        )

        try:
            inicio_anterior = datetime.strptime(
                periodo.get("inicio_anterior", ""),
                "%Y-%m-%d"
            ).strftime("%d/%m/%Y")
            fim_anterior = datetime.strptime(
                periodo.get("fim_anterior", ""),
                "%Y-%m-%d"
            ).strftime("%d/%m/%Y")
            texto_periodo = (
                f"Comparado com {inicio_anterior} → {fim_anterior}"
            )
        except (TypeError, ValueError):
            texto_periodo = "Período anterior equivalente"

        self.rel_estrategico_periodo_anterior.setText(
            texto_periodo
        )

        self.rel_estrategico_delta_desempenho.setText(
            pontos(
                evolucao.get("desempenho_delta")
            )
        )
        self.rel_estrategico_delta_desempenho.setProperty(
            "trend",
            (
                "positive"
                if (evolucao.get("desempenho_delta") or 0) > 0.05
                else "negative"
                if (evolucao.get("desempenho_delta") or 0) < -0.05
                else "neutral"
            )
        )
        self.rel_estrategico_delta_desempenho.style().unpolish(
            self.rel_estrategico_delta_desempenho
        )
        self.rel_estrategico_delta_desempenho.style().polish(
            self.rel_estrategico_delta_desempenho
        )

        delta_volume = int(
            evolucao.get("questoes_delta") or 0
        )
        anterior_resumo = evolucao.get(
            "resumo_anterior",
            {}
        )
        if delta_volume > 0:
            texto_volume = f"▲ +{delta_volume}"
        elif delta_volume < 0:
            texto_volume = f"▼ {delta_volume}"
        else:
            texto_volume = "Estável"
        texto_volume += (
            f" • anterior {int(anterior_resumo.get('questoes') or 0)}"
        )
        self.rel_estrategico_delta_volume.setText(
            texto_volume
        )

        maior = evolucao.get(
            "maior_evolucao"
        )
        queda = evolucao.get(
            "maior_queda"
        )

        self.rel_estrategico_maior_evolucao.setText(
            (
                "Sem base comparável"
                if not maior
                else (
                    f"{maior.get('disciplina', '—')} • "
                    f"{pontos(maior.get('variacao'))}"
                )
            )
        )
        self.rel_estrategico_maior_queda.setText(
            (
                "Sem base comparável"
                if not queda
                else (
                    f"{queda.get('disciplina', '—')} • "
                    f"{pontos(queda.get('variacao'))}"
                )
            )
        )

        riscos = list(
            dados.get("riscos") or []
        )
        for indice, label in enumerate(
            self.rel_estrategico_riscos
        ):
            if indice >= len(riscos):
                label.setVisible(False)
                continue
            item = riscos[indice]
            label.setVisible(True)
            nivel = item.get("nivel", "medio")
            label.setProperty(
                "riskLevel",
                nivel
            )
            label.setText(
                (
                    f"<b>{item.get('titulo', 'Atenção')}</b><br>"
                    f"{item.get('detalhe', '')}"
                )
            )
            label.style().unpolish(label)
            label.style().polish(label)

        acoes = list(
            dados.get("acoes") or []
        )
        for indice, label in enumerate(
            self.rel_estrategico_acoes
        ):
            if indice >= len(acoes):
                label.setVisible(False)
                continue
            item = acoes[indice]
            label.setVisible(True)
            label.setText(
                (
                    f"<b>{indice + 1}. {item.get('titulo', 'Próxima ação')}</b><br>"
                    f"{item.get('detalhe', '')}<br>"
                    f"<i>→ {item.get('acao', '')}</i>"
                )
            )

        disciplinas = list(
            dados.get("disciplinas") or []
        )
        self.rel_estrategico_contagem_disciplinas.setText(
            (
                f"{len(disciplinas)} disciplina"
                if len(disciplinas) == 1
                else f"{len(disciplinas)} disciplinas"
            )
        )

        tabela = self.tabela_relatorio_estrategico_disciplinas
        tabela.setUpdatesEnabled(False)
        tabela.blockSignals(True)
        try:
            tabela.setRowCount(len(disciplinas))

            for linha, item in enumerate(disciplinas):
                dominio_item = item.get("dominio")
                desempenho_item = item.get("desempenho")
                cobertura_item = item.get("cobertura_evidencia")
                variacao_item = item.get("variacao")

                valores = [
                    item.get("disciplina") or "—",
                    item.get("preparacao") or "—",
                    "—" if dominio_item is None else f"{float(dominio_item):.0f}/100",
                    percentual(desempenho_item),
                    percentual(cobertura_item),
                    pontos(variacao_item),
                ]

                for coluna, valor in enumerate(valores):
                    celula = QTableWidgetItem(str(valor))
                    if coluna == 0:
                        celula.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)
                    else:
                        celula.setTextAlignment(Qt.AlignCenter)

                    if coluna == 1:
                        estado = item.get("preparacao")
                        if estado == "Atenção":
                            aplicar_destaque_tabela(celula, "perigo", True)
                        elif estado == "Em construção":
                            aplicar_destaque_tabela(celula, "alerta", True)
                        elif estado == "Forte":
                            aplicar_destaque_tabela(celula, "sucesso", True)

                    tabela.setItem(linha, coluna, celula)

                tabela.setRowHeight(linha, 31)
        finally:
            tabela.blockSignals(False)
            tabela.setUpdatesEnabled(True)


    def abrir_topico_relatorio(
        self,
        linha,
        coluna
    ):
        item = self.tabela_relatorio_topicos.item(
            linha,
            1
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )

        janela = JanelaTopico(
            topico_id,
            item.text(),
            self
        )

        janela.exec()

        self.invalidar_relatorios(atualizar_se_visivel=True)

    def exportar_relatorio_csv(self):
        try:
            self._garantir_dados_relatorio_exportacao()
        except Exception as erro:
            QMessageBox.warning(
                self,
                "Relatório indisponível",
                f"Não foi possível preparar os dados para exportação.\n\n{erro}",
            )
            return

        concurso = obter_concurso_ativo()

        inicio_q = (
            self.data_inicio_relatorio.date()
        )
        fim_q = (
            self.data_fim_relatorio.date()
        )

        nome_padrao = (
            "relatorio_estudos_"
            f"{inicio_q.toString('yyyy-MM-dd')}_"
            f"{fim_q.toString('yyyy-MM-dd')}.csv"
        )

        caminho, _ = QFileDialog.getSaveFileName(
            self,
            "Exportar relatório CSV",
            str(
                Path.home()
                / nome_padrao
            ),
            "Arquivo CSV (*.csv)"
        )

        if not caminho:
            return

        if not caminho.lower().endswith(
            ".csv"
        ):
            caminho += ".csv"

        try:
            with open(
                caminho,
                "w",
                newline="",
                encoding="utf-8-sig"
            ) as arquivo:
                escritor = csv.writer(
                    arquivo,
                    delimiter=";"
                )

                resumo = (
                    self.dados_relatorio_resumo
                )

                escritor.writerow([
                    "RELATÓRIO DE ESTUDOS"
                ])
                escritor.writerow([
                    "Perfil",
                    concurso[1]
                ])
                escritor.writerow([
                    "Início",
                    inicio_q.toString(
                        "dd/MM/yyyy"
                    )
                ])
                escritor.writerow([
                    "Fim",
                    fim_q.toString(
                        "dd/MM/yyyy"
                    )
                ])
                escritor.writerow([])
                escritor.writerow([
                    "Revisões",
                    resumo["revisoes"]
                ])
                escritor.writerow([
                    "Questões",
                    resumo["questoes"]
                ])
                escritor.writerow([
                    "Acertos",
                    resumo["acertos"]
                ])
                escritor.writerow([
                    "Desempenho",
                    (
                        ""
                        if resumo[
                            "percentual"
                        ] is None
                        else str(
                            resumo[
                                "percentual"
                            ]
                        ).replace(
                            ".",
                            ","
                        )
                        + "%"
                    )
                ])
                escritor.writerow([
                    "Tópicos estudados",
                    resumo["topicos"]
                ])
                escritor.writerow([
                    "Disciplinas estudadas",
                    resumo["disciplinas"]
                ])

                estrategico = (
                    self.dados_relatorio_estrategico
                    or {}
                )
                situacao_estrategica = estrategico.get(
                    "situacao",
                    {}
                )

                escritor.writerow([])
                escritor.writerow([
                    "RELATÓRIO ESTRATÉGICO"
                ])
                escritor.writerow([
                    "Estado de preparação",
                    situacao_estrategica.get(
                        "preparacao",
                        "—"
                    )
                ])
                escritor.writerow([
                    "Domínio médio",
                    (
                        ""
                        if situacao_estrategica.get("dominio_medio") is None
                        else str(
                            round(
                                float(situacao_estrategica.get("dominio_medio")),
                                1
                            )
                        ).replace(".", ",")
                        + "/100"
                    )
                ])
                escritor.writerow([
                    "Desempenho interno no período",
                    (
                        ""
                        if situacao_estrategica.get("desempenho") is None
                        else str(
                            round(
                                float(situacao_estrategica.get("desempenho")),
                                1
                            )
                        ).replace(".", ",")
                        + "%"
                    )
                ])
                escritor.writerow([
                    "Cobertura com evidência",
                    str(
                        round(
                            float(
                                situacao_estrategica.get(
                                    "cobertura_evidencia"
                                )
                                or 0.0
                            ),
                            1
                        )
                    ).replace(".", ",")
                    + "%"
                ])

                escritor.writerow([])
                escritor.writerow([
                    "RISCOS"
                ])
                escritor.writerow([
                    "Nível",
                    "Risco",
                    "Detalhe"
                ])
                for item in estrategico.get("riscos") or []:
                    escritor.writerow([
                        item.get("nivel", ""),
                        item.get("titulo", ""),
                        item.get("detalhe", ""),
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "PRÓXIMAS AÇÕES"
                ])
                escritor.writerow([
                    "Prioridade",
                    "Recomendação",
                    "Motivo",
                    "Ação"
                ])
                for ordem, item in enumerate(
                    estrategico.get("acoes") or [],
                    1
                ):
                    escritor.writerow([
                        ordem,
                        item.get("titulo", ""),
                        item.get("detalhe", ""),
                        item.get("acao", ""),
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "PREPARAÇÃO POR DISCIPLINA"
                ])
                escritor.writerow([
                    "Disciplina",
                    "Preparação",
                    "Domínio",
                    "Desempenho",
                    "Cobertura com evidência",
                    "Variação"
                ])
                for item in estrategico.get("disciplinas") or []:
                    escritor.writerow([
                        item.get("disciplina", ""),
                        item.get("preparacao", ""),
                        (
                            ""
                            if item.get("dominio") is None
                            else str(round(float(item.get("dominio")), 1)).replace(".", ",")
                            + "/100"
                        ),
                        (
                            ""
                            if item.get("desempenho") is None
                            else str(round(float(item.get("desempenho")), 1)).replace(".", ",")
                            + "%"
                        ),
                        str(round(float(item.get("cobertura_evidencia") or 0.0), 1)).replace(".", ",") + "%",
                        (
                            ""
                            if item.get("variacao") is None
                            else str(round(float(item.get("variacao")), 1)).replace(".", ",")
                            + " p.p."
                        ),
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "POR DISCIPLINA"
                ])
                escritor.writerow([
                    "Disciplina",
                    "Revisões",
                    "Questões",
                    "Acertos",
                    "Desempenho",
                    "Tópicos"
                ])

                for dado in self.dados_relatorio_disciplinas:
                    escritor.writerow([
                        dado[0],
                        dado[1],
                        dado[2],
                        dado[3],
                        (
                            ""
                            if dado[4] is None
                            else str(
                                dado[4]
                            ).replace(
                                ".",
                                ","
                            )
                            + "%"
                        ),
                        dado[5]
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "POR TÓPICO"
                ])
                escritor.writerow([
                    "Disciplina",
                    "Tópico",
                    "Revisões",
                    "Questões",
                    "Acertos",
                    "Desempenho",
                    "Primeira no período",
                    "Última no período"
                ])

                for dado in self.dados_relatorio_topicos:
                    escritor.writerow([
                        dado[1],
                        dado[2],
                        dado[3],
                        dado[4],
                        dado[5],
                        (
                            ""
                            if dado[6] is None
                            else str(
                                dado[6]
                            ).replace(
                                ".",
                                ","
                            )
                            + "%"
                        ),
                        formatar_data(
                            dado[7]
                        ),
                        formatar_data(
                            dado[8]
                        )
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "POR DIA"
                ])
                escritor.writerow([
                    "Data",
                    "Revisões",
                    "Questões",
                    "Acertos",
                    "Desempenho"
                ])

                for dado in self.dados_relatorio_diario:
                    escritor.writerow([
                        formatar_data(
                            dado[0]
                        ),
                        dado[1],
                        dado[2],
                        dado[3],
                        (
                            ""
                            if dado[4] is None
                            else str(
                                dado[4]
                            ).replace(
                                ".",
                                ","
                            )
                            + "%"
                        )
                    ])

            QMessageBox.information(
                self,
                "Relatório exportado",
                (
                    "Arquivo CSV criado com sucesso:\n\n"
                    f"{caminho}"
                )
            )

        except Exception as erro:
            QMessageBox.critical(
                self,
                "Falha ao exportar",
                (
                    "Não foi possível criar o CSV.\n\n"
                    f"{erro}"
                )
            )

    def criar_aba_laboratorio_algoritmo(self):
        aba = QWidget()
        aba_raiz = QVBoxLayout(aba)
        aba_raiz.setContentsMargins(0, 0, 0, 0)
        aba_raiz.setSpacing(0)

        # O Laboratório possui vários blocos verticais. Em resoluções menores
        # ele não deve cortar a parte inferior: toda a aba passa a ser rolável.
        scroll = QScrollArea()
        scroll.setObjectName("algorithmLabScroll")
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)

        conteudo = QWidget()
        conteudo.setObjectName("algorithmLabContent")
        raiz = QVBoxLayout(conteudo)
        raiz.setContentsMargins(12, 12, 12, 12)
        raiz.setSpacing(10)

        topo = QFrame()
        topo.setObjectName("myEvolutionPanel")
        tl = QVBoxLayout(topo)
        tl.setContentsMargins(14, 12, 14, 12)
        tl.setSpacing(8)
        titulo = QLabel("Laboratório do Algoritmo")
        titulo.setObjectName("myEvolutionSectionTitle")
        desc = QLabel("Simule o Motor V5 sem alterar o comportamento real. Aplicar configuração é uma ação separada.")
        desc.setObjectName("mutedLabel")
        desc.setWordWrap(True)
        tl.addWidget(titulo)
        tl.addWidget(desc)

        pesos_linha = QHBoxLayout()
        pesos_linha.setSpacing(8)
        self.lab_peso_urgencia = QSpinBox(); self.lab_peso_urgencia.setRange(0, 100)
        self.lab_peso_necessidade = QSpinBox(); self.lab_peso_necessidade.setRange(0, 100)
        self.lab_peso_momento = QSpinBox(); self.lab_peso_momento.setRange(0, 100)
        config = carregar_configuracao_motor_v5()
        self.lab_peso_urgencia.setValue(round(config["pesos"]["urgencia"]))
        self.lab_peso_necessidade.setValue(round(config["pesos"]["necessidade"]))
        self.lab_peso_momento.setValue(round(config["pesos"]["momento"]))
        for texto, widget in (("Urgência", self.lab_peso_urgencia), ("Necessidade", self.lab_peso_necessidade), ("Momento", self.lab_peso_momento)):
            bloco = QVBoxLayout(); rot = QLabel(texto); rot.setObjectName("myEvolutionStatLabel")
            widget.setSuffix("%")
            bloco.addWidget(rot); bloco.addWidget(widget); pesos_linha.addLayout(bloco)
        self.lab_proteger = QCheckBox("Proteger revisões vencidas e previstas para hoje")
        self.lab_proteger.setChecked(bool(config["proteger_revisoes_vencidas"]))
        pesos_linha.addWidget(self.lab_proteger, 1, Qt.AlignBottom)
        tl.addLayout(pesos_linha)

        acoes = QHBoxLayout()
        self.lab_pesos_info = QLabel("")
        self.lab_pesos_info.setObjectName("mutedLabel")
        acoes.addWidget(self.lab_pesos_info, 1)
        simular = QPushButton("Simular resultado"); simular.setObjectName("toolbarButton"); simular.clicked.connect(self.atualizar_laboratorio_algoritmo)
        aplicar = QPushButton("Aplicar configuração"); aplicar.setObjectName("studyManualButton"); aplicar.clicked.connect(self.aplicar_configuracao_laboratorio)
        padrao = QPushButton("Restaurar padrão"); padrao.setObjectName("subtleButton"); padrao.clicked.connect(self.restaurar_padrao_laboratorio)
        acoes.addWidget(simular); acoes.addWidget(aplicar); acoes.addWidget(padrao)
        tl.addLayout(acoes)
        raiz.addWidget(topo)

        cards = QGridLayout(); cards.setHorizontalSpacing(8)
        def mini(rotulo):
            f=QFrame(); f.setObjectName("myEvolutionStatCard"); l=QVBoxLayout(f); l.setContentsMargins(11,8,11,8); l.setSpacing(2)
            r=QLabel(rotulo); r.setObjectName("myEvolutionStatLabel"); v=QLabel("—"); v.setObjectName("myEvolutionStatValue")
            l.addWidget(r); l.addWidget(v); return f,v
        for col,(rot,attr) in enumerate((("Score escolhido","lab_score"),("Urgência","lab_urgencia"),("Necessidade","lab_necessidade"),("Momento","lab_momento"))):
            f,v=mini(rot); setattr(self,attr,v); cards.addWidget(f,0,col); cards.setColumnStretch(col,1)
        raiz.addLayout(cards)

        leitura = QFrame(); leitura.setObjectName("myEvolutionPanel"); ll=QVBoxLayout(leitura); ll.setContentsMargins(14,10,14,12); ll.setSpacing(5)
        self.lab_escolhido = QLabel("Aguardando simulação"); self.lab_escolhido.setObjectName("myEvolutionInsightValue"); self.lab_escolhido.setWordWrap(True)
        self.lab_criterio = QLabel("—"); self.lab_criterio.setObjectName("mutedLabel"); self.lab_criterio.setWordWrap(True)
        self.lab_comparacao = QLabel("—"); self.lab_comparacao.setObjectName("myEvolutionInsightDetail"); self.lab_comparacao.setWordWrap(True)
        ll.addWidget(self.lab_escolhido); ll.addWidget(self.lab_criterio); ll.addWidget(self.lab_comparacao)
        raiz.addWidget(leitura)

        self.lab_tabela = QTableWidget(); self.lab_tabela.setObjectName("myEvolutionTable")
        self.lab_tabela.setColumnCount(8); self.lab_tabela.setHorizontalHeaderLabels(["#","Disciplina","Tópico","Urgência","Necessidade","Momento","Score","Faixa"])
        self.lab_tabela.setEditTriggers(QAbstractItemView.NoEditTriggers); self.lab_tabela.setSelectionBehavior(QAbstractItemView.SelectRows); self.lab_tabela.setSelectionMode(QAbstractItemView.SingleSelection)
        self.lab_tabela.setAlternatingRowColors(True); self.lab_tabela.setShowGrid(False); self.lab_tabela.verticalHeader().setVisible(False)
        h=self.lab_tabela.horizontalHeader(); h.setSectionResizeMode(0,QHeaderView.ResizeToContents); h.setSectionResizeMode(1,QHeaderView.ResizeToContents); h.setSectionResizeMode(2,QHeaderView.Stretch)
        for c in range(3,8): h.setSectionResizeMode(c,QHeaderView.ResizeToContents)
        self.lab_tabela.itemSelectionChanged.connect(self.selecionar_linha_laboratorio)
        self.lab_tabela.setMinimumHeight(270)
        self.lab_tabela.setMaximumHeight(360)
        raiz.addWidget(self.lab_tabela)

        busca = QFrame(); busca.setObjectName("myEvolutionPanel"); bl=QHBoxLayout(busca); bl.setContentsMargins(12,8,12,8); bl.setSpacing(8)
        rot=QLabel("Por que não apareceu?"); rot.setObjectName("myEvolutionSectionTitle")
        self.lab_busca = QLineEdit(); self.lab_busca.setPlaceholderText("Digite disciplina ou tópico")
        bot=QPushButton("Explicar"); bot.setObjectName("subtleButton"); bot.clicked.connect(self.explicar_busca_laboratorio)
        self.lab_explicacao = QLabel("Simule primeiro e depois pesquise um conteúdo."); self.lab_explicacao.setObjectName("mutedLabel"); self.lab_explicacao.setWordWrap(True)
        bl.addWidget(rot); bl.addWidget(self.lab_busca,1); bl.addWidget(bot); bl.addWidget(self.lab_explicacao,2)
        raiz.addWidget(busca)
        self.lab_relatorio = None
        self.atualizar_rotulo_pesos_laboratorio()
        for w in (self.lab_peso_urgencia,self.lab_peso_necessidade,self.lab_peso_momento): w.valueChanged.connect(self.atualizar_rotulo_pesos_laboratorio)
        raiz.addStretch()
        scroll.setWidget(conteudo)
        aba_raiz.addWidget(scroll)
        return aba

    def pesos_laboratorio_algoritmo(self):
        return {"urgencia": self.lab_peso_urgencia.value(), "necessidade": self.lab_peso_necessidade.value(), "momento": self.lab_peso_momento.value()}

    def atualizar_rotulo_pesos_laboratorio(self, *args):
        if not hasattr(self,"lab_pesos_info"): return
        total=sum(self.pesos_laboratorio_algoritmo().values())
        self.lab_pesos_info.setText(f"Pesos informados: {total}% • a simulação normaliza automaticamente para 100%")

    def atualizar_laboratorio_algoritmo(self, *args):
        if not hasattr(self,"lab_tabela"): return
        try:
            d=self._dados_motor_v5(self.pesos_laboratorio_algoritmo(), self.lab_proteger.isChecked())
            rel=montar_laboratorio(fila=d["fila"],adaptativas=d["adaptativas"],contexto=d["contexto"],calibracao=d["calibracao"],perfil_decisoes=d["perfil_decisoes"],hoje=QDate.currentDate().toString("yyyy-MM-dd"),pesos=d["pesos"],proteger_revisoes_vencidas=d["proteger"],usar_calibracao=d["usar_calibracao"],usar_historico_decisoes=d["usar_decisoes"])
        except Exception as erro:
            self.lab_escolhido.setText("Falha na simulação"); self.lab_criterio.setText(str(erro)); return
        self.lab_relatorio=rel
        rec=rel.get("recomendacao") or {}; e=rec.get("eixos_v5") or {}
        self.lab_score.setText(f"{float(rec.get('score_total') or 0):.1f}"); self.lab_urgencia.setText(f"{float(e.get('urgencia') or 0):.0f}/100"); self.lab_necessidade.setText(f"{float(e.get('necessidade') or 0):.0f}/100"); self.lab_momento.setText(f"{float(e.get('momento') or 0):.0f}/100")
        self.lab_escolhido.setText(f"{rec.get('disciplina') or 'Estudo livre'} › {rec.get('topico') or 'Sem tópico específico'}")
        self.lab_criterio.setText(str(rec.get("criterio_selecao_v5") or "—")); self.lab_comparacao.setText(str(rel.get("comparacao") or "—"))
        ranking=list(rel.get("ranking") or []); self.lab_tabela.setRowCount(len(ranking))
        for r,item in enumerate(ranking):
            vals=[str(r+1),str(item.get("disciplina") or "—"),str(item.get("topico") or "—"),f"{float(item.get('urgencia') or 0):.0f}",f"{float(item.get('necessidade') or 0):.0f}",f"{float(item.get('momento') or 0):.0f}",f"{float(item.get('score_total') or 0):.1f}","Protegida" if item.get("faixa_temporal_protegida") else "Flexível"]
            for c,v in enumerate(vals): self.lab_tabela.setItem(r,c,QTableWidgetItem(v))
            self.lab_tabela.setRowHeight(r,30)

    def aplicar_configuracao_laboratorio(self):
        salvar_configuracao_motor_v5(self.pesos_laboratorio_algoritmo(), self.lab_proteger.isChecked())
        self.cache_analitico.invalidar(); self.atualizar_dashboard(); self.atualizar_laboratorio_algoritmo()
        QMessageBox.information(self,"Motor V5","Configuração aplicada. As próximas recomendações usarão estes pesos.")

    def restaurar_padrao_laboratorio(self):
        config=restaurar_padrao_motor_v5(); self.lab_peso_urgencia.setValue(round(config["pesos"]["urgencia"])); self.lab_peso_necessidade.setValue(round(config["pesos"]["necessidade"])); self.lab_peso_momento.setValue(round(config["pesos"]["momento"])); self.lab_proteger.setChecked(True)
        self.cache_analitico.invalidar(); self.atualizar_dashboard(); self.atualizar_laboratorio_algoritmo()

    def explicar_busca_laboratorio(self):
        if not self.lab_relatorio: self.atualizar_laboratorio_algoritmo()
        self.lab_explicacao.setText(explicar_topico_laboratorio(self.lab_relatorio or {}, self.lab_busca.text()))

    def selecionar_linha_laboratorio(self):
        linha=self.lab_tabela.currentRow()
        ranking=list((self.lab_relatorio or {}).get("ranking") or [])
        if 0 <= linha < len(ranking):
            item=ranking[linha]; self.lab_explicacao.setText(explicar_topico_laboratorio(self.lab_relatorio, str(item.get("topico") or item.get("disciplina") or "")))

