    def atualizar_previsao_edital(self):
        if not hasattr(
            self,
            "previsao_cobertura_valor"
        ):
            return

        concurso_id = (
            obter_concurso_ativo()[0]
        )

        resultado = self.calcular_previsao_edital(
            concurso_id
        )

        total = resultado[
            "total"
        ]
        trabalhados = resultado[
            "trabalhados"
        ]
        consolidados = resultado[
            "consolidados"
        ]

        cobertura = resultado[
            "cobertura_percentual"
        ]
        consolidacao = resultado[
            "consolidacao_percentual"
        ]

        self.previsao_cobertura_valor.setText(
            (
                f"{trabalhados} / {total} "
                f"• {cobertura:.0f}%"
            )
            if total > 0
            else "0 / 0"
        )
        self.previsao_cobertura_barra.setValue(
            int(
                round(
                    cobertura
                )
            )
        )

        self.previsao_cobertura_ritmo.setText(
            (
                "Ritmo recente: "
                f"{resultado['ritmo_inicio']:.2f} "
                "novo(s) tópico(s)/semana "
                f"• {resultado['eventos_inicio']} evento(s)"
            )
        )

        self.previsao_cobertura_data.setText(
            self.formatar_previsao_data(
                resultado[
                    "previsao_cobertura"
                ],
                "100% iniciado: "
            )
        )

        if resultado[
            "nao_iniciados"
        ] <= 0:
            self.previsao_cobertura_necessario.setText(
                "Para 30 dias: cobertura já completa"
            )
            status_cobertura = (
                "Cobertura concluída",
                "boa"
            )
        else:
            necessario = resultado[
                "ritmo_necessario_30"
            ]

            self.previsao_cobertura_necessario.setText(
                (
                    "Para terminar em 30 dias: "
                    f"{necessario:.2f} tópico(s)/semana"
                )
            )

            ritmo = resultado[
                "ritmo_inicio"
            ]

            if ritmo <= 0:
                status_cobertura = (
                    "Sem ritmo recente para projetar",
                    "insuficiente"
                )
            elif ritmo >= necessario:
                status_cobertura = (
                    "No ritmo para 30 dias",
                    "boa"
                )
            elif ritmo >= necessario * 0.75:
                status_cobertura = (
                    "Próximo do ritmo necessário",
                    "moderada"
                )
            else:
                status_cobertura = (
                    "Abaixo do ritmo para 30 dias",
                    "limitada"
                )

        self.previsao_cobertura_status.setText(
            (
                f"{status_cobertura[0]} • "
                f"{resultado['qualidade_inicio'][0]}"
            )
        )
        self.previsao_cobertura_status.setProperty(
            "forecastState",
            status_cobertura[
                1
            ]
        )
        self.previsao_cobertura_status.style().unpolish(
            self.previsao_cobertura_status
        )
        self.previsao_cobertura_status.style().polish(
            self.previsao_cobertura_status
        )

        self.previsao_consolidacao_valor.setText(
            (
                f"{consolidados} / {total} "
                f"• {consolidacao:.0f}%"
            )
            if total > 0
            else "0 / 0"
        )
        self.previsao_consolidacao_barra.setValue(
            int(
                round(
                    consolidacao
                )
            )
        )

        self.previsao_consolidacao_ritmo.setText(
            (
                "Ritmo recente: "
                f"{resultado['ritmo_consolidacao']:.2f} "
                "consolidação(ões)/semana "
                f"• {resultado['eventos_consolidacao']} evento(s)"
            )
        )

        self.previsao_consolidacao_80.setText(
            self.formatar_previsao_data(
                resultado[
                    "previsao_consolidacao_80"
                ],
                "80% consolidado: "
            )
        )

        self.previsao_consolidacao_100.setText(
            self.formatar_previsao_data(
                resultado[
                    "previsao_consolidacao_100"
                ],
                "100% consolidado: "
            )
        )

        self.previsao_consolidacao_base.setText(
            (
                f"{resultado['qualidade_consolidacao'][0]} "
                f"na janela de {resultado['semanas']} semanas"
            )
        )
        self.previsao_consolidacao_base.setProperty(
            "forecastState",
            resultado[
                "qualidade_consolidacao"
            ][
                1
            ]
        )
        self.previsao_consolidacao_base.style().unpolish(
            self.previsao_consolidacao_base
        )
        self.previsao_consolidacao_base.style().polish(
            self.previsao_consolidacao_base
        )

        self.previsao_base_eventos.setText(
            (
                f"Janela: "
                f"{resultado['inicio_janela'].toString('dd/MM/yyyy')} "
                f"— {resultado['hoje'].toString('dd/MM/yyyy')}"
            )
        )

        # ----------------------------------------------------
        # CENÁRIOS
        # ----------------------------------------------------

        cenarios = resultado["cenarios"]

        self.tabela_previsao_cenarios.setRowCount(
            len(
                cenarios
            )
        )

        for linha, cenario in enumerate(
            cenarios
        ):
            nome = cenario["nome"]
            ritmo_inicio = cenario["ritmo_inicio"]
            ritmo_consolidacao = cenario["ritmo_consolidacao"]
            prev_cobertura = cenario["previsao_cobertura"]
            prev_80 = cenario["previsao_consolidacao_80"]
            prev_100 = cenario["previsao_consolidacao_100"]

            def data_curta(
                previsao
            ):
                if previsao is None:
                    return "—"

                if previsao.get(
                    "atingido",
                    False
                ):
                    return "Atingido"

                return previsao[
                    "data"
                ].toString(
                    "dd/MM/yyyy"
                )

            valores = [
                nome,
                (
                    f"{ritmo_inicio:.2f}"
                    if ritmo_inicio > 0
                    else "—"
                ),
                data_curta(
                    prev_cobertura
                ),
                (
                    f"{ritmo_consolidacao:.2f}"
                    if ritmo_consolidacao > 0
                    else "—"
                ),
                data_curta(
                    prev_80
                ),
                data_curta(
                    prev_100
                ),
            ]

            for coluna, valor in enumerate(
                valores
            ):
                item = QTableWidgetItem(
                    valor
                )

                if coluna > 0:
                    item.setTextAlignment(
                        Qt.AlignCenter
                    )

                if (
                    linha == 1
                    and coluna == 0
                ):
                    aplicar_destaque_tabela(
                        item,
                        "sucesso",
                        True
                    )

                self.tabela_previsao_cenarios.setItem(
                    linha,
                    coluna,
                    item
                )

            self.tabela_previsao_cenarios.setRowHeight(
                linha,
                31
            )

    def calcular_alerta_conteudo(
        self,
        item,
        hoje_qdate=None
    ):
        if hoje_qdate is None:
            hoje_qdate = QDate.currentDate()

        revisoes = int(
            item.get(
                "revisoes",
                0
            )
            or 0
        )
        tentativas = int(
            item.get("tentativas", 0)
            or 0
        )
        iniciado = tentativas > 0
        importancia = int(
            item.get(
                "importancia",
                3
            )
            or 3
        )
        percentual = item.get(
            "percentual"
        )

        percentual_numerico = (
            float(
                percentual
            )
            if percentual is not None
            else None
        )

        ultima_texto = item.get(
            "ultima"
        )
        proxima_texto = item.get(
            "proxima"
        )

        ultima_data = (
            QDate.fromString(
                ultima_texto,
                "yyyy-MM-dd"
            )
            if ultima_texto
            else QDate()
        )
        proxima_data = (
            QDate.fromString(
                proxima_texto,
                "yyyy-MM-dd"
            )
            if proxima_texto
            else QDate()
        )

        dias_sem_revisao = None
        if ultima_data.isValid():
            dias_sem_revisao = max(
                0,
                ultima_data.daysTo(
                    hoje_qdate
                )
            )

        dias_atraso = 0
        if (
            proxima_data.isValid()
            and proxima_data < hoje_qdate
        ):
            dias_atraso = max(
                1,
                proxima_data.daysTo(
                    hoje_qdate
                )
            )

        motivos = []
        tipos = set()
        pontos = 0

        # ----------------------------------------------------
        # IMPORTANTE AINDA NÃO INICIADO
        # ----------------------------------------------------

        if (
            not iniciado
            and importancia >= 4
        ):
            tipos.add(
                "Não iniciados"
            )

            if importancia >= 5:
                pontos += 82
                motivos.append(
                    "tópico de importância máxima ainda não iniciado"
                )
            else:
                pontos += 58
                motivos.append(
                    "tópico importante ainda não iniciado"
                )

        # ----------------------------------------------------
        # REVISÃO VENCIDA
        # ----------------------------------------------------

        if dias_atraso > 0:
            tipos.add(
                "Vencidos"
            )

            pontos += min(
                55,
                18
                + dias_atraso * 3
            )

            if dias_atraso >= 14:
                tipos.add(
                    "Abandonados"
                )
                motivos.append(
                    f"revisão vencida há {dias_atraso} dias"
                )
            elif dias_atraso == 1:
                motivos.append(
                    "revisão vencida há 1 dia"
                )
            else:
                motivos.append(
                    f"revisão vencida há {dias_atraso} dias"
                )

        # ----------------------------------------------------
        # BAIXO DESEMPENHO SEM RETORNO
        # Só entra quando existe atraso ou já passou tempo
        # suficiente desde a última revisão.
        # ----------------------------------------------------

        if (
            iniciado
            and percentual_numerico is not None
            and percentual_numerico < 70.0
            and (
                dias_atraso > 0
                or (
                    dias_sem_revisao is not None
                    and dias_sem_revisao >= 14
                )
            )
        ):
            tipos.add(
                "Baixo desempenho"
            )

            deficit = max(
                0.0,
                70.0
                - percentual_numerico
            )

            pontos += min(
                38,
                18
                + int(
                    deficit * 0.8
                )
            )

            motivos.append(
                (
                    f"desempenho atual de "
                    f"{percentual_numerico:.1f}%"
                )
            )

        # ----------------------------------------------------
        # INICIADO, MAS SEM PRÓXIMA REVISÃO
        # ----------------------------------------------------

        if (
            iniciado
            and not proxima_data.isValid()
        ):
            tipos.add(
                "Abandonados"
            )

            pontos += (
                48
                if importancia >= 4
                else 32
            )

            motivos.append(
                "sem próxima revisão agendada"
            )

        # ----------------------------------------------------
        # IMPORTÂNCIA ALTA SEM CONTATO RECENTE
        # Se a revisão ainda estiver agendada no futuro, gera
        # somente um alerta leve/monitoramento.
        # ----------------------------------------------------

        if (
            iniciado
            and importancia >= 4
            and dias_sem_revisao is not None
            and dias_sem_revisao >= 30
            and dias_atraso == 0
            and proxima_data.isValid()
            and proxima_data > hoje_qdate
        ):
            pontos += (
                28
                if importancia >= 5
                else 18
            )

            motivos.append(
                (
                    f"alta importância sem revisão há "
                    f"{dias_sem_revisao} dias"
                )
            )

        # ----------------------------------------------------
        # ABANDONO REAL: muito tempo sem revisar e já deveria
        # ter voltado ao conteúdo.
        # ----------------------------------------------------

        if (
            iniciado
            and dias_sem_revisao is not None
            and dias_sem_revisao >= 45
            and (
                dias_atraso > 0
                or not proxima_data.isValid()
            )
        ):
            tipos.add(
                "Abandonados"
            )
            pontos += min(
                30,
                10
                + (
                    dias_sem_revisao
                    - 45
                )
                // 3
            )

            motivos.append(
                (
                    f"sem revisão efetiva há "
                    f"{dias_sem_revisao} dias"
                )
            )

        if not motivos:
            return None

        # Importância pesa, mas não cria alerta sozinha quando o
        # conteúdo já foi iniciado.
        if iniciado:
            if importancia >= 5:
                pontos += 12
            elif importancia == 4:
                pontos += 7

        if (
            percentual_numerico is not None
            and percentual_numerico < 50
        ):
            pontos += 10

        if pontos >= 78:
            nivel = "Crítico"
            ordem_nivel = 0
        elif pontos >= 48:
            nivel = "Atenção"
            ordem_nivel = 1
        else:
            nivel = "Monitorar"
            ordem_nivel = 2

        # Elimina motivos repetidos mantendo a ordem.
        motivos_unicos = []
        vistos = set()

        for motivo in motivos:
            if motivo in vistos:
                continue

            vistos.add(
                motivo
            )
            motivos_unicos.append(
                motivo
            )

        return {
            **item,
            "nivel_alerta": nivel,
            "ordem_alerta": ordem_nivel,
            "pontos_alerta": pontos,
            "motivo_alerta": " • ".join(
                motivos_unicos
            ),
            "tipos_alerta": tipos,
            "dias_atraso": dias_atraso,
            "dias_sem_revisao": dias_sem_revisao,
        }

    def montar_alertas_conteudo(
        self,
        concurso_id
    ):
        hoje = QDate.currentDate()

        dados = self.montar_dados_progresso_edital(
            concurso_id
        )

        alertas = []

        for item in dados:
            alerta = self.calcular_alerta_conteudo(
                item,
                hoje
            )

            if alerta is not None:
                alertas.append(
                    alerta
                )

        alertas.sort(
            key=lambda item: (
                item[
                    "ordem_alerta"
                ],
                -item[
                    "pontos_alerta"
                ],
                -item[
                    "importancia"
                ],
                -item[
                    "dias_atraso"
                ],
                (
                    item[
                        "percentual"
                    ]
                    if item[
                        "percentual"
                    ] is not None
                    else 101
                ),
                item[
                    "disciplina"
                ].lower(),
                item[
                    "topico"
                ].lower()
            )
        )

        return alertas

    def atualizar_alertas_dashboard(
        self,
        concurso_id
    ):
        if not hasattr(
            self,
            "dashboard_alertas_texto"
        ):
            return

        alertas = self.cache_analitico.obter(
            f"dashboard:alertas:{int(concurso_id)}",
            lambda: self.montar_alertas_conteudo(concurso_id),
            ttl=20,
        )

        criticos = sum(
            1
            for item in alertas
            if item[
                "nivel_alerta"
            ] == "Crítico"
        )
        atencao = sum(
            1
            for item in alertas
            if item[
                "nivel_alerta"
            ] == "Atenção"
        )
        monitorar = max(
            0,
            len(alertas)
            - criticos
            - atencao
        )

        total_alertas = len(
            alertas
        )

        if hasattr(
            self,
            "dashboard_notificacoes_subtitulo"
        ):
            if total_alertas == 0:
                resumo_notificacoes = "Nenhum alerta ativo • acompanhe o ritmo do edital"
            else:
                partes_resumo = [
                    f"{total_alertas} alerta" + ("" if total_alertas == 1 else "s")
                ]
                if criticos:
                    partes_resumo.append(
                        f"{criticos} crítico" + ("" if criticos == 1 else "s")
                    )
                if atencao:
                    partes_resumo.append(
                        f"{atencao} em atenção"
                    )
                resumo_notificacoes = " • ".join(partes_resumo)

            self.dashboard_notificacoes_subtitulo.setText(
                resumo_notificacoes
            )

        if (
            criticos > 0
            and hasattr(self, "dashboard_notificacoes_conteudo")
            and not getattr(self, "_notificacoes_criticas_autoabertas", False)
        ):
            self.definir_estado_secao_dashboard(
                "notificacoes",
                True,
                salvar=False
            )
            self._notificacoes_criticas_autoabertas = True

        if hasattr(
            self,
            "dashboard_attention_alert_count"
        ):
            self.dashboard_attention_alert_count.setText(
                (
                    "Alertas: nenhum"
                    if total_alertas == 0
                    else (
                        "Alertas: 1 ativo"
                        if total_alertas == 1
                        else f"Alertas: {total_alertas} ativos"
                    )
                )
            )

        if not alertas:
            self.dashboard_alertas_icone.setText(
                "✓"
            )
            self.dashboard_alertas_texto.setText(
                "Nenhuma prioridade crítica agora"
            )
            self.dashboard_alertas_detalhe.setText(
                "Os tópicos monitorados estão dentro das regras atuais de atenção."
            )
            self.dashboard_alertas_resumo.setText(
                "Em ordem"
            )
            self.dashboard_alertas_contagem.setText(
                "Nenhum alerta ativo no perfil"
            )
            self.dashboard_alertas_conteudo.setToolTip(
                "Nenhum tópico atingiu os critérios atuais de alerta."
            )
            self.dashboard_alertas_conteudo.setProperty(
                "alertState",
                "ok"
            )
            self.dashboard_alertas_botao.setText(
                "Sem alertas"
            )
            self.dashboard_alertas_botao.setEnabled(
                False
            )

        else:
            principal = alertas[0]
            total_alertas = len(
                alertas
            )

            disciplina = str(
                principal.get(
                    "disciplina",
                    "Conteúdo"
                )
                or "Conteúdo"
            )
            topico = str(
                principal.get(
                    "topico",
                    "Tópico"
                )
                or "Tópico"
            )
            nivel = str(
                principal.get(
                    "nivel_alerta",
                    "Monitorar"
                )
                or "Monitorar"
            )
            motivo = str(
                principal.get(
                    "motivo_alerta",
                    ""
                )
                or ""
            ).strip()

            if motivo:
                motivo_exibicao = (
                    motivo[0].upper()
                    + motivo[1:]
                )
                if not motivo_exibicao.endswith(
                    (".", "!", "?")
                ):
                    motivo_exibicao += "."
            else:
                motivo_exibicao = (
                    "Este tópico concentra o sinal de atenção "
                    "mais relevante do momento."
                )

            self.dashboard_alertas_icone.setText(
                "!"
            )
            self.dashboard_alertas_texto.setText(
                f"{disciplina} › {topico}"
            )
            self.dashboard_alertas_detalhe.setText(
                motivo_exibicao
            )
            self.dashboard_alertas_resumo.setText(
                nivel
            )

            extras = max(
                0,
                total_alertas - 1
            )
            partes_contagem = []

            if extras > 0:
                partes_contagem.append(
                    (
                        "+ 1 outro tópico na fila"
                        if extras == 1
                        else f"+ {extras} outros tópicos na fila"
                    )
                )

            if criticos:
                partes_contagem.append(
                    (
                        "1 crítico"
                        if criticos == 1
                        else f"{criticos} críticos"
                    )
                )

            if atencao:
                partes_contagem.append(
                    (
                        "1 em atenção"
                        if atencao == 1
                        else f"{atencao} em atenção"
                    )
                )

            if (
                monitorar
                and not criticos
                and not atencao
            ):
                partes_contagem.append(
                    (
                        "1 para monitorar"
                        if monitorar == 1
                        else f"{monitorar} para monitorar"
                    )
                )

            if not partes_contagem:
                partes_contagem.append(
                    "Prioridade única"
                )

            self.dashboard_alertas_contagem.setText(
                " • ".join(
                    partes_contagem
                )
            )

            estado = (
                "critico"
                if nivel == "Crítico"
                else (
                    "atencao"
                    if nivel == "Atenção"
                    else "monitorar"
                )
            )

            tooltip_linhas = [
                "Prioridades atuais:"
            ]
            for item in alertas[:5]:
                tooltip_linhas.append(
                    (
                        f"• {item.get('nivel_alerta', 'Monitorar')} — "
                        f"{item.get('disciplina', '')} › "
                        f"{item.get('topico', '')}: "
                        f"{item.get('motivo_alerta', '')}"
                    )
                )

            if total_alertas > 5:
                tooltip_linhas.append(
                    f"• + {total_alertas - 5} alerta(s)"
                )

            self.dashboard_alertas_conteudo.setToolTip(
                "\n".join(
                    tooltip_linhas
                )
            )
            self.dashboard_alertas_conteudo.setProperty(
                "alertState",
                estado
            )
            self.dashboard_alertas_botao.setText(
                "Abrir prioridade"
            )
            self.dashboard_alertas_botao.setEnabled(
                True
            )

        self.dashboard_alertas_conteudo.style().unpolish(
            self.dashboard_alertas_conteudo
        )
        self.dashboard_alertas_conteudo.style().polish(
            self.dashboard_alertas_conteudo
        )

        self.atualizar_previsao_dashboard(
            concurso_id
        )

