    def filtrar_alertas_conteudo(self):
        if not hasattr(
            self,
            "dados_alertas_conteudo"
        ):
            return

        busca = self.normalizar_texto_progresso(
            self.alertas_busca.text()
        )

        nivel = (
            self.alertas_filtro_nivel.currentText()
        )
        tipo = (
            self.alertas_filtro_tipo.currentText()
        )

        filtrados = []

        for item in self.dados_alertas_conteudo:
            if (
                nivel != "Todos os níveis"
                and item[
                    "nivel_alerta"
                ] != nivel
            ):
                continue

            if (
                tipo != "Todos os tipos"
                and tipo not in item[
                    "tipos_alerta"
                ]
            ):
                continue

            if busca:
                alvo = self.normalizar_texto_progresso(
                    (
                        f"{item['disciplina']} "
                        f"{item['topico']} "
                        f"{item['nivel_alerta']} "
                        f"{item['motivo_alerta']}"
                    )
                )

                termos = [
                    termo
                    for termo in busca.split(
                        " "
                    )
                    if termo
                ]

                if not all(
                    termo in alvo
                    for termo in termos
                ):
                    continue

            filtrados.append(
                item
            )

        self.alertas_vazio.setVisible(
            len(
                filtrados
            ) == 0
        )
        self.tabela_alertas_conteudo.setVisible(
            len(
                filtrados
            ) > 0
        )

        self.tabela_alertas_conteudo.setRowCount(
            len(
                filtrados
            )
        )

        mapa_nivel = {
            "Crítico": "perigo",
            "Atenção": "alerta",
            "Monitorar": "atencao",
        }

        for linha, item in enumerate(
            filtrados
        ):
            atraso_texto = (
                (
                    f"{item['dias_atraso']} d"
                )
                if item[
                    "dias_atraso"
                ] > 0
                else "—"
            )

            valores = [
                item[
                    "nivel_alerta"
                ],
                item[
                    "disciplina"
                ],
                item[
                    "topico"
                ],
                item[
                    "motivo_alerta"
                ],
                formatar_data(
                    item[
                        "ultima"
                    ]
                ),
                formatar_data(
                    item[
                        "proxima"
                    ]
                ),
                atraso_texto,
                formatar_percentual(
                    item[
                        "percentual"
                    ]
                ),
                "",
            ]

            for coluna, valor in enumerate(
                valores
            ):
                if coluna == 8:
                    continue

                celula = QTableWidgetItem(
                    valor
                )

                if coluna == 2:
                    celula.setData(
                        Qt.UserRole,
                        item[
                            "topico_id"
                        ]
                    )

                if coluna in (
                    0,
                    4,
                    5,
                    6,
                    7
                ):
                    celula.setTextAlignment(
                        Qt.AlignCenter
                    )

                if coluna == 0:
                    aplicar_destaque_tabela(
                        celula,
                        mapa_nivel.get(
                            item[
                                "nivel_alerta"
                            ],
                            "atencao"
                        ),
                        True
                    )

                if (
                    coluna == 7
                    and item[
                        "percentual"
                    ] is not None
                    and item[
                        "percentual"
                    ] < 70
                ):
                    aplicar_destaque_tabela(
                        celula,
                        "perigo",
                        False
                    )

                self.tabela_alertas_conteudo.setItem(
                    linha,
                    coluna,
                    celula
                )

            estrelas = IndicadorEstrelasFila(
                item[
                    "importancia"
                ]
            )
            self.tabela_alertas_conteudo.setCellWidget(
                linha,
                8,
                estrelas
            )

            self.tabela_alertas_conteudo.setRowHeight(
                linha,
                34
            )

    def abrir_topico_alerta(
        self,
        linha,
        coluna
    ):
        item = self.tabela_alertas_conteudo.item(
            linha,
            2
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )

        if topico_id is None:
            return

        janela = JanelaTopico(
            topico_id,
            item.text(),
            self
        )

        janela.exec()

        self.atualizar_dashboard()
        self.invalidar_estatisticas("all")

    def montar_dados_progresso_edital(
        self,
        concurso_id
    ):
        return self.montar_snapshot_progresso_edital(concurso_id)["topicos"]

    def montar_snapshot_progresso_edital(
        self,
        concurso_id
    ):
        """Fonte única compartilhada pela aba Progresso e pelo Dashboard."""
        return self.cache_analitico.obter(
            f"progresso:v2:{int(concurso_id)}",
            lambda: obter_snapshot_progresso_edital(concurso_id),
            ttl=20,
        )

    def atualizar_progresso_dashboard(
        self,
        concurso_id,
        metricas_globais=None
    ):
        if not hasattr(
            self,
            "dashboard_progresso_trabalhado"
        ):
            return

        snapshot = self.montar_snapshot_progresso_edital(
            concurso_id
        )
        total = int(snapshot["total_topics"])
        trabalhados = int(snapshot["started_topics"])
        cobertura_valor = snapshot["topic_coverage_rate"]
        cobertura = round(float(cobertura_valor)) if cobertura_valor is not None else 0

        self.dashboard_progresso_trabalhado.setText(
            f"{cobertura}%"
        )
        self.dashboard_progresso_barra.setValue(
            int(
                cobertura
            )
        )
        self.dashboard_progresso_contagem.setText(
            f"{trabalhados} de {total} tópicos"
        )
        self.dashboard_progresso_consolidando.setText(
            (
                f"{float(snapshot['sufficient_evidence_rate']):.0f}%"
                if snapshot["sufficient_evidence_rate"] is not None
                else "Dados insuficientes"
            )
        )
        self.dashboard_progresso_consolidado.setText(
            str(snapshot["consolidated_topics"])
        )
        self.dashboard_progresso_nao_iniciado.setText(
            (
                f"{float(snapshot['question_coverage_rate']):.0f}%"
                if snapshot["question_coverage_rate"] is not None
                else "—"
            )
        )
        dominio_global = snapshot["global_mastery_score"]

        if dominio_global is not None:
            self.dashboard_dominio_medio.setText(
                f"{float(dominio_global):.0f}/100"
            )
        else:
            self.dashboard_dominio_medio.setText(
                "—"
            )

        self.atualizar_alertas_dashboard(
            concurso_id
        )
        return snapshot

    def abrir_progresso_edital(self):
        self.abrir_estatisticas("Progresso")

    def normalizar_texto_progresso(
        self,
        texto
    ):
        texto = str(
            texto
            or ""
        ).lower().strip()

        texto = unicodedata.normalize(
            "NFD",
            texto
        )

        texto = "".join(
            caractere
            for caractere in texto
            if unicodedata.category(
                caractere
            )
            != "Mn"
        )

        return " ".join(
            texto.split()
        )

    def atualizar_progresso_edital(self):
        if not hasattr(
            self,
            "tabela_progresso_topicos"
        ):
            return

        concurso_id = (
            obter_concurso_ativo()[0]
        )

        snapshot = self.montar_snapshot_progresso_edital(
            concurso_id
        )
        dados = snapshot["topicos"]
        self.dados_progresso_edital = dados
        total = int(snapshot["total_topics"])
        trabalhados = int(snapshot["started_topics"])
        percentual_trabalhado = snapshot["topic_coverage_rate"]
        percentual_consolidado = snapshot["consolidated_rate"]
        percentual_evidencia = snapshot["sufficient_evidence_rate"]
        cobertura_questoes = snapshot["question_coverage_rate"]

        self.progresso_card_trabalhado.setText(
            (
                f"{float(percentual_trabalhado):.0f}%"
                if percentual_trabalhado is not None
                else "Dados insuficientes"
            )
        )
        self.progresso_card_trabalhado_hint.setText(
            f"{trabalhados} de {total} tópicos"
        )

        self.progresso_card_consolidado.setText(
            (
                f"{float(percentual_consolidado):.0f}%"
                if percentual_consolidado is not None
                else "Dados insuficientes"
            )
        )
        self.progresso_card_consolidado_hint.setText(
            (
                f"{snapshot['consolidated_topics']} "
                f"de {total} tópicos"
            )
        )

        self.progresso_card_consolidando.setText(
            (
                f"{float(percentual_evidencia):.0f}%"
                if percentual_evidencia is not None
                else "Dados insuficientes"
            )
        )
        self.progresso_card_consolidando_hint.setText(
            (
                f"{snapshot['sufficient_evidence_topics']} de {total} "
                "com evidência moderada/alta"
            )
        )

        self.progresso_card_nao_iniciado.setText(
            (
                f"{float(cobertura_questoes):.0f}%"
                if cobertura_questoes is not None
                else "Dados insuficientes"
            )
        )
        self.progresso_card_nao_iniciado_hint.setText(
            "questões ativas respondidas ao menos uma vez"
        )

        dominio_global = snapshot["global_mastery_score"]
        topicos_com_dominio = sum(
            1
            for item in dados
            if item["dominio_score"] is not None
        )

        if dominio_global is not None:

            self.progresso_card_dominio.setText(
                f"{float(dominio_global):.0f}/100"
            )
            self.progresso_card_dominio_hint.setText(
                (
                    f"{topicos_com_dominio} tópico(s) "
                    "com domínio calculável"
                )
            )
        else:
            self.progresso_card_dominio.setText(
                "Dados insuficientes"
            )
            self.progresso_card_dominio_hint.setText(
                "o núcleo ainda não certifica domínio global"
            )

        lacunas = snapshot["gaps"]
        self.progresso_lacunas_resumo.setText(
            "Lacunas do edital — "
            f"não iniciados: {lacunas['not_started']} • "
            f"iniciados com evidência insuficiente: "
            f"{lacunas['started_insufficient_evidence']} • "
            f"evidência baixa: {lacunas['low_evidence']} • "
            f"evidência suficiente, ainda não consolidados: "
            f"{lacunas['sufficient_evidence_not_consolidated']} • "
            f"revisões vencidas: {lacunas['overdue_review']}"
        )

        # ----------------------------------------------------
        # DISCIPLINAS
        # ----------------------------------------------------

        disciplinas = snapshot["disciplinas"]

        self.progresso_contagem_disciplinas.setText(
            (
                "1 disciplina"
                if len(
                    disciplinas
                ) == 1
                else f"{len(disciplinas)} disciplinas"
            )
        )

        tabela_disciplinas = self.tabela_progresso_disciplinas
        tabela_disciplinas.setUpdatesEnabled(False)
        tabela_disciplinas.blockSignals(True)
        try:
            tabela_disciplinas.setRowCount(len(disciplinas))

            for linha, info in enumerate(disciplinas):
                def taxa_texto(valor):
                    return f"{float(valor):.0f}%" if valor is not None else "—"

                valores = [
                    info["disciplina"],
                    str(info["total_topicos"]),
                    taxa_texto(info["cobertura_topicos"]),
                    taxa_texto(info["cobertura_questoes"]),
                    taxa_texto(info["evidencia_suficiente_taxa"]),
                    str(info["consolidados"]),
                    (
                        f"{float(info['dominio']):.0f}/100"
                        if info["dominio"] is not None
                        else "Dados insuficientes"
                    ),
                ]

                for coluna, valor in enumerate(valores):
                    item_tabela = QTableWidgetItem(valor)

                    if coluna > 0:
                        item_tabela.setTextAlignment(Qt.AlignCenter)

                    if coluna == 5 and info["consolidados"] > 0:
                        aplicar_destaque_tabela(
                            item_tabela,
                            "sucesso",
                            False
                        )

                    tabela_disciplinas.setItem(linha, coluna, item_tabela)

                tabela_disciplinas.setRowHeight(linha, 34)
        finally:
            tabela_disciplinas.blockSignals(False)
            tabela_disciplinas.setUpdatesEnabled(True)

        # Recarrega o filtro de disciplina preservando a seleção.
        selecao_anterior = (
            self.progresso_filtro_disciplina.currentText()
        )

        nomes_disciplinas = [
            item["disciplina"]
            for item in disciplinas
        ]

        self.progresso_filtro_disciplina.blockSignals(
            True
        )
        self.progresso_filtro_disciplina.clear()
        self.progresso_filtro_disciplina.addItem(
            "Todas as disciplinas"
        )
        self.progresso_filtro_disciplina.addItems(
            nomes_disciplinas
        )

        if selecao_anterior in (
            ["Todas as disciplinas"]
            + nomes_disciplinas
        ):
            self.progresso_filtro_disciplina.setCurrentText(
                selecao_anterior
            )

        self.progresso_filtro_disciplina.blockSignals(
            False
        )

        self.filtrar_progresso_edital()
        self.atualizar_alertas_conteudo()
        self.atualizar_previsao_edital()
        if hasattr(self, "_estado_estatisticas"):
            self._estado_estatisticas.marcar_limpa("Progresso")

    def filtrar_progresso_edital(self):
        if not hasattr(
            self,
            "dados_progresso_edital"
        ):
            return

        busca = self.normalizar_texto_progresso(
            self.progresso_busca.text()
        )

        disciplina_filtro = (
            self.progresso_filtro_disciplina.currentText()
        )
        estado_filtro = (
            self.progresso_filtro_estado.currentText()
        )
        evidencia_filtro = (
            self.progresso_filtro_evidencia.currentText()
        )
        mapa_evidencia_filtro = {
            "Evidência insuficiente": "insufficient",
            "Evidência baixa": "low",
            "Evidência moderada": "moderate",
            "Evidência alta": "high",
        }

        filtrados = []

        for item in self.dados_progresso_edital:
            if (
                disciplina_filtro
                and disciplina_filtro
                != "Todas as disciplinas"
                and item[
                    "disciplina"
                ] != disciplina_filtro
            ):
                continue

            if (
                estado_filtro
                and estado_filtro
                != "Todos os estados"
                and item[
                    "estado"
                ] != estado_filtro
            ):
                continue

            evidencia_codigo = mapa_evidencia_filtro.get(
                evidencia_filtro
            )
            if evidencia_codigo and item["evidencia"] != evidencia_codigo:
                continue

            if busca:
                alvo = self.normalizar_texto_progresso(
                    (
                        f"{item['disciplina']} "
                        f"{item['topico']} "
                        f"{item['estado']} "
                        f"{item['evidencia_rotulo']} "
                        f"{item['dominio_nivel']} "
                        f"{item['dominio_score']}"
                    )
                )

                termos = [
                    termo
                    for termo in busca.split(
                        " "
                    )
                    if termo
                ]

                if not all(
                    termo in alvo
                    for termo in termos
                ):
                    continue

            filtrados.append(
                item
            )

        quantidade = len(
            filtrados
        )

        self.progresso_contagem_topicos.setText(
            (
                "1 tópico"
                if quantidade == 1
                else f"{quantidade} tópicos"
            )
        )

        self.tabela_progresso_topicos.setUpdatesEnabled(False)
        self.tabela_progresso_topicos.blockSignals(True)
        self.tabela_progresso_topicos.setRowCount(
            quantidade
        )

        mapa_destaque = {
            "Não iniciado": "perigo",
            "Em andamento": "alerta",
            "Em consolidação": "atencao",
            "Consolidado": "sucesso",
        }

        for linha, item in enumerate(
            filtrados
        ):
            dominio_item = item["dominio"]
            score_dominio = item["dominio_score"]
            texto_dominio = (
                f"{float(score_dominio):.0f}/100 • {item['dominio_nivel']}"
                + (" • provisório" if item["dominio_provisorio"] else "")
                if score_dominio is not None
                else "Dados insuficientes"
            )
            valores = [
                item["disciplina"],
                item["topico"],
                item["estado"],
                (
                    f"{float(item['cobertura_questoes']):.0f}%"
                    if item["cobertura_questoes"] is not None
                    else "Sem questões ativas"
                ),
                item["evidencia_rotulo"],
                texto_dominio,
                str(item["revisoes"]),
                formatar_data(item["proxima"]),
            ]

            for coluna, valor in enumerate(
                valores
            ):
                celula = QTableWidgetItem(
                    valor
                )

                if coluna == 1:
                    celula.setData(
                        Qt.UserRole,
                        item[
                            "topico_id"
                        ]
                    )

                if coluna in (
                    2,
                    3,
                    4,
                    6,
                    7
                ):
                    celula.setTextAlignment(
                        Qt.AlignCenter
                    )

                if coluna == 2:
                    aplicar_destaque_tabela(
                        celula,
                        mapa_destaque.get(
                            item[
                                "estado"
                            ],
                            "atencao"
                        ),
                        True
                    )

                if coluna == 5:
                    cobertura_item = dominio_item.get("cobertura")
                    recente_item = dominio_item.get("desempenho_recente")
                    score_tooltip = (
                        f"{float(score_dominio):.1f}/100"
                        if score_dominio is not None
                        else "dados insuficientes"
                    )
                    recente_tooltip = (
                        f"{float(recente_item):.1f}"
                        if recente_item is not None
                        else "dados insuficientes"
                    )
                    cobertura_tooltip = (
                        f"{float(cobertura_item):.1f}"
                        if cobertura_item is not None
                        else "dados insuficientes"
                    )

                    celula.setToolTip(
                        (
                            f"Índice de Domínio: {score_tooltip}\n"
                            f"Nível: {item['dominio_nivel']}\n"
                            f"Evidência: {item['evidencia_rotulo']}\n\n"
                            f"Desempenho atual: {dominio_item.get('desempenho') if dominio_item.get('desempenho') is not None else 'dados insuficientes'}\n"
                            f"Desempenho recente: {recente_tooltip}\n"
                            f"Cobertura de questões: {cobertura_tooltip}\n"
                            f"Consolidação: {item['consolidacao']}\n\n"
                            f"Respostas históricas: {dominio_item['tentativas_historicas']} • "
                            f"Questões diferentes: {dominio_item['questoes_unicas']} • "
                            f"Dias: {dominio_item['dias_ativos_historicos']} • "
                            f"Dúvidas: {dominio_item.get('taxa_duvida') if dominio_item.get('taxa_duvida') is not None else '—'} • "
                            f"Recorrentes: {dominio_item['recorrentes']} • "
                            f"Críticas: {dominio_item['criticas']}"
                        )
                    )

                    nivel_dominio = item["dominio_nivel"]

                    if nivel_dominio in (
                        "Domínio forte",
                        "Dominado"
                    ):
                        aplicar_destaque_tabela(
                            celula,
                            "sucesso",
                            False
                        )
                    elif nivel_dominio in (
                        "Crítico",
                        "Frágil"
                    ):
                        aplicar_destaque_tabela(
                            celula,
                            "perigo",
                            False
                        )
                    elif nivel_dominio in (
                        "Em desenvolvimento",
                        "Consolidando"
                    ):
                        aplicar_destaque_tabela(
                            celula,
                            "atencao",
                            False
                        )

                if coluna == 4:
                    tom_evidencia = {
                        "insufficient": "perigo",
                        "low": "alerta",
                        "moderate": "atencao",
                        "high": "sucesso",
                    }.get(item["evidencia"], "atencao")
                    aplicar_destaque_tabela(celula, tom_evidencia, False)

                self.tabela_progresso_topicos.setItem(
                    linha,
                    coluna,
                    celula
                )

            self.tabela_progresso_topicos.setRowHeight(
                linha,
                32
            )

        self.tabela_progresso_topicos.blockSignals(False)
        self.tabela_progresso_topicos.setUpdatesEnabled(True)

    def abrir_topico_progresso(
        self,
        linha,
        coluna
    ):
        item = self.tabela_progresso_topicos.item(
            linha,
            1
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )

        if topico_id is None:
            return

        janela = JanelaTopico(
            topico_id,
            item.text(),
            self
        )

        janela.exec()

        self.atualizar_dashboard()
        self.invalidar_estatisticas("all")

    def alterar_periodo_evolucao(
        self,
        texto,
        atualizar=True
    ):
        personalizado = (
            texto == "Personalizado"
        )

        for widget in (
            self.evolucao_label_de,
            self.data_inicio_evolucao,
            self.evolucao_label_ate,
            self.data_fim_evolucao
        ):
            widget.setVisible(
                personalizado
            )

        hoje = QDate.currentDate()

        if not personalizado:
            dias = {
                "7 dias": 7,
                "30 dias": 30,
                "60 dias": 60,
                "90 dias": 90
            }.get(
                texto,
                30
            )

            self.data_fim_evolucao.blockSignals(
                True
            )
            self.data_inicio_evolucao.blockSignals(
                True
            )

            self.data_fim_evolucao.setDate(
                hoje
            )
            self.data_inicio_evolucao.setDate(
                hoje.addDays(
                    -(
                        dias
                        - 1
                    )
                )
            )

            self.data_inicio_evolucao.blockSignals(
                False
            )
            self.data_fim_evolucao.blockSignals(
                False
            )

        elif not self.data_inicio_evolucao.date().isValid():
            self.data_inicio_evolucao.setDate(
                hoje.addDays(
                    -29
                )
            )
            self.data_fim_evolucao.setDate(
                hoje
            )

        if atualizar:
            self.atualizar_evolucao_temporal()

    def atualizar_evolucao_personalizada(
        self
    ):
        if (
            self.combo_periodo_evolucao.currentText()
            == "Personalizado"
        ):
            self.atualizar_evolucao_temporal()

    def atualizar_evolucao_temporal(self, *args, forcar=False):
        if not hasattr(self, "combo_periodo_evolucao"):
            return

        inicio = self.data_inicio_evolucao.date()
        fim = self.data_fim_evolucao.date()
        if not inicio.isValid() or not fim.isValid():
            return
        if inicio > fim:
            QMessageBox.warning(
                self,
                "Período inválido",
                "A data inicial não pode ser posterior à data final.",
            )
            return

        concurso_id = obter_concurso_ativo()[0]
        inicio_iso = inicio.toString("yyyy-MM-dd")
        fim_iso = fim.toString("yyyy-MM-dd")
        chave_cache = (
            f"estatisticas:tendencias:{int(concurso_id)}:"
            f"{inicio_iso}:{fim_iso}"
        )
        if forcar:
            self.cache_analitico.invalidar(chave_cache)
        dados = self.cache_analitico.obter(
            chave_cache,
            lambda: obter_analise_temporal(
                concurso_id,
                data_inicio=inicio_iso,
                data_fim_inclusivo=fim_iso,
            ),
            ttl=20,
        )
        self.dados_evolucao_temporal = dados
        atual = dados["current_metrics"]
        anterior = dados["previous_metrics"]
        comparacao = dados["comparisons"]["accuracy"]
        suficiente = dados["sufficiency"]
        tendencia = dados["official_performance_trend"]
        periodo_anterior = dados["previous_period"]

        self.evolucao_periodo_label.setText(
            f"{inicio.toString('dd/MM/yyyy')} — {fim.toString('dd/MM/yyyy')} • "
            f"{dados['current_period']['days']} dia(s)"
        )
        self.evolucao_desempenho.setText(
            formatar_percentual(atual.get("accuracy_rate"))
        )
        self.evolucao_desempenho_tendencia.setText(
            f"{atual.get('attempts', 0)} tentativas • "
            f"{atual.get('active_days', 0)} dias ativos"
        )
        self.evolucao_desempenho_tendencia.setProperty("trendState", "neutra")

        delta = comparacao.get("delta_pp")
        if delta is None:
            self.evolucao_questoes_dia.setText("Dados insuficientes")
            self.evolucao_questoes_tendencia.setText(
                "período atual × anterior equivalente"
            )
            self.evolucao_questoes_tendencia.setProperty("trendState", "neutra")
        else:
            texto_delta = self.formatar_variacao_minha_evolucao(delta)
            self.evolucao_questoes_dia.setText(texto_delta)
            self.evolucao_questoes_tendencia.setText(
                f"anterior {formatar_percentual(anterior.get('accuracy_rate'))}"
            )
            self.evolucao_questoes_tendencia.setProperty(
                "trendState",
                "positiva" if delta > 0 else "negativa" if delta < 0 else "neutra",
            )

        mapa_tendencia = {
            "improvement": ("Melhora", "positiva"),
            "decline": ("Queda", "negativa"),
            "stable": ("Estável", "neutra"),
            "insufficient_data": ("Dados insuficientes", "neutra"),
        }
        tendencia_texto, tendencia_estado = mapa_tendencia.get(
            tendencia.get("value"), ("Dados insuficientes", "neutra")
        )
        self.evolucao_revisoes_dia.setText(tendencia_texto)
        self.evolucao_revisoes_tendencia.setText(
            "performance_trend@1 • janelas de tentativas"
        )
        self.evolucao_revisoes_tendencia.setProperty(
            "trendState", tendencia_estado
        )

        self.evolucao_dias_estudados.setText(
            "Base suficiente" if suficiente.get("ready") else "Dados insuficientes"
        )
        self.evolucao_dias_tendencia.setText(
            f"atual {atual.get('attempts', 0)} / {atual.get('active_days', 0)}d • "
            f"anterior {anterior.get('attempts', 0)} / "
            f"{anterior.get('active_days', 0)}d"
        )
        self.evolucao_dias_tendencia.setProperty("trendState", "neutra")

        for label in (
            self.evolucao_desempenho_tendencia,
            self.evolucao_questoes_tendencia,
            self.evolucao_revisoes_tendencia,
            self.evolucao_dias_tendencia,
        ):
            label.style().unpolish(label)
            label.style().polish(label)

        faltas = suficiente.get("missing", {})
        if suficiente.get("ready"):
            texto_suficiencia = (
                "Comparação válida: ambos os períodos possuem ao menos "
                "10 tentativas e 2 dias ativos."
            )
        else:
            partes = []
            rotulos_faltas = (
                ("current_attempts", "tentativas no período atual"),
                ("previous_attempts", "tentativas no período anterior"),
                ("current_active_days", "dias ativos no período atual"),
                ("previous_active_days", "dias ativos no período anterior"),
            )
            for chave, rotulo in rotulos_faltas:
                quantidade = int(faltas.get(chave, 0) or 0)
                if quantidade:
                    partes.append(f"faltam {quantidade} {rotulo}")
            texto_suficiencia = (
                "Dados insuficientes para comparação"
                + (" • " + " • ".join(partes) if partes else "")
            )
        inicio_ant = QDate.fromString(
            periodo_anterior["start"][:10], "yyyy-MM-dd"
        ).toString("dd/MM/yyyy")
        fim_ant = QDate.fromString(
            periodo_anterior["end_inclusive"], "yyyy-MM-dd"
        ).toString("dd/MM/yyyy")
        self.evolucao_estado_comparacao.setText(
            f"{texto_suficiencia}\nPeríodo anterior equivalente: "
            f"{inicio_ant} — {fim_ant}. Atividade maior não é, por si só, melhora acadêmica."
        )

        serie = dados.get("display_series") or dados.get("daily_series") or []
        rotulos = []
        for item in serie:
            inicio_item = QDate.fromString(item["date"], "yyyy-MM-dd").toString("dd/MM")
            fim_item = item.get("end_date")
            if fim_item:
                fim_formatado = QDate.fromString(
                    fim_item, "yyyy-MM-dd"
                ).toString("dd/MM")
                rotulos.append(f"{inicio_item}–{fim_formatado}")
            else:
                rotulos.append(inicio_item)
        self.grafico_evolucao_desempenho.definir_dados(
            [item.get("accuracy_rate") for item in serie], rotulos
        )
        self.grafico_evolucao_questoes.definir_dados(
            [item.get("attempts", 0) for item in serie], rotulos
        )
        self.grafico_evolucao_revisoes.definir_dados(
            [item.get("qualified_reviews", 0) for item in serie], rotulos
        )

        disciplinas = [
            item for item in dados.get("subjects", [])
            if item["current"]["attempts"] or item["previous"]["attempts"]
        ]
        self.evolucao_contagem_disciplinas.setText(
            "1 disciplina" if len(disciplinas) == 1
            else f"{len(disciplinas)} disciplinas"
        )
        self.tabela_evolucao_disciplinas.setRowCount(len(disciplinas))
        for linha, item_d in enumerate(disciplinas):
            atual_d = item_d["current"]
            anterior_d = item_d["previous"]
            comp_d = item_d["comparison"]["accuracy"]
            delta_d = comp_d.get("delta_pp")
            valores = [
                item_d["name"],
                formatar_percentual(atual_d.get("accuracy_rate")),
                formatar_percentual(anterior_d.get("accuracy_rate")),
                (
                    self.formatar_variacao_minha_evolucao(delta_d)
                    if delta_d is not None else "Dados insuficientes"
                ),
                f"{atual_d.get('attempts', 0)} / {anterior_d.get('attempts', 0)}",
                "Comparável" if item_d.get("comparable") else "Não comparável",
            ]
            for coluna, valor in enumerate(valores):
                celula = QTableWidgetItem(str(valor))
                if coluna:
                    celula.setTextAlignment(Qt.AlignCenter)
                if coluna == 3 and delta_d is not None:
                    if delta_d >= 2.0:
                        aplicar_destaque_tabela(celula, "sucesso", False)
                    elif delta_d <= -2.0:
                        aplicar_destaque_tabela(celula, "perigo", False)
                self.tabela_evolucao_disciplinas.setItem(linha, coluna, celula)
            self.tabela_evolucao_disciplinas.setRowHeight(linha, 31)

        topicos = [
            item for item in dados.get("topics", [])
            if item["current"]["attempts"] or item["previous"]["attempts"]
        ]
        topicos.sort(
            key=lambda item: (
                not item.get("comparable"),
                -abs(item["comparison"]["accuracy"].get("delta_pp") or 0.0),
                item.get("subject", "").casefold(),
                item.get("name", "").casefold(),
            )
        )
        comparaveis = [item for item in topicos if item.get("comparable")]
        positivos = [
            item for item in comparaveis
            if float(item["comparison"]["accuracy"]["delta_pp"]) > 0
        ]
        negativos = [
            item for item in comparaveis
            if float(item["comparison"]["accuracy"]["delta_pp"]) < 0
        ]
        if comparaveis:
            mensagens = [f"{len(comparaveis)} tópico(s) comparável(is)."]
            if positivos:
                melhor = max(
                    positivos,
                    key=lambda item: item["comparison"]["accuracy"]["delta_pp"],
                )
                mensagens.append(
                    f"Maior evolução: {melhor['subject']} › {melhor['name']} "
                    f"({melhor['comparison']['accuracy']['delta_pp']:+.1f} p.p.)."
                )
            if negativos:
                pior = min(
                    negativos,
                    key=lambda item: item["comparison"]["accuracy"]["delta_pp"],
                )
                mensagens.append(
                    f"Ponto de atenção: {pior['subject']} › {pior['name']} "
                    f"({pior['comparison']['accuracy']['delta_pp']:+.1f} p.p.)."
                )
            self.evolucao_topicos_aviso.setText(" ".join(mensagens))
        else:
            self.evolucao_topicos_aviso.setText(
                "Ainda não há base suficiente para comparar tópicos."
            )

        self.tabela_evolucao_topicos.setRowCount(len(topicos))
        for linha, item_t in enumerate(topicos):
            atual_t = item_t["current"]
            anterior_t = item_t["previous"]
            delta_t = item_t["comparison"]["accuracy"].get("delta_pp")
            valores = [
                item_t.get("subject", "—"),
                item_t.get("name", "—"),
                formatar_percentual(atual_t.get("accuracy_rate")),
                formatar_percentual(anterior_t.get("accuracy_rate")),
                (
                    self.formatar_variacao_minha_evolucao(delta_t)
                    if delta_t is not None else "—"
                ),
                f"{atual_t.get('attempts', 0)} / {anterior_t.get('attempts', 0)}",
                "Comparável" if item_t.get("comparable") else "Não comparável ainda",
            ]
            for coluna, valor in enumerate(valores):
                celula = QTableWidgetItem(str(valor))
                if coluna >= 2:
                    celula.setTextAlignment(Qt.AlignCenter)
                if coluna == 4 and delta_t is not None:
                    if delta_t >= 2.0:
                        aplicar_destaque_tabela(celula, "sucesso", False)
                    elif delta_t <= -2.0:
                        aplicar_destaque_tabela(celula, "perigo", False)
                self.tabela_evolucao_topicos.setItem(linha, coluna, celula)
            self.tabela_evolucao_topicos.setRowHeight(linha, 31)

        progresso = dados.get("progress_history") or []
        if not progresso:
            self.evolucao_progresso_historico_aviso.setText(
                "Coleta histórica ainda não iniciada."
            )
            self.grafico_evolucao_progresso.definir_dados([], [])
        elif len(progresso) == 1:
            inicio_coleta = QDate.fromString(
                progresso[0]["date"], "yyyy-MM-dd"
            ).toString("dd/MM/yyyy")
            self.evolucao_progresso_historico_aviso.setText(
                f"Histórico de progresso disponível a partir de {inicio_coleta}. "
                "Coleta histórica iniciada — ainda sem série suficiente."
            )
            self.grafico_evolucao_progresso.definir_dados([], [])
        else:
            self.evolucao_progresso_historico_aviso.setText(
                "Cobertura de questões registrada por snapshots diários reais; "
                "não há backfill."
            )
            self.grafico_evolucao_progresso.definir_dados(
                [item.get("question_coverage_rate") for item in progresso],
                [
                    QDate.fromString(item["date"], "yyyy-MM-dd").toString("dd/MM")
                    for item in progresso
                ],
            )

        if hasattr(self, "_estado_estatisticas"):
            self._estado_estatisticas.marcar_limpa("Tendências")

    def atualizar_icones_interface(self):
        """Aplica os ícones vetoriais disponíveis sem tornar a UI dependente deles."""
        tema = normalizar_tema(
            getattr(self, "tema_atual", "claro")
        )
        visual_dashboard = getattr(self, "dashboard_visual_root", None)
        if visual_dashboard is not None:
            estilo = dashboard_visual_styles(tema) + _estilo_metricas_rapidas_planejamento(tema)
            if visual_dashboard.styleSheet() != estilo:
                visual_dashboard.setStyleSheet(estilo)
            visual_dashboard.update()
        # O painel Estudo por questões utiliza os MESMOS estilos que possuía
        # no Dashboard, mesmo agora residindo na Central de Simulados.
        raiz_estudo = getattr(self, "_portal_estudo_questoes_raiz", None)
        if raiz_estudo is not None and visual_dashboard is not None:
            if raiz_estudo.styleSheet() != visual_dashboard.styleSheet():
                raiz_estudo.setStyleSheet(visual_dashboard.styleSheet())

        raiz_edital = getattr(self, "_portal_edital_dashboard_raiz", None)
        if raiz_edital is not None and visual_dashboard is not None:
            if raiz_edital.styleSheet() != visual_dashboard.styleSheet():
                raiz_edital.setStyleSheet(visual_dashboard.styleSheet())

        if hasattr(self, "botao_configuracoes_topo"):
            fallback_config = (
                Path(__file__).resolve().parent
                / "assets"
                / "config_gear.png"
            )
            self.botao_configuracoes_topo.setIcon(
                criar_icone(
                    "fa6s.gear",
                    tema=tema,
                    papel="configuracao",
                    fallback_path=fallback_config,
                )
            )
            self.botao_configuracoes_topo.setIconSize(
                QSize(20, 20)
            )

        botoes_acoes = (
            ("dashboard_botao_pausa", "fa6s.pause"),
            ("dashboard_botao_estatisticas", "fa6s.chart-pie"),
            ("dashboard_botao_relatorios", "fa6s.file-lines"),
            ("dashboard_botao_calendario", "fa6s.calendar-days"),
        )

        for atributo, nome_icone in botoes_acoes:
            botao = getattr(self, atributo, None)
            if botao is None:
                continue
            botao.setIcon(
                criar_icone(
                    nome_icone,
                    tema=tema,
                    papel="acao",
                )
            )
            botao.setIconSize(QSize(15, 15))

        botoes_disciplina = (
            ("botao_adicionar_topico", "fa6s.circle-plus", "destaque", 17),
            ("botao_estudar_topico_disciplina", "fa6s.play", "destaque", 14),
            ("botao_ver_questoes_topico_disciplina", "fa6s.list", "acao", 15),
            ("botao_mais_topico_disciplina", "fa6s.ellipsis", "acao", 15),
        )
        for atributo, nome_icone, papel, tamanho in botoes_disciplina:
            botao = getattr(self, atributo, None)
            if botao is None:
                continue
            botao.setIcon(
                criar_icone(
                    nome_icone,
                    tema=tema,
                    papel=papel,
                )
            )
            botao.setIconSize(QSize(tamanho, tamanho))

        botao_mais_disciplina = getattr(self, "botao_mais_disciplina", None)
        if botao_mais_disciplina is not None:
            icone_mais = criar_icone(
                "fa6s.ellipsis",
                tema=tema,
                papel="acao",
            )
            botao_mais_disciplina.setIcon(icone_mais)
            botao_mais_disciplina.setIconSize(QSize(16, 16))
            botao_mais_disciplina.setText("" if not icone_mais.isNull() else "⋯")

    def abrir_configuracoes(self):
        janela = JanelaConfiguracoes(
            self
        )
        # showMaximized respeita a área de trabalho do Windows e permite
        # restaurar a janela pelo controle nativo no canto superior direito.
        janela.showMaximized()

        if janela.exec() == QDialog.Accepted:
            self.tema_atual = normalizar_tema(
                obter_configuracao_texto(
                    "tema_interface",
                    "claro",
                )
            )
            self.atualizar_icones_interface()
            self._atualizar_layout_sidebar()
            self.atualizar_estilos_disciplinas_desligadas_dashboard()
            self.cache_analitico.invalidar("regularidade:")
            self.cache_analitico.invalidar("estatisticas:regularidade:")
            self._estado_estatisticas.marcar_sujas(("Regularidade",), resumo=False)
            self.atualizar_dashboard()

            # Aplica imediatamente a mesma preferência ao fundo já existente.
            # Não reconstrói a Home e não altera os quadros, cards ou timer.
            fundo_home = self.tela_portal_inicio.findChild(
                QWidget, "portalInicioConteudo"
            )
            if fundo_home is not None and hasattr(
                fundo_home, "definir_reducao_movimento"
            ):
                preferencia = QSettings("VighnaStudy", "Home")
                fundo_home.definir_reducao_movimento(preferencia.value(
                    "acessibilidade/reduzir_movimento", False, type=bool
                ))
            # A preferência de movimento é compartilhada com o novo GIF do
            # Dashboard e entra em vigor sem reiniciar o aplicativo.
            self._sincronizar_animacao_dashboard()

            QMessageBox.information(
                self,
                "Configurações salvas",
                (
                    "As novas regras já estão ativas.\n\n"
                    "Elas também permanecerão salvas nas "
                    "próximas vezes que o programa for aberto."
                )
            )


    def obter_dias_minha_evolucao(self):
        texto = (
            self.combo_periodo_minha_evolucao.currentText()
            if hasattr(self, "combo_periodo_minha_evolucao")
            else "30 dias"
        )

        if texto.startswith("7"):
            return 7
        if texto.startswith("60"):
            return 60
        if texto.startswith("90"):
            return 90
        return 30

    def formatar_variacao_minha_evolucao(self, valor):
        if valor is None:
            return "—"

        valor = float(valor)
        if abs(valor) < 0.05:
            return "Estável"

        prefixo = "+" if valor > 0 else ""
        return (
            f"{prefixo}{valor:.1f} p.p."
            .replace(".", ",")
        )

    def formatar_variacao_volume_historica(self, atual, anterior):
        atual = float(atual or 0)
        anterior = float(anterior or 0)
        if anterior <= 0:
            if atual <= 0:
                return "Sem atividade nos dois períodos"
            return "Sem base anterior comparável"
        variacao = 100.0 * (atual - anterior) / anterior
        if abs(variacao) < 0.5:
            return "Estável vs. período anterior"
        prefixo = "+" if variacao > 0 else ""
        return (
            f"{prefixo}{variacao:.0f}% vs. período anterior"
            .replace(".", ",")
        )

    def atualizar_grafico_minha_evolucao(self, *args):
        if not hasattr(self, "grafico_minha_evolucao"):
            return

        dados = getattr(
            self,
            "dados_minha_evolucao",
            None
        )
        if not dados:
            self.grafico_minha_evolucao.definir_dados([], [])
            return

        serie = dados.get("serie", [])
        metrica = (
            self.combo_metrica_minha_evolucao.currentText()
            if hasattr(self, "combo_metrica_minha_evolucao")
            else "Desempenho"
        )

        if metrica == "Questões resolvidas":
            valores = [item.get("questoes", 0) for item in serie]
            self.grafico_minha_evolucao.percentual = False
            self.grafico_minha_evolucao.barras = True
        elif metrica == "Foco efetivo (global)":
            valores = [item.get("foco_minutos", 0) for item in serie]
            self.grafico_minha_evolucao.percentual = False
            self.grafico_minha_evolucao.barras = True
        elif metrica == "Revisões qualificadas":
            valores = [item.get("revisoes", 0) for item in serie]
            self.grafico_minha_evolucao.percentual = False
            self.grafico_minha_evolucao.barras = True
        else:
            valores = [item.get("desempenho") for item in serie]
            self.grafico_minha_evolucao.percentual = True
            self.grafico_minha_evolucao.barras = False

        rotulos = [
            QDate.fromString(
                item.get("data", ""),
                "yyyy-MM-dd"
            ).toString("dd/MM")
            for item in serie
        ]

        self.grafico_minha_evolucao.definir_dados(
            valores,
            rotulos
        )

    def atualizar_minha_evolucao(self, *args, forcar=False):
        if not hasattr(self, "tabela_minha_evolucao"):
            return

        concurso = obter_concurso_ativo()
        dias = self.obter_dias_minha_evolucao()
        chave_cache = f"estatisticas:historico:{int(concurso[0])}:{int(dias)}"
        if forcar:
            self.cache_analitico.invalidar(chave_cache)
        dados = self.cache_analitico.obter(
            chave_cache,
            lambda: obter_evolucao_historica(concurso[0], dias),
            ttl=20,
        )
        self.dados_minha_evolucao = dados

        resumo = dados.get("resumo", {})
        desempenho = resumo.get("desempenho")

        self.minha_desempenho.setText(
            formatar_percentual(desempenho)
        )
        self.minha_desempenho_detalhe.setText(
            f"{resumo.get('questoes', 0)} tentativa(s) • "
            f"{resumo.get('dias_ativos', 0)} dia(s) ativo(s)"
        )

        self.minha_dominio.setText(
            str(resumo.get("questoes", 0))
        )
        self.minha_dominio_detalhe.setText(
            f"{resumo.get('acertos', 0)} acerto(s) • "
            f"{resumo.get('erros', 0)} erro(s)"
        )

        self.minha_questoes.setText(
            str(resumo.get("questoes_unicas", 0))
        )
        self.minha_questoes_detalhe.setText(
            "identidade histórica preservada"
        )

        self.minha_consolidados.setText(
            str(resumo.get("sessoes", 0))
        )
        self.minha_consolidados_detalhe.setText(
            "sessões iniciadas no período"
        )

        foco = dados.get("foco", {})
        foco_anterior = dados.get("foco_anterior", {})
        foco_segundos = int(foco.get("segundos", 0) or 0)
        foco_segundos_anterior = int(foco_anterior.get("segundos", 0) or 0)
        self.minha_foco.setText(
            formatar_tempo_foco_resumido(foco_segundos)
        )
        self.minha_foco_detalhe.setText(
            "Métrica global de hábito • " + self.formatar_variacao_volume_historica(
                foco_segundos,
                foco_segundos_anterior
            )
        )

        dias_foco = int(foco.get("dias_ativos", 0) or 0)
        consistencia = float(dados.get("consistencia_percentual", 0) or 0)
        consistencia_anterior = float(dados.get("consistencia_anterior", 0) or 0)
        self.minha_consistencia.setText(
            f"{dias_foco}/{dias} dias"
        )
        self.minha_consistencia_detalhe.setText(
            (
                f"{consistencia:.0f}% do período global • "
                + self.formatar_variacao_minha_evolucao(
                    consistencia - consistencia_anterior
                )
                + " vs. anterior"
            )
        )

        sessoes_foco = int(foco.get("sessoes", 0) or 0)
        self.minha_sessoes_foco.setText(
            str(sessoes_foco)
        )
        self.minha_sessoes_foco_detalhe.setText(
            (
                f"{int(foco.get('concluidas', 0) or 0)} concluída(s) • média "
                + formatar_tempo_foco_resumido(
                    int(foco.get("media_sessao", 0) or 0)
                )
            )
        )

        revisoes_periodo = int(dados.get("revisoes_periodo", 0) or 0)
        revisoes_anterior = int(dados.get("revisoes_anterior", 0) or 0)
        self.minha_revisoes_periodo.setText(
            str(revisoes_periodo)
        )
        self.minha_revisoes_periodo_detalhe.setText(
            (
                f"{dados.get('revisoes_legacy_excluidas', 0)} legado(s) sem concurso excluído(s)"
                if dados.get("revisoes_estado") == "legacy_limited"
                else self.formatar_variacao_volume_historica(
                    revisoes_periodo,
                    revisoes_anterior
                )
            )
        )

        prazo = dados.get("prazos_revisao") or {}
        prazo_ant = prazo.get("anterior") or {}
        total_prazo = int(prazo.get("total_com_prazo") or 0)
        pct_prazo = prazo.get("percentual_no_prazo")
        self.minha_prazo_pct.setText("—" if pct_prazo is None else f"{float(pct_prazo):.0f}%")
        self.minha_prazo_total.setText(str(total_prazo))
        atraso_medio = prazo.get("atraso_medio_dias")
        self.minha_prazo_atraso.setText("—" if atraso_medio is None else f"{float(atraso_medio):.1f} d".replace(".", ","))
        self.minha_prazo_atrasadas.setText(str(int(prazo.get("atrasadas") or 0)))
        self.minha_prazo_pct_detalhe.setText("concluídas na data prevista ou antes")
        self.minha_prazo_atraso_detalhe.setText("considera apenas conclusões atrasadas")
        self.minha_prazo_atrasadas_detalhe.setText("registros com prazo histórico válido")
        if total_prazo:
            ant_pct = prazo_ant.get("percentual_no_prazo")
            detalhe = f"{int(prazo.get('no_prazo') or 0)} de {total_prazo} revisão(ões)"
            if ant_pct is not None and pct_prazo is not None:
                detalhe += " • " + self.formatar_variacao_minha_evolucao(float(pct_prazo) - float(ant_pct)) + " vs. anterior"
            self.minha_prazo_amostra.setText(detalhe)
        else:
            self.minha_prazo_amostra.setText("Sem amostra válida neste período")

        # Insights. Tópicos comparáveis têm preferência; na falta deles,
        # a leitura recua para a disciplina para não inventar granularidade.
        ganho_topico = dados.get("maior_evolucao_topico")
        ganho = dados.get("maior_evolucao")
        if ganho_topico and float(ganho_topico.get("variacao") or 0) > 0:
            self.minha_ganho.setText(
                f"{ganho_topico.get('disciplina', '—')} › {ganho_topico.get('topico', '—')}"
            )
            self.minha_ganho_detalhe.setText(
                self.formatar_variacao_minha_evolucao(
                    ganho_topico.get("variacao")
                )
                + f" • {ganho_topico.get('questoes', 0)} questões"
            )
        elif ganho and float(ganho.get("variacao") or 0) > 0:
            self.minha_ganho.setText(
                ganho.get("disciplina", "—")
            )
            self.minha_ganho_detalhe.setText(
                self.formatar_variacao_minha_evolucao(
                    ganho.get("variacao")
                )
            )
        else:
            self.minha_ganho.setText(
                "Base ainda insuficiente"
            )
            self.minha_ganho_detalhe.setText(
                "São necessárias amostras comparáveis nos dois períodos."
            )

        queda_topico = dados.get("maior_queda_topico")
        queda = dados.get("maior_queda")
        fraca = dados.get("menor_dominio")
        if queda_topico and float(queda_topico.get("variacao") or 0) < 0:
            self.minha_atencao.setText(
                f"{queda_topico.get('disciplina', '—')} › {queda_topico.get('topico', '—')}"
            )
            self.minha_atencao_detalhe.setText(
                self.formatar_variacao_minha_evolucao(
                    queda_topico.get("variacao")
                )
                + " vs. período anterior"
            )
        elif queda and float(queda.get("variacao") or 0) < 0:
            self.minha_atencao.setText(
                queda.get("disciplina", "—")
            )
            self.minha_atencao_detalhe.setText(
                self.formatar_variacao_minha_evolucao(
                    queda.get("variacao")
                )
                + " no período"
            )
        elif fraca:
            self.minha_atencao.setText(
                fraca.get("disciplina", "—")
            )
            self.minha_atencao_detalhe.setText(
                (
                    f"Domínio médio {float(fraca.get('dominio') or 0):.0f}/100 • "
                    f"{fraca.get('nivel', '—')}"
                )
            )
        else:
            self.minha_atencao.setText(
                "Sem evidência suficiente"
            )
            self.minha_atencao_detalhe.setText(
                "Resolva mais questões para identificar tendências."
            )

        recuperadas = int(dados.get("recuperadas", 0) or 0)
        recorrentes = int(dados.get("erros_recorrentes", 0) or 0)
        self.minha_recuperacao.setText(
            (
                "1 questão recuperada"
                if recuperadas == 1
                else f"{recuperadas} questões recuperadas"
            )
        )
        self.minha_recuperacao_detalhe.setText(
            (
                "Nenhum erro recorrente aberto"
                if recorrentes == 0
                else (
                    "1 erro recorrente/crítico ainda aberto"
                    if recorrentes == 1
                    else f"{recorrentes} erros recorrentes/críticos ainda abertos"
                )
            )
        )

        disciplinas = dados.get("disciplinas", [])
        self.minha_contagem_disciplinas.setText(
            (
                "1 disciplina"
                if len(disciplinas) == 1
                else f"{len(disciplinas)} disciplinas"
            )
        )
        self.tabela_minha_evolucao.setRowCount(
            len(disciplinas)
        )

        for linha, item_d in enumerate(disciplinas):
            dominio_d = item_d.get("dominio")
            desempenho_d = item_d.get("desempenho")
            variacao_d = item_d.get("variacao")

            valores = [
                item_d.get("disciplina", "—"),
                (
                    f"{dominio_d:.0f}/100"
                    if dominio_d is not None
                    else "—"
                ),
                item_d.get("nivel", "—"),
                formatar_percentual(desempenho_d),
                self.formatar_variacao_minha_evolucao(variacao_d),
                str(item_d.get("questoes", 0)),
            ]

            for coluna, valor in enumerate(valores):
                tabela_item = QTableWidgetItem(valor)
                if coluna > 0:
                    tabela_item.setTextAlignment(Qt.AlignCenter)

                if coluna == 4 and variacao_d is not None:
                    if variacao_d >= 2.0:
                        aplicar_destaque_tabela(
                            tabela_item,
                            "sucesso",
                            False
                        )
                    elif variacao_d <= -2.0:
                        aplicar_destaque_tabela(
                            tabela_item,
                            "perigo",
                            False
                        )

                self.tabela_minha_evolucao.setItem(
                    linha,
                    coluna,
                    tabela_item
                )

            self.tabela_minha_evolucao.setRowHeight(
                linha,
                31
            )

        topicos = dados.get("topicos_tendencia", [])
        if hasattr(self, "minha_contagem_topicos"):
            self.minha_contagem_topicos.setText(
                "1 tópico" if len(topicos) == 1 else f"{len(topicos)} tópicos"
            )
        if hasattr(self, "tabela_minha_evolucao_topicos"):
            self.tabela_minha_evolucao_topicos.setRowCount(len(topicos))
            for linha, item_t in enumerate(topicos):
                dominio_t = item_t.get("dominio")
                desempenho_t = item_t.get("desempenho")
                variacao_t = item_t.get("variacao")
                valores_t = [
                    item_t.get("disciplina", "—"),
                    item_t.get("topico", "—"),
                    f"{dominio_t:.0f}/100" if dominio_t is not None else "—",
                    formatar_percentual(desempenho_t),
                    self.formatar_variacao_minha_evolucao(variacao_t),
                    str(item_t.get("questoes", 0)),
                ]
                for coluna, valor in enumerate(valores_t):
                    tabela_item = QTableWidgetItem(valor)
                    if coluna >= 2:
                        tabela_item.setTextAlignment(Qt.AlignCenter)
                    if coluna == 4 and variacao_t is not None:
                        if variacao_t >= 2.0:
                            aplicar_destaque_tabela(tabela_item, "sucesso", False)
                        elif variacao_t <= -2.0:
                            aplicar_destaque_tabela(tabela_item, "perigo", False)
                    self.tabela_minha_evolucao_topicos.setItem(
                        linha, coluna, tabela_item
                    )
                self.tabela_minha_evolucao_topicos.setRowHeight(linha, 31)

        self.atualizar_grafico_minha_evolucao()
        if hasattr(self, "painel_estatisticas_premium"):
            self.painel_estatisticas_premium.definir_periodo(
                self.combo_periodo_minha_evolucao.currentText()
            )
            # O quadro inferior usa o MESMO ranking oficial da aba Pontos fracos.
            # TTL impede consultas extras em navegações normais entre telas.
            chave_fracos = f"estatisticas:fracos:{int(concurso[0])}"
            try:
                pontos_fracos = self.cache_analitico.obter(
                    chave_fracos,
                    lambda: listar_ranking_topicos(limite=25, ordem="asc"),
                    ttl=12,
                )
            except Exception:
                # Falhas na lista resumida não bloqueiam o histórico principal.
                pontos_fracos = []
            self.painel_estatisticas_premium.atualizar(
                dados, pontos_fracos=pontos_fracos
            )
        if hasattr(self, "_estado_estatisticas"):
            self._estado_estatisticas.marcar_limpa("Histórico")


    def _nome_aba_estatisticas_atual(self):
        if not hasattr(self, "abas_estatisticas"):
            return "Histórico"
        indice = self.abas_estatisticas.currentIndex()
        if indice < 0:
            return "Histórico"
        return self.abas_estatisticas.tabText(indice)

    def _selecionar_aba_estatisticas(self, nome_aba):
        if not nome_aba or not hasattr(self, "abas_estatisticas"):
            return
        for indice in range(self.abas_estatisticas.count()):
            if self.abas_estatisticas.tabText(indice) == nome_aba:
                self.abas_estatisticas.setCurrentIndex(indice)
                return

    def abrir_estatisticas(self, aba=None):
        self._garantir_tela_estatisticas()
        # Selecionar a aba antes de exibir a tela evita um ciclo de pintura extra.
        if aba:
            self._selecionar_aba_estatisticas(aba)

        # A única validação de perfil necessária na entrada fica aqui. Depois
        # disso, alternar abas usa apenas o estado em memória e não toca no banco.
        try:
            concurso = obter_concurso_ativo()
            concurso_id = int(concurso[0])
            if self._estado_estatisticas.concurso_id != concurso_id:
                self._estado_estatisticas.trocar_concurso(concurso_id)
                self.cache_analitico.invalidar("estatisticas:")
            if hasattr(self, "perfil_estatisticas"):
                self.perfil_estatisticas.setText(f"Perfil: {concurso[1]}")
        except Exception:
            pass

        # Navegação primeiro; cálculo somente se o snapshot visível estiver sujo.
        self.telas.setCurrentWidget(self.tela_estatisticas)
        self._agendar_atualizacao_estatisticas()

    def _obter_resumo_estatisticas(self, concurso_id, hoje):
        chave = f"estatisticas:resumo:{int(concurso_id)}:{hoje}"

        def carregar():
            disciplinas = obter_estatisticas_disciplinas(hoje)
            metricas_globais = self.cache_analitico.obter(
                f"nucleo:global:{int(concurso_id)}:all",
                lambda: obter_metricas_globais_nucleo(concurso_id),
                ttl=30,
            )
            return disciplinas, metricas_globais

        return self.cache_analitico.obter(chave, carregar, ttl=12)

    def _atualizar_resumo_estatisticas(self, concurso, hoje, forcar=False):
        if not forcar and not self._estado_estatisticas.resumo_sujo:
            return None

        inicio = time.perf_counter()
        if forcar:
            self.cache_analitico.invalidar(
                f"estatisticas:resumo:{int(concurso[0])}:"
            )
        disciplinas, metricas_globais = self._obter_resumo_estatisticas(
            concurso[0], hoje
        )

        total_topicos = sum(item[1] for item in disciplinas)
        total_revisoes = sum(item[2] for item in disciplinas)
        total_questoes = sum(item[4] for item in disciplinas)
        total_atrasadas = sum(item[5] for item in disciplinas)
        total_hoje = sum(item[6] for item in disciplinas)
        media_disciplinas = (
            metricas_globais.get("metrics", {})
            .get("accuracy_rate", {})
            .get("value")
        )

        self.estat_total_topicos.setText(str(total_topicos))
        self.estat_total_revisoes.setText(str(total_revisoes))
        self.estat_total_questoes.setText(str(total_questoes))
        self.estat_media.setText(formatar_percentual(media_disciplinas))
        self.estat_atrasadas.setText(str(total_atrasadas))
        self.estat_hoje.setText(str(total_hoje))

        self._estado_estatisticas.marcar_resumo_limpo()
        self._estado_estatisticas.registrar_duracao(
            "Resumo", (time.perf_counter() - inicio) * 1000.0
        )
        return disciplinas

    def _atualizar_aba_estatisticas_disciplinas(self, concurso, hoje):
        inicio = time.perf_counter()
        disciplinas, _ = self._obter_resumo_estatisticas(concurso[0], hoje)
        quantidade_disciplinas = len(disciplinas)
        self.estat_contagem_disciplinas.setText(
            "1 disciplina"
            if quantidade_disciplinas == 1
            else f"{quantidade_disciplinas} disciplinas"
        )

        tabela = self.tabela_estat_disciplinas
        tabela.setUpdatesEnabled(False)
        tabela.blockSignals(True)
        try:
            tabela.setRowCount(quantidade_disciplinas)
            for linha, dado in enumerate(disciplinas):
                valores = [
                    dado[0], str(dado[1]), str(dado[2]),
                    formatar_percentual(dado[3]), str(dado[4]),
                    str(dado[5]), str(dado[6]),
                ]
                for coluna, valor in enumerate(valores):
                    item = QTableWidgetItem(valor)
                    if coluna in (1, 2, 3, 4, 5, 6):
                        item.setTextAlignment(Qt.AlignCenter)
                    if coluna == 5 and dado[5] > 0:
                        aplicar_destaque_tabela(item, "perigo", True)
                    if coluna == 6 and dado[6] > 0:
                        aplicar_destaque_tabela(item, "atencao", True)
                    tabela.setItem(linha, coluna, item)
                tabela.setRowHeight(linha, 31)
        finally:
            tabela.blockSignals(False)
            tabela.setUpdatesEnabled(True)

        self._estado_estatisticas.registrar_duracao(
            "Disciplinas", (time.perf_counter() - inicio) * 1000.0
        )

    def _atualizar_aba_estatisticas_fracos(self, concurso_id, forcar=False):
        inicio = time.perf_counter()
        chave = f"estatisticas:fracos:{int(concurso_id)}"
        if forcar:
            self.cache_analitico.invalidar(chave)
        fracos = self.cache_analitico.obter(
            chave,
            lambda: listar_ranking_topicos(limite=25, ordem="asc"),
            ttl=12,
        )
        self.dados_estat_fracos = fracos
        quantidade_fracos = len(fracos)
        self.estat_contagem_fracos.setText(
            "1 tópico" if quantidade_fracos == 1 else f"{quantidade_fracos} tópicos"
        )

        tabela = self.tabela_fracos
        tabela.setUpdatesEnabled(False)
        tabela.blockSignals(True)
        try:
            tabela.setRowCount(quantidade_fracos)
            for linha, dado in enumerate(fracos):
                evidencia = str(dado[7] if len(dado) > 7 else "insufficient")
                desempenho = formatar_percentual(dado[4])
                if evidencia == "low":
                    desempenho += " · prov."
                valores = [
                    dado[1], dado[2], str(dado[3]),
                    desempenho,
                    formatar_data(dado[6]), formatar_data(dado[5]),
                ]
                for coluna, valor in enumerate(valores):
                    item = QTableWidgetItem(valor)
                    if coluna == 1:
                        item.setData(Qt.UserRole, dado[0])
                    if coluna in (2, 3, 4, 5):
                        item.setTextAlignment(Qt.AlignCenter)
                    if coluna == 3 and dado[4] is not None:
                        if evidencia == "low":
                            aplicar_destaque_tabela(item, "atencao", False)
                            item.setToolTip(
                                "Evidência baixa: domínio provisório, ainda não "
                                "classificado como fraqueza definitiva."
                            )
                        elif dado[4] < 60:
                            aplicar_destaque_tabela(item, "perigo", True)
                        elif dado[4] < 70:
                            aplicar_destaque_tabela(item, "alerta", True)
                        elif dado[4] < 80:
                            aplicar_destaque_tabela(item, "atencao", True)
                    tabela.setItem(linha, coluna, item)
                tabela.setRowHeight(linha, 31)
        finally:
            tabela.blockSignals(False)
            tabela.setUpdatesEnabled(True)

        self._estado_estatisticas.registrar_duracao(
            "Pontos fracos", (time.perf_counter() - inicio) * 1000.0
        )

    def _atualizar_aba_estatisticas_recentes(self, concurso_id, forcar=False):
        inicio = time.perf_counter()
        chave = f"estatisticas:recentes:{int(concurso_id)}"
        if forcar:
            self.cache_analitico.invalidar(chave)
        recentes = self.cache_analitico.obter(
            chave,
            lambda: listar_revisoes_recentes(limite=40),
            ttl=12,
        )
        self.dados_estat_recentes = recentes
        quantidade_recentes = len(recentes)
        self.estat_contagem_recentes.setText(
            "1 revisão"
            if quantidade_recentes == 1
            else f"{quantidade_recentes} revisões"
        )

        tabela = self.tabela_recentes
        tabela.setUpdatesEnabled(False)
        tabela.blockSignals(True)
        try:
            tabela.setRowCount(quantidade_recentes)
            for linha, dado in enumerate(recentes):
                valores = [
                    formatar_data(dado[2]), dado[3], dado[4],
                    str(dado[5]), str(dado[6]), formatar_percentual(dado[7]),
                ]
                for coluna, valor in enumerate(valores):
                    item = QTableWidgetItem(valor)
                    if coluna == 2:
                        item.setData(Qt.UserRole, dado[1])
                    if coluna in (0, 3, 4, 5):
                        item.setTextAlignment(Qt.AlignCenter)
                    if coluna == 5 and dado[7] is not None:
                        if dado[7] < 60:
                            aplicar_destaque_tabela(item, "perigo", False)
                        elif dado[7] >= 90:
                            aplicar_destaque_tabela(item, "sucesso", False)
                    tabela.setItem(linha, coluna, item)
                tabela.setRowHeight(linha, 31)
        finally:
            tabela.blockSignals(False)
            tabela.setUpdatesEnabled(True)

        self._estado_estatisticas.registrar_duracao(
            "Revisões recentes", (time.perf_counter() - inicio) * 1000.0
        )

    def atualizar_estatisticas(self, forcar=False):
        """Atualiza somente a aba de Estatísticas atualmente visível.

        Abas limpas saem antes de qualquer consulta ao perfil/banco. Esse fast
        path complementa o pré-carregamento do startup e elimina verificações
        redundantes durante a navegação normal.
        """
        if self._estatisticas_refresh_em_andamento:
            return
        if not hasattr(self, "abas_estatisticas"):
            return
        if not self._estatisticas_visivel_precisa_atualizacao(forcar=forcar):
            return

        self._estatisticas_refresh_em_andamento = True
        try:
            hoje = QDate.currentDate().toString("yyyy-MM-dd")
            concurso = obter_concurso_ativo()
            if self._estatisticas_data_referencia != hoje:
                self._estatisticas_data_referencia = hoje
                self._estado_estatisticas.marcar_sujas()
                self.cache_analitico.invalidar("estatisticas:")
            trocou_concurso = self._estado_estatisticas.trocar_concurso(concurso[0])
            if trocou_concurso:
                # As chaves possuem concurso_id, mas limpar o prefixo evita
                # acumular snapshots de perfis alternados durante a sessão.
                self.cache_analitico.invalidar("estatisticas:")

            if hasattr(self, "perfil_estatisticas"):
                self.perfil_estatisticas.setText(f"Perfil: {concurso[1]}")

            self._atualizar_resumo_estatisticas(concurso, hoje, forcar=forcar)

            aba = self._nome_aba_estatisticas_atual()
            if not forcar and not self._estado_estatisticas.precisa_atualizar(aba):
                return

            inicio = time.perf_counter()
            if aba == "Histórico" and hasattr(self, "tabela_minha_evolucao"):
                self.atualizar_minha_evolucao(forcar=forcar)
            elif aba == "Regularidade" and hasattr(self, "tabela_regularidade_semanas"):
                self._atualizar_aba_regularidade(forcar=forcar)
            elif aba == "Conquistas" and hasattr(self, "tabela_gamificacao_conquistas"):
                self._atualizar_aba_conquistas(concurso[0], forcar=forcar)
            elif aba == "Algoritmo" and hasattr(self, "lab_tabela"):
                self.atualizar_laboratorio_algoritmo()
            elif aba == "Disciplinas" and hasattr(self, "tabela_estat_disciplinas"):
                self._atualizar_aba_estatisticas_disciplinas(concurso, hoje)
            elif aba == "Mapa de domínio" and hasattr(self, "tabela_mapa_dominio"):
                self._atualizar_aba_mapa_dominio(concurso[0], forcar=forcar)
            elif aba == "Pontos fracos" and hasattr(self, "tabela_fracos"):
                self._atualizar_aba_estatisticas_fracos(concurso[0], forcar=forcar)
            elif aba == "Revisões recentes" and hasattr(self, "tabela_recentes"):
                self._atualizar_aba_estatisticas_recentes(concurso[0], forcar=forcar)
            elif aba == "Tendências" and hasattr(self, "combo_periodo_evolucao"):
                self.atualizar_evolucao_temporal(forcar=forcar)
            elif aba == "Progresso" and hasattr(self, "tabela_progresso_topicos"):
                if forcar:
                    self.cache_analitico.invalidar(
                        f"progresso:v2:{int(concurso[0])}"
                    )
                self.atualizar_progresso_edital()

            self._estado_estatisticas.marcar_limpa(aba)
            self._estado_estatisticas.registrar_duracao(
                f"aba:{aba}", (time.perf_counter() - inicio) * 1000.0
            )
        finally:
            self._estatisticas_refresh_em_andamento = False


    def abrir_topico_estatistica_fraco(
        self,
        linha,
        coluna
    ):
        item = self.tabela_fracos.item(
            linha,
            1
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )

        janela = JanelaTopico(
            topico_id,
            item.text(),
            self
        )

        janela.exec()

        self.invalidar_estatisticas("all")

    def abrir_topico_estatistica_recente(
        self,
        linha,
        coluna
    ):
        item = self.tabela_recentes.item(
            linha,
            2
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )

        janela = JanelaTopico(
            topico_id,
            item.text(),
            self
        )

        janela.exec()

        self.invalidar_estatisticas("all")

    def criar_mini_indicador_disciplina(
        self,
        titulo
    ):
        quadro = QFrame()
        quadro.setObjectName(
            "miniStat"
        )

        layout = QVBoxLayout(
            quadro
        )
        layout.setContentsMargins(
            12,
            8,
            12,
            8
        )
        layout.setSpacing(
            1
        )

        rotulo = QLabel(
            titulo
        )
        rotulo.setObjectName(
            "miniStatLabel"
        )

        valor = QLabel(
            "—"
        )
        valor.setObjectName(
            "miniStatValue"
        )

        layout.addWidget(
            rotulo
        )
        layout.addWidget(
            valor
        )

        return quadro, valor

    def criar_tela_disciplina(self):
        tela = QWidget()

        layout = QVBoxLayout(
            tela
        )

        layout.setContentsMargins(
            28,
            20,
            28,
            24
        )

        layout.setSpacing(
            12
        )

        # ====================================================
        # CABEÇALHO
        # ====================================================

        cabecalho = QHBoxLayout()
        cabecalho.setSpacing(
            10
        )

        voltar = QPushButton(
            "← Voltar"
        )
        voltar.setObjectName(
            "subtleButton"
        )
        voltar.setProperty(
            "navigationBack",
            True
        )
        voltar.setFixedWidth(
            88
        )
        voltar.clicked.connect(
            self._voltar_da_disciplina
        )

        cabecalho.addWidget(
            voltar
        )

        bloco_titulo = QVBoxLayout()
        bloco_titulo.setSpacing(
            1
        )

        self.titulo_disciplina = QLabel()
        self.titulo_disciplina.setObjectName(
            "pageTitle"
        )

        subtitulo_disciplina = QLabel(
            "Organize os tópicos e acompanhe o progresso desta disciplina."
        )
        subtitulo_disciplina.setObjectName(
            "pageSubtitle"
        )

        bloco_titulo.addWidget(
            self.titulo_disciplina
        )
        bloco_titulo.addWidget(
            subtitulo_disciplina
        )

        cabecalho.addLayout(
            bloco_titulo
        )
        cabecalho.addStretch()

        # A ação principal da disciplina recebe destaque próprio. Comandos de
        # manutenção menos frequentes ficam concentrados no menu compacto ao lado.
        self.botao_adicionar_topico = QPushButton("Adicionar tópico")
        self.botao_adicionar_topico.setObjectName("primaryButton")
        self.botao_adicionar_topico.setFixedHeight(42)
        self.botao_adicionar_topico.setMinimumWidth(174)
        self.botao_adicionar_topico.setToolTip(
            "Adicionar um novo título/tópico à disciplina atual."
        )
        self.botao_adicionar_topico.clicked.connect(self.novo_topico)

        self.botao_mais_disciplina = QPushButton("⋯")
        self.botao_mais_disciplina.setObjectName("subtleButton")
        self.botao_mais_disciplina.setFixedSize(44, 42)
        self.botao_mais_disciplina.setAccessibleName("Mais ações da disciplina")
        self.botao_mais_disciplina.setToolTip("Mais ações da disciplina")

        self.menu_disciplina = QMenu(self.botao_mais_disciplina)
        self.acao_questoes_arquivadas_disciplina = self.menu_disciplina.addAction(
            "Questões arquivadas"
        )
        self.acao_questoes_arquivadas_disciplina.triggered.connect(
            self.abrir_questoes_desativadas_disciplina_atual
        )
        self.acao_lixeira_disciplina = self.menu_disciplina.addAction("Lixeira")
        self.acao_lixeira_disciplina.triggered.connect(
            lambda: JanelaLixeiraQuestoes(self).exec()
        )
        self.menu_disciplina.addSeparator()
        self.acao_estado_disciplina = self.menu_disciplina.addAction(
            "Desligar disciplina"
        )
        self.acao_estado_disciplina.triggered.connect(
            self.alternar_estado_disciplina_atual
        )
        self.botao_mais_disciplina.setMenu(self.menu_disciplina)

        # Controles mantidos apenas como proxies internos para preservar
        # compatibilidade com rotinas legadas. Eles precisam ter um pai oculto:
        # um QWidget/QPushButton criado sem parent vira uma janela top-level e,
        # se alguma rotina chamar setVisible(True), pode aparecer como uma
        # pequena janela flutuante sobre a disciplina.
        self._proxies_disciplina = QWidget(tela)
        self._proxies_disciplina.setObjectName("disciplineLegacyProxyContainer")
        self._proxies_disciplina.setVisible(False)

        self.botao_estado_disciplina = QPushButton(
            "Desligar disciplina", self._proxies_disciplina
        )
        self.botao_estado_disciplina.setVisible(False)
        self.botao_estado_disciplina.clicked.connect(
            self.alternar_estado_disciplina_atual
        )

        self.botao_capitulos = QPushButton(
            "Capítulos", self._proxies_disciplina
        )
        self.botao_capitulos.setObjectName("toolbarButton")
        self.botao_capitulos.setFixedHeight(34)
        self.botao_capitulos.setEnabled(False)
        self.botao_capitulos.setToolTip(
            "Adicionar, renomear ou desligar capítulos do tópico selecionado."
        )
        self.botao_capitulos.clicked.connect(
            self.abrir_capitulos_topico_selecionado
        )

        renomear = QPushButton("Renomear", self._proxies_disciplina)
        renomear.setObjectName("toolbarButton")
        renomear.setFixedHeight(34)
        renomear.setToolTip("Renomear o tópico selecionado.")
        renomear.clicked.connect(self.renomear_topico_selecionado)

        self.botao_estado_topico = QPushButton(
            "Desligar tópico", self._proxies_disciplina
        )
        self.botao_estado_topico.setObjectName("toolbarButton")
        self.botao_estado_topico.setFixedHeight(34)
        self.botao_estado_topico.setToolTip(
            "Desliga temporariamente o tópico no perfil atual, sem apagar histórico, agenda ou questões."
        )
        self.botao_estado_topico.clicked.connect(
            self.alternar_estado_topico_selecionado
        )

        excluir = QPushButton("Excluir", self._proxies_disciplina)
        excluir.setObjectName("dangerButton")
        excluir.setFixedHeight(34)
        excluir.setToolTip(
            "Excluir permanentemente o título/tópico ou capítulo selecionado."
        )
